DEBUG_LEVEL = 0
DEBUG_COMPONENTS: List[str] = []

def _filter_kwargs(kwargs: Dict[str, Any]) -> Dict[str, Any]:
    """Entfernt problematische Schluesselwortargumente aus einem kwargs-Dictionary."""
    filtered = kwargs.copy()
    filtered.pop("key_threadpool", None)
    filtered.pop("_pool", None)
    keys_to_remove = [k for k in filtered if k.startswith("_")]
    for key in keys_to_remove:
        filtered.pop(key, None)
    return filtered


def _should_patch() -> bool:
    """Prueft dynamisch und absolut robust, ob der urllib3‑Monkey‑Patch benoetigt wird."""

    def _debug(msg: str) -> None:
        """Gibt eine Debug‑Meldung aus, falls Debugging aktiv ist."""
        try:
            if DEBUG_LEVEL >= 3 or "monkey" in DEBUG_COMPONENTS:
                if "log_debug" in globals():
                    log_debug("monkey", msg)
                else:
                    logger.debug(f"[monkey] {msg}")
        except (NameError, AttributeError):
            pass

    try:
        import urllib3.connectionpool
    except ImportError:
        _debug("urllib3 nicht installiert, Patch ueberfluessig.")
        return False
    if not hasattr(urllib3.connectionpool, "PoolKey"):
        _debug("PoolKey nicht vorhanden, Patch ueberfluessig.")
        return False
    try:
        urllib3.connectionpool.PoolKey(
            host="localhost",
            port=80,
            request_context={},
            key_threadpool="dummy",
        )
    except TypeError as e:
        if "key_threadpool" in str(e):
            _debug("TypeError wegen key_threadpool erkannt – Patch wird angewendet.")
            return True
        _debug(f"TypeError, aber nicht key_threadpool: {e}")
        return False
    except Exception as e:
        _debug(f"Unerwarteter Fehler beim Testen: {e}")
        return False
    else:
        _debug("urllib3 akzeptiert key_threadpool – Patch überflüssig.")
        return False


# ── Globale Referenzen für den Monkey‑Patch ──────────────────────
_original_pool_init: Optional[Callable] = None
_original_proxy_init: Optional[Callable] = None
_original_poolkey_new: Optional[Callable] = None
_original_poolkey_init: Optional[Callable] = None
_original_connection_from_pool_key: Optional[Callable] = None
_original_container_init: Optional[Callable] = None
_original_urlopen: Optional[Callable] = None
_patch_applied = False


def _apply_patches() -> None:
    """Führt alle Monkey‑Patches durch (intern)."""
    global _original_pool_init, _original_proxy_init, _original_poolkey_new
    global _original_poolkey_init, _original_connection_from_pool_key
    global _original_container_init, _original_urlopen, _patch_applied
    if _patch_applied:
        return
    import urllib3._collections
    import urllib3.connection
    import urllib3.connectionpool
    import urllib3.poolmanager

    # ── PoolManager.__init__ ─────────────────────────────────────
    _original_pool_init = urllib3.poolmanager.PoolManager.__init__

    def _patched_pool_init(self: Any, *args: Any, **kwargs: Any) -> None:
        filtered = _filter_kwargs(kwargs)
        _original_pool_init(self, *args, **filtered)  # type: ignore[call-arg]

    urllib3.poolmanager.PoolManager.__init__ = _patched_pool_init  # type: ignore[method-assign]

    # ── ProxyManager.__init__ (falls vorhanden) ───────────────────
    if hasattr(urllib3.poolmanager, "ProxyManager"):
        _original_proxy_init = urllib3.poolmanager.ProxyManager.__init__

        def _patched_proxy_init(self: Any, *args: Any, **kwargs: Any) -> None:
            filtered = _filter_kwargs(kwargs)
            _original_proxy_init(self, *args, **filtered)  # type: ignore[call-arg]

        urllib3.poolmanager.ProxyManager.__init__ = _patched_proxy_init  # type: ignore[method-assign]

    # ── PoolKey.__new__ ──────────────────────────────────────────
    if hasattr(urllib3.connectionpool, "PoolKey"):
        _original_poolkey_new = urllib3.connectionpool.PoolKey.__new__  # type: ignore[attr-defined]

        @staticmethod
        def _patched_poolkey_new(cls: type, *args: Any, **kwargs: Any) -> Any:
            filtered = _filter_kwargs(kwargs)
            return _original_poolkey_new(cls, *args, **filtered)  # type: ignore[call-arg]

        urllib3.connectionpool.PoolKey.__new__ = _patched_poolkey_new  # type: ignore[attr-defined,assignment]

    # ── PoolKey.__init__ ─────────────────────────────────────────
    if hasattr(urllib3.connectionpool, "PoolKey") and hasattr(
        urllib3.connectionpool.PoolKey, "__init__"
    ):
        _original_poolkey_init = urllib3.connectionpool.PoolKey.__init__  # type: ignore[attr-defined]

        def _patched_poolkey_init(self: Any, *args: Any, **kwargs: Any) -> None:
            filtered = _filter_kwargs(kwargs)
            _original_poolkey_init(self, *args, **filtered)  # type: ignore[call-arg]

        urllib3.connectionpool.PoolKey.__init__ = _patched_poolkey_init  # type: ignore[attr-defined,assignment]

    # ── PoolManager.connection_from_pool_key ──────────────────────
    if hasattr(urllib3.poolmanager.PoolManager, "connection_from_pool_key"):
        _original_connection_from_pool_key = (
            urllib3.poolmanager.PoolManager.connection_from_pool_key
        )

        def _patched_connection_from_pool_key(
            self: Any, pool_key: Any, request_context: Optional[Any] = None
        ) -> Any:
            return _original_connection_from_pool_key(self, pool_key, request_context)  # type: ignore[call-arg]

        urllib3.poolmanager.PoolManager.connection_from_pool_key = (
            _patched_connection_from_pool_key
        )  # type: ignore[method-assign]

    # ── RecentlyUsedContainer.__init__ ────────────────────────────
    if hasattr(urllib3._collections, "RecentlyUsedContainer"):
        _original_container_init = urllib3._collections.RecentlyUsedContainer.__init__

        def _patched_container_init(self: Any, *args: Any, **kwargs: Any) -> None:
            filtered = _filter_kwargs(kwargs)
            _original_container_init(self, *args, **filtered)  # type: ignore[call-arg]

        urllib3._collections.RecentlyUsedContainer.__init__ = _patched_container_init  # type: ignore[method-assign]

    # ── ConnectionPool.urlopen ────────────────────────────────────
    if hasattr(urllib3.connectionpool, "ConnectionPool"):
        _original_urlopen = urllib3.connectionpool.ConnectionPool.urlopen  # type: ignore[attr-defined]

        def _patched_urlopen(
            self: Any, method: str, url: str, *args: Any, **kwargs: Any
        ) -> Any:
            filtered = _filter_kwargs(kwargs)
            return _original_urlopen(self, method, url, *args, **filtered)  # type: ignore[call-arg]

        urllib3.connectionpool.ConnectionPool.urlopen = _patched_urlopen  # type: ignore[attr-defined,assignment]

    _patch_applied = True
    logger.debug("[monkey] urllib3 monkey-patch applied successfully")


def apply() -> None:
    """Wendet den urllib3‑Monkey‑Patch an, falls erforderlich."""
    global _patch_applied

    def _debug(msg: str) -> None:
        """Sichere Debug‑Ausgabe."""
        try:
            if DEBUG_LEVEL >= 3 or "monkey" in DEBUG_COMPONENTS:
                if "log_debug" in globals():
                    log_debug("monkey", msg)
                else:
                    logger.debug(f"[monkey] {msg}")
        except (NameError, AttributeError):
            try:
                if not QUIET_MODE:
                    print(f"[monkey] {msg}")
            except Exception:
                pass

    def _warn(msg: str) -> None:
        """Sichere Warnungs‑Ausgabe."""
        try:
            logger.warning(msg)
        except (NameError, AttributeError):
            print(f"WARNING: {msg}")

    if _patch_applied:
        _debug("urllib3‑Patch wurde bereits angewendet.")
        return

    try:
        if not _should_patch():
            return
    except Exception as e:
        _warn(f"Fehler in _should_patch(): {e} – Patch wird nicht angewendet.")
        return

    try:
        _apply_patches()
        _patch_applied = True
        _debug("urllib3 monkey‑patch erfolgreich angewendet.")
    except Exception as e:
        _warn(
            f"urllib3 monkey‑patch konnte nicht angebracht werden: {e}. "
            "Das Programm funktioniert trotzdem, aber es könnte zu "
            "Problemen mit urllib3 >= 2.0 kommen."
        )
        _patch_applied = False


def unpatch() -> None:
    """Entfernt den urllib3 Monkey‑Patch und stellt die Originalmethoden wieder her."""
    global _patch_applied
    if not _patch_applied:
        return
    import urllib3._collections
    import urllib3.connection
    import urllib3.connectionpool
    import urllib3.poolmanager
    try:
        if _original_urlopen is not None:
            urllib3.connectionpool.ConnectionPool.urlopen = _original_urlopen  # type: ignore[attr-defined,assignment]
    except Exception:
        pass
    try:
        if _original_container_init is not None:
            urllib3._collections.RecentlyUsedContainer.__init__ = (
                _original_container_init
            )  # type: ignore[method-assign]
    except Exception:
        pass
    try:
        if _original_connection_from_pool_key is not None:
            urllib3.poolmanager.PoolManager.connection_from_pool_key = (
                _original_connection_from_pool_key
            )  # type: ignore[method-assign]
    except Exception:
        pass
    try:
        if _original_poolkey_init is not None:
            urllib3.connectionpool.PoolKey.__init__ = _original_poolkey_init  # type: ignore[attr-defined,assignment]
    except Exception:
        pass
    try:
        if _original_poolkey_new is not None:
            urllib3.connectionpool.PoolKey.__new__ = _original_poolkey_new  # type: ignore[attr-defined,assignment]
    except Exception:
        pass
    try:
        if _original_proxy_init is not None:
            urllib3.poolmanager.ProxyManager.__init__ = _original_proxy_init  # type: ignore[method-assign]
    except Exception:
        pass
    try:
        if _original_pool_init is not None:
            urllib3.poolmanager.PoolManager.__init__ = _original_pool_init  # type: ignore[method-assign]
    except Exception:
        pass
    _patch_applied = False
    try:
        if DEBUG_LEVEL >= 4:
            if "log_debug" in globals():
                log_debug("monkey", "urllib3 monkey-patch removed")
            else:
                logger.debug("[monkey] urllib3 monkey-patch removed")
    except NameError:
        pass


apply()
warnings.filterwarnings(
    "ignore", category=UserWarning, module="multiprocessing.resource_tracker"
)

