class ConfigDefaults:
    """
    Zentrale Konfigurationskonstanten für Dragon Whisperer.    """

    SAMPLE_RATE: int = 16000
    """Audio-Samplerate in Hz (16 kHz ist optimal für Whisper)."""

    CHANNELS: int = 1
    """Anzahl der Audiokanäle (1 = Mono, 2 = Stereo). Mono reicht für Whisper aus."""

    AUDIO_FORMAT: str = "s16le"
    """Rohaudio-Format (s16le = signed 16-bit little-endian)."""

    BYTES_PER_SAMPLE: int = 2
    """Bytes pro Sample (bei 16-bit = 2)."""

    DEFAULT_BEAM_SIZE: int = 10
    """Standard-Beam-Size für Whisper-Decodierung (höher = genauer, aber langsamer)."""

    DEFAULT_TEMPERATURE: float = 0.0
    """Temperatur für Whisper (0.0 = deterministisch, >0 = zufälliger)."""

    MAX_MEMORY_USAGE: int = 8 * 1024 * 1024 * 1024
    """Maximaler Arbeitsspeicher in Bytes (8 GB). Wird durch psutil überschrieben, falls verfügbar."""

    MAX_GUI_UPDATES_PER_SECOND: int = 60
    """Maximale GUI-Updates pro Sekunde (begrenzt die Auslastung des Hauptthreads)."""

    MAX_CACHE_SIZE: int = 500
    """Maximale Anzahl Einträge im Transkriptions-Cache (LRU)."""

    MAX_TEXT_LINES: int = 2000
    """Maximale Zeilen in den Text-Widgets (verhindert Speicherüberlauf)."""

    ENABLE_VAD_FILTER: bool = True
    """Voice Activity Detection standardmäßig aktivieren (entfernt Stille vor Transkription)."""

    MAX_CONSECUTIVE_ERRORS: int = 5
    """Maximale aufeinanderfolgende Fehler, bevor der Stream neu gestartet wird."""

    BASE_CHUNK_DURATION: int = 20
    """Standard-Chunk-Dauer in Sekunden (20s ist ein guter Kompromiss)."""

    MIN_CHUNK_DURATION: int = 2
    """Minimale Chunk-Dauer (kürzer = niedrigere Latenz, aber weniger Kontext)."""

    MAX_CHUNK_DURATION: int = 30
    """Maximale Chunk-Dauer (länger = mehr Kontext, aber höhere Latenz)."""

    CHUNK_OVERLAP: float = 2.0
    """Überlappung zwischen aufeinanderfolgenden Chunks in Sekunden (verhindert Informationsverlust an den Grenzen)."""

    STREAM_TIMEOUT: int = 25
    """Timeout für Stream-Verbindungen in Sekunden."""

    INITIAL_BUFFER_SECONDS: float = 2.0
    """Initiale Puffergröße in Sekunden (erlaubt einen flüssigen Start)."""

    MAX_EMPTY_READS: int = 30
    """Maximale Anzahl aufeinanderfolgender leerer Leseversuche, bevor ein Reconnect ausgelöst wird."""

    RECONNECT_DELAY: int = 2
    """Verzögerung vor einem Reconnect-Versuch in Sekunden."""

    READ_RETRY_DELAY: float = 0.1
    """Verzögerung zwischen Leseversuchen bei Timeout in Sekunden."""

    YOUTUBE_TIMEOUT: int = 10000000
    """YouTube-spezifisches Timeout in Mikrosekunden (10 Sekunden)."""

    NORMAL_TIMEOUT: int = 30000000
    """Normales Timeout für andere Streams in Mikrosekunden (30 Sekunden)."""

    MAX_STREAM_RECONNECTS: int = 5
    """Maximale Anzahl von Reconnect-Versuchen pro Stream."""

    STREAM_RECONNECT_DELAY: int = 2
    """Basisverzögerung zwischen Reconnects in Sekunden."""

    STREAM_RECONNECT_BACKOFF_FACTOR: float = 2.0
    """Exponentieller Backoff-Faktor für Reconnects."""

    READ_EMPTY_SLEEP_BASE: float = 0.1
    """Basis-Schlafzeit bei leeren Lesevorgängen."""

    READ_ERROR_BACKOFF_BASE: float = 0.1
    """Basis-Backoff bei Lese-Fehlern."""

    YOUTUBE_IDLE_TIMEOUT: int = 25
    """Inaktivitäts-Timeout für YouTube-Streams in Sekunden."""

    YOUTUBE_INITIAL_TIMEOUT: int = 25
    """Initiales Timeout für YouTube-Verbindungen."""

    YOUTUBE_URL_REFRESH_INTERVAL: int = 600
    """Intervall für das Aktualisieren der YouTube-Audio-URL in Sekunden (10 Minuten)."""

    YOUTUBE_URL_REFRESH_MAX_ATTEMPTS: int = 3
    """Maximale Versuche, eine frische YouTube-URL zu holen."""

    YOUTUBE_LOW_QUALITY_MAX_CHUNKS: int = 5
    """Anzahl der Chunks mit niedriger Qualität, bevor ein Fallback ausgelöst wird."""

    YOUTUBE_INITIAL_WAIT: float = 3.0
    """Wartezeit nach dem Start eines YouTube-Streams in Sekunden."""

    FFMPEG_START_WAIT: float = 1.5
    """Wartezeit nach dem Start von FFmpeg, bevor mit dem Lesen begonnen wird."""

    STREAM_TEST_TIMEOUT: int = 8
    """Timeout für den initialen Stream-Test in Sekunden."""

    YOUTUBE_STREAM_TEST_TIMEOUT: int = 8
    """YouTube-spezifischer Stream-Test-Timeout."""

    READ_WITH_TIMEOUT_SELECT_INTERVAL: float = 0.001
    """Intervall für select() bei Lesevorgängen mit Timeout."""

    READ_WITH_TIMEOUT_EMPTY_LOG_INTERVAL: int = 10
    """Log-Intervall für leere Lesevorgänge (Anzahl der Versuche)."""

    MAX_BACKOFF: int = 30
    """Maximale Backoff-Zeit in Sekunden."""

    BUFFER_FLUSH_INACTIVITY: float = 10.0
    """Inaktivitätszeit, nach der der Puffer geleert wird, in Sekunden."""

    BUFFER_FLUSH_TIMEOUT: float = 30.0
    """Timeout für Puffer-Leerung in Sekunden."""

    PROGRESS_UPDATE_INTERVAL: float = 0.5
    """Intervall für Fortschritts-Updates in Sekunden."""

    ERRORS_BEFORE_CHUNK_REDUCTION: int = 3
    """Anzahl der Fehler, bevor die Chunk-Dauer reduziert wird."""

    SUCCESSES_BEFORE_CHUNK_INCREASE: int = 5
    """Anzahl der Erfolge, bevor die Chunk-Dauer erhöht wird."""

    FFMPEG_BUFSIZE: str = "2048k"
    """FFmpeg Puffergröße (2 MB)."""

    FFMPEG_THREADS: int = 1
    """Anzahl der FFmpeg-Threads (1 = automatisch)."""

    FFMPEG_PROBESIZE: str = "32"
    """FFmpeg Probesize in MB (kleiner Wert für schnellere Initialisierung)."""

    FFMPEG_ANALYZE_DURATION: str = "0"
    """FFmpeg Analyze-Duration (0 = automatisch)."""

    AUDIO_ENHANCEMENT_ENABLED: bool = True
    """Audio-Enhancement standardmäßig aktivieren."""

    MIN_RMS_THRESHOLD: float = 0.002
    """Minimaler RMS-Wert, ab dem eine Verstärkung angewendet wird."""

    TARGET_RMS: float = 0.2
    """Ziel-RMS-Wert für die automatische Verstärkung."""

    MAX_GAIN: float = 5.0
    """Maximaler Verstärkungsfaktor."""

    CLIPPING_THRESHOLD: float = 0.9
    """Schwellwert für Clipping-Erkennung (0.9 = 90% des Maximalwerts)."""

    NOISEREDUCE_INTERVAL: int = 10
    """Intervall (Anzahl der Chunks) für die Anwendung von noisereduce."""

    NOISEREDUCE_MIN_LENGTH: int = 32000
    """Minimale Audio-Länge in Samples für noisereduce (2 Sekunden bei 16 kHz)."""

    AUDIO_ENHANCEMENT_MIN_LENGTH: int = 1600
    """Minimale Audio-Länge für Enhancement in Bytes."""

    LOW_QUALITY_CHUNK_THRESHOLD_FACTOR: float = 0.15
    """Faktor für die Erkennung niedriger Qualität (im Verhältnis zur erwarteten Dauer)."""

    LOW_QUALITY_CHUNK_LOG_LEVEL: int = 4
    """Log-Level für Low-Quality-Warnungen."""

    LOW_QUALITY_CHUNK_LOG_INTERVAL: int = 10
    """Intervall für Low-Quality-Logs (Anzahl der Chunks)."""

    DUPLICATE_CHECK_ENABLED: bool = False
    """Duplikaterkennung standardmäßig deaktiviert (spart CPU)."""

    RECENT_TRANSCRIPTIONS_SIZE: int = 10
    """Anzahl der letzten Transkriptionen, die für die Duplikatprüfung gespeichert werden."""

    MIN_TEXT_LENGTH: int = 3
    """Minimale Textlänge für die Duplikatprüfung (kürzere Texte werden ignoriert)."""

    MIN_UNIQUE_WORDS_RATIO: float = 0.3
    """Minimaler Anteil einzigartiger Wörter (verhindert Wiederholungen wie 'ja ja ja')."""

    SUBTITLE_BUFFER_SIZE: int = 1000
    """Maximale Anzahl von Untertitel-Segmenten im Puffer."""

    ENABLE_TIMED_TRANSCRIPTIONS: bool = True
    """Zeitstempel für Transkriptionen aktivieren (für Untertitel-Modus)."""

    ENABLE_TIMED_TRANSLATIONS: bool = True
    """Zeitstempel für Übersetzungen aktivieren (für Untertitel-Modus)."""

    ENABLE_DEBUG_LOGGING: bool = True
    """Debug-Logging global aktivieren."""

    LOG_CHUNK_PROCESSING: bool = False
    """Detailliertes Logging für Chunk-Verarbeitung (sehr ausführlich)."""

    LOG_AUDIO_STATS: bool = True
    """Audio-Statistiken (RMS, Verstärkung) loggen."""

    LOG_PERFORMANCE: bool = True
    """Performance-Metriken (Verarbeitungszeit, Realtime-Faktor) loggen."""

    LOG_STREAM_EVENTS: bool = True
    """Stream-Ereignisse (Verbindung, Timeout, Reconnect) loggen."""

    PERFORMANCE_LOG_INTERVAL: int = 50
    """Intervall für Performance-Logs (Anzahl der Chunks)."""

    MAX_CACHE_SIZE_MB: int = 100
    """Maximale Cache-Größe in MB (Überschreibung durch Config möglich)."""

    CACHE_ENABLED: bool = True
    """Caching global aktivieren."""

    TRANSCRIPTION_CACHE_SIZE: int = 500
    """Maximale Anzahl Einträge im Transkriptions-Cache."""

    TRANSCRIPTION_CACHE_TTL: int = 300
    """Lebensdauer von Transkriptions-Cache-Einträgen in Sekunden (5 Minuten)."""

    TRANSLATION_CACHE_SIZE: int = 1000
    """Maximale Anzahl Einträge im Übersetzungs-Cache."""

    TRANSLATION_CACHE_TTL: int = 3600
    """Lebensdauer von Übersetzungs-Cache-Einträgen in Sekunden (1 Stunde)."""

    AUDIO_CACHE_SIZE: int = 256
    """Maximale Anzahl Einträge im Audio-Cache."""

    AUDIO_CACHE_TTL: int = 1800
    """Lebensdauer von Audio-Cache-Einträgen in Sekunden (30 Minuten)."""

    VAD_THRESHOLD: float = 0.25
    """VAD-Schwellwert (0.0-1.0, höher = weniger empfindlich)."""

    VAD_MIN_SPEECH_DURATION_MS: int = 225
    """Minimale Sprachdauer in Millisekunden (kürzere Passagen werden ignoriert)."""

    VAD_MIN_SILENCE_DURATION_MS: int = 80
    """Minimale Stilledauer in Millisekunden, um einen Satz zu beenden."""

    LANGUAGE_VAD: Dict[str, Dict[str, Any]] = {
        "ja": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "ko": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "zh": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "th": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "vi": {"threshold": 0.3, "min_speech_ms": 250, "min_silence_ms": 90},
        "ar": {"threshold": 0.35, "min_speech_ms": 280, "min_silence_ms": 100},
        "ru": {"threshold": 0.3, "min_speech_ms": 240, "min_silence_ms": 80},
        "hi": {"threshold": 0.32, "min_speech_ms": 280, "min_silence_ms": 110},
        "tr": {"threshold": 0.32, "min_speech_ms": 260, "min_silence_ms": 95},
        "fa": {"threshold": 0.33, "min_speech_ms": 270, "min_silence_ms": 100},
    }
    """Sprachspezifische VAD-Parameter (überschreiben die globalen Werte für bestimmte Sprachen)."""

    ALLOWED_FILE_SCHEME_PREFIX: str = "file://"
    """Präfix für lokale Dateien."""

    ALLOWED_FILE_BASE_DIRS: ClassVar[List[str]] = [
        str(Path.home().resolve()),
        os.getcwd(),
    ]
    """Standardmäßig erlaubte Basisverzeichnisse für Dateizugriff (Home, CWD)."""

    URL_ALLOWED_CHARS: str = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
    """Erlaubte Zeichen in URLs (RFC 3986-konform)."""

    YOUTUBE_HEADERS: Dict[str, str] = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.0.0 Safari/537.36",
        "Referer": "https://www.youtube.com/",
        "Origin": "https://www.youtube.com",
        "Accept": "*/*",
        "Accept-Language": "en-US,en;q=0.9",
    }
    """HTTP-Header für YouTube-Anfragen (umgeht Blockaden)."""

    PLATFORM_CONFIG: Dict[str, Dict[str, Any]] = {
        "windows": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_streamed", "1"],
            "process_creation_flags": 0x08000000,
        },
        "macos": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_on_network_error", "1"],
            "start_new_session": True,
        },
        "linux": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_streamed", "1"],
            "start_new_session": True,
        },
    }
    """Plattformspezifische FFmpeg- und Prozess-Parameter."""

    GUI_QUEUE_MAX_SIZE: int = 200
    """Maximale Größe der GUI-Queue (begrenzt die GUI-Last)."""

    GUI_QUEUE_CLEANUP_TARGET: int = 100
    """Zielgröße der GUI-Queue nach einer Bereinigung."""

    TEXT_QUEUE_MAX_SIZE: int = 150
    """Maximale Größe der Text-Queue (Transkriptionen/Übersetzungen)."""

    TEXT_QUEUE_CLEANUP_TARGET: int = 75
    """Zielgröße der Text-Queue nach einer Bereinigung."""

    ADAPTIVE_CHUNK_MIN_SAMPLES: int = 5
    """Minimale Anzahl von Samples für die adaptive Chunk-Anpassung."""

    ADAPTIVE_CHUNK_SMOOTHING_ALPHA: float = 0.3
    """Glättungsfaktor für die adaptive Chunk-Anpassung (0.0-1.0)."""

    ADAPTIVE_CHUNK_STABLE_THRESHOLD: int = 2
    """Anzahl der stabilen Messungen, bevor die Chunk-Dauer geändert wird."""

    WHISPER_MODELS: List[str] = [
        "tiny",
        "tiny.en",
        "base",
        "base.en",
        "small",
        "small.en",
        "medium",
        "large-v2",
        "large-v3",
        "large-v3-turbo",
        "distil-large-v3",
    ]
    """Liste aller von Whisper unterstützten Modelle (für ComboBox und Validierung)."""

    MAX_REFRESH_ATTEMPTS: int = 3
    """Maximale Anzahl von Refresh-Versuchen für Stream-URLs."""

    REFRESH_RETRY_DELAY_BASE: float = 2.0
    """Basisverzögerung für Refresh-Wiederholungen in Sekunden."""

    REFRESH_RETRY_DELAY_MAX: float = 10.0
    """Maximale Verzögerung für Refresh-Wiederholungen."""

    STALLED_RECONNECT_LOG_INTERVAL: float = 10.0
    """Intervall für Logs bei hängenden Reconnects in Sekunden."""

    @classmethod
    def print_debug_info(cls) -> None:
        """Gibt eine Übersicht aller Konfigurationswerte für Debugging-Zwecke aus."""
        logger = logging.getLogger("dragon")
        logger.debug("=" * 60)
        logger.debug("ConfigDefaults Debug Information")
        logger.debug("=" * 60)
        for name, value in cls.__dict__.items():
            if not name.startswith("_") and not callable(value):
                if isinstance(value, (list, dict)) and len(str(value)) > 100:
                    value_str = str(value)[:100] + "..."
                else:
                    value_str = str(value)
                logger.debug(f"  {name:35} = {value_str}")
        logger.debug("=" * 60)

    @classmethod
    def validate_constants(cls) -> List[str]:
        """
        Validiert die Konstanten auf Konsistenz und gibt eine Liste von Problemen zurück.
        Wird beim Start aufgerufen, um fehlerhafte Konfigurationen zu erkennen.
        """
        issues = []
        if cls.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            issues.append(
                f"SAMPLE_RATE={cls.SAMPLE_RATE} (erwartet: 8000,16000,22050,44100,48000)"
            )
        if cls.CHANNELS not in (1, 2):
            issues.append(f"CHANNELS={cls.CHANNELS} (erwartet: 1 oder 2)")
        if cls.MIN_CHUNK_DURATION >= cls.MAX_CHUNK_DURATION:
            issues.append(
                f"MIN_CHUNK_DURATION={cls.MIN_CHUNK_DURATION} >= MAX_CHUNK_DURATION={cls.MAX_CHUNK_DURATION}"
            )
        if (
            cls.BASE_CHUNK_DURATION < cls.MIN_CHUNK_DURATION
            or cls.BASE_CHUNK_DURATION > cls.MAX_CHUNK_DURATION
        ):
            issues.append(
                f"BASE_CHUNK_DURATION={cls.BASE_CHUNK_DURATION} außerhalb [{cls.MIN_CHUNK_DURATION}, {cls.MAX_CHUNK_DURATION}]"
            )
        if not cls.WHISPER_MODELS:
            issues.append("WHISPER_MODELS ist leer")
        return issues


@dataclass
class Config(ConfigDefaults):
    """    Dynamische Konfiguration für Dragon Whisperer.    """
    _base_chunk_duration: int = ConfigDefaults.BASE_CHUNK_DURATION
    CHUNK_OVERLAP: float = ConfigDefaults.CHUNK_OVERLAP
    MIN_CHUNK_DURATION: int = ConfigDefaults.MIN_CHUNK_DURATION
    MAX_CHUNK_DURATION: int = ConfigDefaults.MAX_CHUNK_DURATION
    LANGUAGE_VAD: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.LANGUAGE_VAD.copy()
    )
    _actual_chunk_duration: float = field(
        init=False, default=float(ConfigDefaults.BASE_CHUNK_DURATION)
    )

    AUDIO_FILTER: str = "aresample=16000"
    LANGUAGE_FILTERS: Dict[str, str] = field(
        default_factory=lambda: {
            k: "aresample=16000" for k in ConfigDefaults.LANGUAGE_VAD
        }
    )
    FILTER_PROFILES: Dict[str, str] = field(
        default_factory=lambda: {
            "transcription": "aresample=16000",
            "translation": "aresample=16000",
            "realtime": "aresample=16000",
            "noisy": "aresample=16000,volume=2.5,highpass=f=150,lowpass=f=3000",
            "music": "aresample=16000",
            "podcast": "aresample=16000",
        }
    )

    YOUTUBE_HEADERS: Dict[str, str] = field(
        default_factory=lambda: ConfigDefaults.YOUTUBE_HEADERS.copy()
    )
    PLATFORM_CONFIG: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.PLATFORM_CONFIG.copy()
    )

    AUDIO_ENHANCEMENT_ENABLED: bool = False
    MIN_RMS_THRESHOLD: float = ConfigDefaults.MIN_RMS_THRESHOLD
    TARGET_RMS: float = ConfigDefaults.TARGET_RMS
    MAX_GAIN: float = ConfigDefaults.MAX_GAIN
    CLIPPING_THRESHOLD: float = ConfigDefaults.CLIPPING_THRESHOLD

    DUPLICATE_CHECK_ENABLED: bool = False
    RECENT_TRANSCRIPTIONS_SIZE: int = ConfigDefaults.RECENT_TRANSCRIPTIONS_SIZE
    MIN_TEXT_LENGTH: int = ConfigDefaults.MIN_TEXT_LENGTH
    MIN_UNIQUE_WORDS_RATIO: float = ConfigDefaults.MIN_UNIQUE_WORDS_RATIO

    SUBTITLE_BUFFER_SIZE: int = ConfigDefaults.SUBTITLE_BUFFER_SIZE
    ENABLE_TIMED_TRANSCRIPTIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSCRIPTIONS
    ENABLE_TIMED_TRANSLATIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSLATIONS

    ENABLE_DEBUG_LOGGING: bool = ConfigDefaults.ENABLE_DEBUG_LOGGING
    LOG_CHUNK_PROCESSING: bool = ConfigDefaults.LOG_CHUNK_PROCESSING
    LOG_AUDIO_STATS: bool = ConfigDefaults.LOG_AUDIO_STATS
    LOG_PERFORMANCE: bool = ConfigDefaults.LOG_PERFORMANCE
    LOG_STREAM_EVENTS: bool = ConfigDefaults.LOG_STREAM_EVENTS
    PERFORMANCE_LOG_INTERVAL: int = ConfigDefaults.PERFORMANCE_LOG_INTERVAL

    MAX_CACHE_SIZE_MB: int = ConfigDefaults.MAX_CACHE_SIZE_MB
    CACHE_ENABLED: bool = ConfigDefaults.CACHE_ENABLED

    WHISPER_MODELS: List[str] = field(
        default_factory=lambda: ConfigDefaults.WHISPER_MODELS.copy()
    )

    _cached_bytes_per_second: Optional[int] = field(
        default=None, init=False, repr=False
    )

    @property
    def CHUNK_DURATION(self) -> float:
        """Aktuelle Chunk-Dauer in Sekunden (dynamisch änderbar)."""
        return self._actual_chunk_duration

    @CHUNK_DURATION.setter
    def CHUNK_DURATION(self, value: float) -> None:
        """Setzt die Chunk-Dauer mit Bereichsprüfung und Logging."""
        old = self._actual_chunk_duration
        if self.MIN_CHUNK_DURATION <= value <= self.MAX_CHUNK_DURATION:
            self._actual_chunk_duration = float(value)
            if abs(old - value) > 0.1 and logger.isEnabledFor(logging.DEBUG):
                logger.debug(f"Chunk-Dauer geändert: {old:.1f}s → {value:.1f}s")
        else:
            clamped = max(self.MIN_CHUNK_DURATION, min(value, self.MAX_CHUNK_DURATION))
            logger.warning(
                f"Chunk-Dauer {value}s außerhalb [{self.MIN_CHUNK_DURATION}, {self.MAX_CHUNK_DURATION}] – "
                f"auf {clamped:.1f}s geklammert"
            )
            self._actual_chunk_duration = clamped

    @property
    def CHUNK_SIZE_BYTES(self) -> int:
        """Größe eines Audio-Chunks in Bytes (basierend auf aktueller Chunk-Dauer)."""
        return int(
            self.CHUNK_DURATION
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def OVERLAP_SIZE_BYTES(self) -> int:
        """Überlappungsgröße in Bytes zwischen aufeinanderfolgenden Chunks."""
        return int(
            self.CHUNK_OVERLAP
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def BYTES_PER_SECOND(self) -> int:
        """
        Datenrate in Bytes pro Sekunde (mit Caching für Performance).
        """
        if self._cached_bytes_per_second is None:
            self._cached_bytes_per_second = (
                self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
            )
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "config",
                    f"Computed BYTES_PER_SECOND = {self._cached_bytes_per_second} "
                    f"(SR={self.SAMPLE_RATE}, CH={self.CHANNELS}, BPS={self.BYTES_PER_SAMPLE})",
                )
        return self._cached_bytes_per_second

    @property
    def MIN_CHUNK_BYTES(self) -> int:
        """Minimale Chunk-Größe in Bytes (entspricht MIN_CHUNK_DURATION)."""
        return int(self.MIN_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def MAX_CHUNK_BYTES(self) -> int:
        """Maximale Chunk-Größe in Bytes (entspricht MAX_CHUNK_DURATION)."""
        return int(self.MAX_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def INITIAL_BUFFER_BYTES(self) -> int:
        """Größe des initialen Audiopuffers in Bytes."""
        return int(self.INITIAL_BUFFER_SECONDS * self.BYTES_PER_SECOND)

    def get_timeout_microseconds(self, is_youtube: bool = False) -> int:
        """
        Gibt das passende Timeout in Mikrosekunden zurück.
        """
        return self.YOUTUBE_TIMEOUT if is_youtube else self.NORMAL_TIMEOUT

    def get_audio_filter(
        self, language: Optional[str] = None, profile: Optional[str] = None
    ) -> str:
        """        Gibt einen optimierten Audiofilter basierend auf Sprache und Profil zurück.        """
        filter_str = self.AUDIO_FILTER

        if profile and profile in self.FILTER_PROFILES:
            filter_str = self.FILTER_PROFILES[profile]

        if language and language in self.LANGUAGE_FILTERS:
            filter_str = self.LANGUAGE_FILTERS[language]

        if self.LOG_AUDIO_STATS and DEBUG_LEVEL >= 2:
            log_debug(
                "audio",
                f"Verwende Audiofilter: {filter_str} (profil={profile}, lang={language})",
            )

        return filter_str

    def get_youtube_headers(self, is_manifest: bool = False) -> Dict[str, str]:
        """        Gibt die HTTP-Header für YouTube-Anfragen zurück.        """
        headers = self.YOUTUBE_HEADERS.copy()
        if is_manifest:
            headers.update(
                {"X-Client-Data": "CI22yQE=", "Content-Type": "application/x-mpegURL"}
            )
        return headers

    def get_platform_config(self, platform: Optional[str] = None) -> Dict[str, Any]:
        """        Gibt plattformspezifische Konfiguration für FFmpeg und Prozesse zurück.        """
        if not platform:
            platform = SYSTEM.lower()
        config = self.PLATFORM_CONFIG.get(platform, self.PLATFORM_CONFIG["linux"])
        if DEBUG_LEVEL >= 3:
            log_debug("platform", f"Plattform-Konfiguration für {platform}: {config}")
        return config

    def __setattr__(self, name: str, value: Any) -> None:
        """
        Invalidiert den BYTES_PER_SECOND‑Cache nur bei tatsächlicher Wertänderung.
        """
        if name in ("SAMPLE_RATE", "CHANNELS", "BYTES_PER_SAMPLE"):
            current = getattr(self, name, None)
            if current != value:
                object.__setattr__(self, "_cached_bytes_per_second", None)
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "config",
                        f"Invalidated BYTES_PER_SECOND cache due to change of {name} "
                        f"({current} → {value})",
                    )
        super().__setattr__(name, value)

    def __post_init__(self) -> None:
        """
        Initialisiert die Config-Instanz nach der Dataclass-Erstellung.
        """
        self._actual_chunk_duration = float(self._base_chunk_duration)
        self._cached_bytes_per_second = (
            self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
        )

        if not self.validate_config():
            logger.warning(
                "Config-Instanz enthält ungültige Werte. Versuche automatische Korrektur."
            )
            if self.CHUNK_DURATION < self.MIN_CHUNK_DURATION:
                logger.warning(
                    f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s < MIN_CHUNK_DURATION={self.MIN_CHUNK_DURATION}s. "
                    f"Setze auf MIN_CHUNK_DURATION."
                )
                self.CHUNK_DURATION = self.MIN_CHUNK_DURATION
            elif self.CHUNK_DURATION > self.MAX_CHUNK_DURATION:
                logger.warning(
                    f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s > MAX_CHUNK_DURATION={self.MAX_CHUNK_DURATION}s. "
                    f"Setze auf MAX_CHUNK_DURATION."
                )
                self.CHUNK_DURATION = self.MAX_CHUNK_DURATION

            if self.CHUNK_OVERLAP >= self.CHUNK_DURATION:
                new_overlap = max(0.0, self.CHUNK_DURATION * 0.1)
                logger.warning(
                    f"CHUNK_OVERLAP={self.CHUNK_OVERLAP:.1f}s >= CHUNK_DURATION={self.CHUNK_DURATION:.1f}s. "
                    f"Setze auf {new_overlap:.1f}s."
                )
                self.CHUNK_OVERLAP = new_overlap

            if self.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
                logger.warning(
                    f"SAMPLE_RATE={self.SAMPLE_RATE}Hz ist unüblich. "
                    f"Whisper erwartet 16000Hz. Setze auf 16000Hz."
                )
                self.SAMPLE_RATE = 16000

            if self.CHANNELS not in (1, 2):
                logger.warning(
                    f"CHANNELS={self.CHANNELS} ist ungültig. Setze auf 1 (Mono)."
                )
                self.CHANNELS = 1
            self._cached_bytes_per_second = (
                self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
            )

        if self.ENABLE_DEBUG_LOGGING:
            if DEBUG_LEVEL >= 2:
                logger.debug(
                    f"Config initialisiert: chunk={self.CHUNK_DURATION:.1f}s "
                    f"({self.CHUNK_SIZE_BYTES:,} bytes), "
                    f"sample_rate={self.SAMPLE_RATE}Hz, channels={self.CHANNELS}, "
                    f"overlap={self.CHUNK_OVERLAP:.1f}s ({self.OVERLAP_SIZE_BYTES:,} bytes), "
                    f"bytes_per_sec={self.BYTES_PER_SECOND:,}"
                )
            elif DEBUG_LEVEL >= 1:
                logger.debug(
                    f"Config: chunk={self.CHUNK_DURATION:.1f}s, "
                    f"sr={self.SAMPLE_RATE}Hz, ch={self.CHANNELS}"
                )

        if not getattr(Config, "_constants_validated", False):
            issues = Config.validate_constants()
            if issues:
                logger.error(
                    f"❌ ConfigDefaults enthält inkonsistente Konstanten: {', '.join(issues)}"
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("config", f"Validation issues details: {issues}")
            else:
                if DEBUG_LEVEL >= 2:
                    log_debug("config", "✅ ConfigDefaults validation passed")
            Config._constants_validated = True

        if self.AUDIO_ENHANCEMENT_ENABLED and not SCIPY_AVAILABLE:
            logger.warning(
                "Audio-Enhancement ist aktiviert, aber scipy ist nicht installiert. "
                "Rauschunterdrückung wird nicht funktionieren."
            )

        if self.DUPLICATE_CHECK_ENABLED and not (SCIPY_AVAILABLE or NUMPY_AVAILABLE):
            logger.warning(
                "Duplikatprüfung ist aktiviert, aber weder scipy noch numpy sind verfügbar. "
                "Die Ähnlichkeitsberechnung wird langsam sein."
            )

    def calculate_optimal_chunk_duration(
        self,
        model_size: str = "medium",
        is_realtime: bool = False,
        device: Optional[str] = None,
        compute_type: Optional[str] = None,
        use_dynamic: bool = True,
    ) -> float:
        """
        Berechnet die optimale Chunk-Dauer basierend auf Modell, Hardware und Echtzeit-Anforderung.
        """
        if is_realtime:
            min_dur = float(self.MIN_CHUNK_DURATION)
            if device == "cuda" and use_dynamic:
                duration = min(8.0, min_dur * 1.5)
            else:
                duration = min_dur
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "chunk",
                    f"Echtzeit-Modus: Chunk-Dauer = {duration:.1f}s (device={device})",
                )
            return duration

        model_lower = model_size.lower()
        base_model = model_lower.replace(".en", "")
        model_base = {
            "tiny": 3.0,
            "base": 4.0,
            "small": 5.0,
            "medium": 6.0,
            "large": 7.0,
            "large-v2": 7.0,
            "large-v3": 7.0,
            "large-v3-turbo": 5.0,
            "distil-large-v3": 4.0,
        }
        duration = model_base.get(base_model, 5.0)

        if use_dynamic:
            compute_factor = 1.0
            if compute_type == "int8":
                compute_factor = 1.2
            elif compute_type == "float16":
                compute_factor = 0.9
            elif compute_type == "float32":
                compute_factor = 0.7
            duration *= compute_factor

            device_factor = 1.0
            if device == "cuda":
                device_factor = 1.3
            elif device == "mps":
                device_factor = 1.1
            elif device == "cpu":
                device_factor = 0.8
            duration *= device_factor

        duration = max(self.MIN_CHUNK_DURATION, min(duration, self.MAX_CHUNK_DURATION))
        duration = round(duration * 2) / 2.0

        if DEBUG_LEVEL >= 2:
            logger.debug(
                f"Optimale Chunk-Dauer für {model_size}: {duration:.1f}s "
                f"(realtime={is_realtime}, device={device}, compute={compute_type})"
            )
        return duration

    @classmethod
    def get_dynamic_max_memory(cls) -> int:
        """
        Ermittelt dynamisch die maximale Arbeitsspeichergrenze (75 % des verfügbaren RAM).

        Returns:
            Maximaler Speicher in Bytes.
        """
        try:
            import psutil

            mem = psutil.virtual_memory()
            limit = int(mem.total * 0.75)
            if DEBUG_LEVEL >= 2:
                logger.debug(
                    f"Dynamisches Speicherlimit: {limit // (1024**2)} MB "
                    f"(75% von {mem.total // (1024**2)} MB)"
                )
            return limit
        except ImportError:
            if DEBUG_LEVEL >= 1:
                logger.debug("psutil nicht verfügbar – verwende Standard-Speicherlimit")
            return cls.MAX_MEMORY_USAGE

    def validate_config(self) -> bool:
        """
        Validiert die aktuelle Konfiguration auf Konsistenz.
        """
        try:
            valid = (
                self.SAMPLE_RATE in [8000, 16000, 22050, 44100, 48000]
                and self.CHANNELS in [1, 2]
                and self.MIN_CHUNK_DURATION
                <= self.CHUNK_DURATION
                <= self.MAX_CHUNK_DURATION
                and 0.0 <= self.CHUNK_OVERLAP < self.CHUNK_DURATION
            )
            if not valid and self.ENABLE_DEBUG_LOGGING:
                logger.warning("Config-Validierung fehlgeschlagen")
            return valid
        except Exception as e:
            logger.error(f"Config-Validierung Ausnahme: {e}")
            return False

    def print_summary(self) -> None:
        """Gibt eine übersichtliche Zusammenfassung der wichtigsten Konfigurationswerte aus."""
        logger.info("\n" + "=" * 60)
        logger.info("🎵 CONFIGURATION (optimized for precision)")
        logger.info("=" * 60)
        logger.info(f"📊 Audio: {self.SAMPLE_RATE}Hz, {self.CHANNELS}ch")
        logger.info(f"📦 Chunk: {self.CHUNK_DURATION}s ({self.CHUNK_SIZE_BYTES:,}B)")
        logger.info(f"⚡ Bytes/sec: {self.BYTES_PER_SECOND:,}")
        logger.info(f"🎛️ Filter: {self.AUDIO_FILTER}")
        logger.info(f"✅ Valid: {self.validate_config()}")
        logger.info("=" * 60)

    def reset_to_defaults(self) -> None:
        """Setzt alle dynamischen Werte auf die Standardwerte aus ConfigDefaults zurück."""
        self._base_chunk_duration = ConfigDefaults.BASE_CHUNK_DURATION
        self.CHUNK_OVERLAP = ConfigDefaults.CHUNK_OVERLAP
        self.MIN_CHUNK_DURATION = ConfigDefaults.MIN_CHUNK_DURATION
        self.MAX_CHUNK_DURATION = ConfigDefaults.MAX_CHUNK_DURATION
        self.CHUNK_DURATION = ConfigDefaults.BASE_CHUNK_DURATION
        self.AUDIO_ENHANCEMENT_ENABLED = False
        self.DUPLICATE_CHECK_ENABLED = False
        self.CACHE_ENABLED = ConfigDefaults.CACHE_ENABLED
        if self.ENABLE_DEBUG_LOGGING:
            logger.info("Config auf Standardwerte zurückgesetzt")

    def get_debug_info(self) -> Dict[str, Any]:
        """
        Sammelt detaillierte Debug-Informationen über die aktuelle Konfiguration.

        Returns:
            Dictionary mit allen relevanten Werten (für Diagnosezwecke).
        """
        return {
            "sample_rate": self.SAMPLE_RATE,
            "channels": self.CHANNELS,
            "chunk_duration": self.CHUNK_DURATION,
            "chunk_size_bytes": self.CHUNK_SIZE_BYTES,
            "bytes_per_second": self.BYTES_PER_SECOND,
            "min_chunk_duration": self.MIN_CHUNK_DURATION,
            "max_chunk_duration": self.MAX_CHUNK_DURATION,
            "audio_filter": self.AUDIO_FILTER,
            "audio_enhancement": self.AUDIO_ENHANCEMENT_ENABLED,
            "duplicate_check": self.DUPLICATE_CHECK_ENABLED,
            "cache_enabled": self.CACHE_ENABLED,
            "max_cache_mb": self.MAX_CACHE_SIZE_MB,
            "whisper_models": self.WHISPER_MODELS,
            "vad_threshold": self.VAD_THRESHOLD,
            "valid": self.validate_config(),
        }


class RealtimeConfig(Config):
    """
    Konfiguration für Echtzeit-Transkription mit minimaler Latenz.

    Optimiert für kurze Antwortzeiten, weniger CPU‑Verbrauch und
    reduzierte Überlappung, um die Verarbeitungsdauer pro Chunk
    so gering wie möglich zu halten.
    """

    def __init__(self) -> None:
        super().__init__()
        # Chunk‑Dauer auf 5 s reduzieren – kürzere Verarbeitungsblöcke
        self.CHUNK_DURATION = 5.0
        # Überlappung minimieren, um redundante Berechnungen zu vermeiden
        self.CHUNK_OVERLAP = 0.1
        # Timeout für Stream‑Verbindungen heruntersetzen
        self.STREAM_TIMEOUT = 5

        # Audiofilter auf das absolute Minimum beschränken –
        # nur Resampling auf 16 kHz, keine weiteren Effekte.
        self.AUDIO_FILTER = "aresample=16000"

        # Keine Audio‑Nachbearbeitung – spart CPU‑Zeit
        self.AUDIO_ENHANCEMENT_ENABLED = False
        self.DUPLICATE_CHECK_ENABLED = False

        # Weniger aufeinanderfolgende Fehler tolerieren, bevor
        # der Stream neu gestartet wird, um schneller auf Probleme
        # zu reagieren.
        self.MAX_CONSECUTIVE_ERRORS = 3

        # FFmpeg‑Puffer und Threads für geringere Latenz anpassen
        self.FFMPEG_THREADS = 1
        self.FFMPEG_BUFSIZE = "256k"

        # Reduzierte Analysezeit in FFmpeg, damit der Stream
        # schneller startet
        self.FFMPEG_PROBESIZE = "16"
        self.FFMPEG_ANALYZE_DURATION = "0"


class HighAccuracyConfig(Config):
    """
    Konfiguration für höchste Transkriptionsgenauigkeit bei geringerem Zeitdruck.

    Diese Einstellungen priorisieren die Erkennungsqualität gegenüber der
    Geschwindigkeit.  Sie sind ideal für die Offline‑Verarbeitung von
    aufgezeichnetem Material (Podcasts, Vorträge, Hörbücher).
    """

    def __init__(self) -> None:
        super().__init__()

        # ── Chunk‑Dauer ──────────────────────────────────────────────
        # Längere Chunks geben dem Modell mehr Kontext, was zu weniger
        # Wortfehlern führt.  25 s ist ein guter Kompromiss zwischen
        # Genauigkeit und Speicherverbrauch.
        self.CHUNK_DURATION = 25.0

        # ── Überlappung ─────────────────────────────────────────────
        # Eine moderate Überlappung verhindert, dass Satzgrenzen durch
        # die feste Chunk‑Einteilung zerschnitten werden.
        self.CHUNK_OVERLAP = 0.8

        # ── Audio‑Filterkette ───────────────────────────────────────
        # Die Filterkette ist darauf ausgelegt, Sprache möglichst klar
        # hervorzuheben und störende Hintergrundgeräusche zu dämpfen,
        # ohne die Sprachverständlichkeit zu beeinträchtigen.
        #   • volume=1.8          → leise Passagen anheben
        #   • highpass=f=80       → tieffrequentes Rumpeln entfernen
        #   • lowpass=f=3800      → hohe Frequenzen dämpfen, die für
        #                           Sprache nicht relevant sind
        #   • dynaudnorm          → Lautstärke dynamisch normalisieren
        self.AUDIO_FILTER = (
            "aresample=16000,"
            "volume=1.8,"
            "highpass=f=80,"
            "lowpass=f=3800,"
            "dynaudnorm=p=0.3:s=3:g=20"
        )

        # ── Audio‑Enhancement ───────────────────────────────────────
        # Zusätzliche Rauschunterdrückung und Dynamikbearbeitung.
        self.AUDIO_ENHANCEMENT_ENABLED = True

        # ── Duplikaterkennung ───────────────────────────────────────
        # Verhindert, dass das Modell denselben Satz mehrfach ausgibt.
        self.DUPLICATE_CHECK_ENABLED = True

        # ── Fehlertoleranz ─────────────────────────────────────────
        # Bei Fokus auf Genauigkeit wollen wir nicht voreilig abbrechen.
        self.MAX_CONSECUTIVE_ERRORS = 10

        # ── FFmpeg‑Puffer ───────────────────────────────────────────
        # Ein größerer Puffer kann kurze Netzwerkaussetzer besser
        # überbrücken und verhindert Aussetzer bei der Datenübertragung.
        self.FFMPEG_BUFSIZE = "4096k"

        # ── Stream‑Timeout ─────────────────────────────────────────
        # Längere Timeouts verhindern, dass eine langsame Verbindung
        # fälschlich als Fehler erkannt wird.
        self.STREAM_TIMEOUT = 60


class YouTubeOptimizedConfig(Config):
    """
    Speziell auf YouTube‑Streams abgestimmte Konfiguration.

    Diese Einstellungen berücksichtigen die besonderen Eigenschaften von
    YouTube‑Livestreams und Video‑on‑Demand:

    * Kürzere Timeouts für eine schnellere Fehlererkennung.
    * Erhöhte Wiederholungsversuche, um auch bei instabilen Verbindungen
      das Audio zuverlässig zu extrahieren.
    * Aggressives Reconnect‑Verhalten mit kurzer Verzögerung.
    * Ein auf YouTube optimierter Audio‑Filter mit sanfter Dynamik‑
      Kompression und leichter Anhebung der Sprachfrequenzen.
    * Kein zusätzliches Audio‑Enhancement, um CPU‑Last zu sparen.
    """

    def __init__(self) -> None:
        super().__init__()

        # ── FFmpeg‑Ressourcen ───────────────────────────────────────
        # Ein Thread genügt, da YouTube‑Streams bereits gut komprimiert sind.
        self.FFMPEG_THREADS = 1
        # Größerer Puffer, um Netzwerkschwankungen abzufedern.
        self.FFMPEG_BUFSIZE = "2048k"

        # ── Timeouts (in Mikrosekunden) ─────────────────────────────
        # 10 s Timeout für die eigentliche Datenübertragung.
        self.YOUTUBE_TIMEOUT = 10_000_000
        # Verzögerung vor einem Reconnect – 0,5 s für schnelle Reaktion.
        self.RECONNECT_DELAY = 0.5

        # ── URL‑Refresh ────────────────────────────────────────────
        self.YOUTUBE_URL_REFRESH_INTERVAL = 300   # alle 5 Minuten
        self.MAX_REFRESH_ATTEMPTS = 8             # mehr Versuche für Robustheit

        # ── Stream‑Timeout ─────────────────────────────────────────
        # 20 s Gesamt‑Timeout für den Stream‑Start.
        self.STREAM_TIMEOUT = 20

        # ── Audio‑Filter ───────────────────────────────────────────
        # Der Filter wurde für YouTube‑typische Sprachaufnahmen optimiert:
        #   • volume=1,8     → leichte Anhebung ohne Übersteuerung
        #   • highpass=80Hz  → entfernt tieffrequentes Brummen
        #   • lowpass=3400Hz → erhält Sprachverständlichkeit
        #   • compand        → sanfte dynamische Kompression, um
        #                       Lautstärkeschwankungen auszugleichen
        self.AUDIO_FILTER = (
            "aresample=16000,"
            "volume=1.8,"
            "highpass=f=80,"
            "lowpass=f=3400,"
            "compand=attacks=0.01:decays=0.2:points=-80/-80|-45/-15|-27/-9|0/-7|20/-7"
        )

        # ── Kein zusätzliches Enhancement ──────────────────────────
        # YouTube‑Audio ist meist bereits gut bearbeitet; zusätzliche
        # Filterung würde nur CPU kosten.
        self.AUDIO_ENHANCEMENT_ENABLED = False


def get_config(config_type: str = "default") -> Config:
    """
    Erzeugt und liefert eine Config‑Instanz für den angegebenen
    Konfigurationstyp.

    Unterstützte Typen:
        - ``"default"``            → Standard‑Konfiguration
        - ``"realtime"``           → Minimale Latenz (Echtzeit)
        - ``"high_accuracy"``      → Maximale Genauigkeit (Offline)
        - ``"youtube"``            → YouTube‑optimiert

    Bei einem unbekannten Typ wird die Standard‑Konfiguration verwendet
    und eine Warnung ausgegeben.  Die erzeugte Instanz wird automatisch
    validiert; falls die Validierung fehlschlägt, wird versucht, die
    Konfiguration zu reparieren.
    """
    configs = {
        "default": Config,
        "realtime": RealtimeConfig,
        "high_accuracy": HighAccuracyConfig,
        "youtube": YouTubeOptimizedConfig,
    }

    # Verwende den gewünschten Typ, falle bei unbekanntem auf "default" zurück
    config_class = configs.get(config_type)
    if config_class is None:
        logger.warning(
            "⚠️ Unbekannter config_type '%s' – verwende 'default'.", config_type
        )
        config_class = Config

    # Instanz erzeugen
    try:
        config = config_class()
    except Exception as exc:
        logger.error(
            "❌ Fehler beim Erstellen der Konfiguration '%s': %s – "
            "verwende Standard‑Config.",
            config_type,
            exc,
        )
        config = Config()

    # Validierung und ggf. Reparatur
    if not config.validate_config():
        logger.warning(
            "Config '%s' ist inkonsistent – versuche Reparatur …",
            config_class.__name__,
        )
        # Config selbst hat keine repair()‑Methode – wir führen die
        # Korrekturen direkt durch (Bereichsprüfung der Chunk‑Dauer etc.)
        if config.CHUNK_DURATION < config.MIN_CHUNK_DURATION:
            config.CHUNK_DURATION = config.MIN_CHUNK_DURATION
        if config.CHUNK_DURATION > config.MAX_CHUNK_DURATION:
            config.CHUNK_DURATION = config.MAX_CHUNK_DURATION
        if config.CHUNK_OVERLAP >= config.CHUNK_DURATION:
            config.CHUNK_OVERLAP = max(0.0, config.CHUNK_DURATION * 0.1)
        if config.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            config.SAMPLE_RATE = 16000
        if config.CHANNELS not in (1, 2):
            config.CHANNELS = 1

        if not config.validate_config():
            logger.error(
                "❌ Konnte Config '%s' nicht reparieren – verwende "
                "absolute Notfall‑Defaults.",
                config_class.__name__,
            )
            config = Config()
    else:
        if DEBUG_LEVEL >= 2:
            log_debug(
                "config",
                f"Config '{config_class.__name__}' erfolgreich erstellt und validiert "
                f"(chunk={config.CHUNK_DURATION:.1f}s, sr={config.SAMPLE_RATE}Hz, "
                f"ch={config.CHANNELS})",
            )

    return config


class FastLazyLoader:
    """
    Thread‑sicherer Lazy‑Loader für Module mit Caching und Verfügbarkeitsprüfung.
    """

    _loaded_modules: Dict[str, Any] = {}
    _module_locks: Dict[str, threading.Lock] = {}
    _global_lock = threading.Lock()
    _availability_cache: Dict[str, Tuple[bool, float]] = {}
    _availability_cache_ttl: float = 60.0
    _metrics_enabled: bool = False
    _metrics: Dict[str, Any] = {
        "load_attempts": 0,
        "load_success": 0,
        "load_failures": 0,
        "cache_hits": 0,
        "availability_checks": 0,
    }
    _metrics_lock = threading.RLock()
    _cache_lock = threading.RLock()
    _logger = logging.getLogger("dragon")

    @classmethod
    def configure(
        cls,
        *,
        availability_cache_ttl: Optional[float] = None,
        enable_metrics: bool = False,
    ) -> None:
        """
        Konfiguriert globale Parameter.
        """
        if availability_cache_ttl is not None:
            cls._availability_cache_ttl = availability_cache_ttl
        cls._metrics_enabled = enable_metrics
        cls._logger.debug(
            "FastLazyLoader configured: ttl=%ss, metrics=%s",
            cls._availability_cache_ttl,
            enable_metrics,
            extra={"component": "loader"},
        )

    @classmethod
    def _get_lock(cls, module_name: str) -> threading.Lock:
        """Gibt ein Lock für das Modul zurück (erzeugt eines, falls nicht vorhanden)."""
        with cls._global_lock:
            if module_name not in cls._module_locks:
                cls._module_locks[module_name] = threading.Lock()
            return cls._module_locks[module_name]

    @classmethod
    def _cleanup_availability_cache(cls) -> None:
        """Entfernt abgelaufene Einträge aus dem Verfügbarkeits‑Cache."""
        now = time.time()
        with cls._cache_lock:
            expired = [
                k
                for k, (_, ts) in cls._availability_cache.items()
                if now - ts > cls._availability_cache_ttl
            ]
            for k in expired:
                del cls._availability_cache[k]
                if cls._metrics_enabled:
                    cls._logger.debug(
                        "Removed expired availability entry for %s",
                        k,
                        extra={"component": "loader"},
                    )

    @classmethod
    def load(
        cls, module_name: str, import_paths: Union[str, List[str], None] = None
    ) -> Any:
        """
        Lädt ein Modul (lazy) und gibt es zurück.
        """
        # ── Schneller Lese‑Pfad ─────────────────────────────────────
        with cls._global_lock:
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                mod = cls._loaded_modules[module_name]
                # Bei Mock‑Modul geben wir es trotzdem zurück, damit der
                # Aufrufer nicht mit None umgehen muss.
                return mod

        # ── Schreib‑Pfad (mit modul‑spezifischem Lock) ──────────────
        lock = cls._get_lock(module_name)
        with lock:
            # Nach Erhalt des Locks erneut prüfen (Double‑Check)
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                return cls._loaded_modules[module_name]

            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_attempts"] += 1

            # Wurde kein Importpfad angegeben, verwende den Modulnamen.
            if import_paths is None:
                paths = [module_name]
            elif isinstance(import_paths, str):
                paths = [import_paths]
            else:
                paths = import_paths

            # Spezielle Lade‑Handler für kritische Module
            special_handlers = {
                "torch": cls._load_torch,
                "faster_whisper": cls._load_faster_whisper,
                "numpy": cls._load_numpy,
                "deep_translator": cls._load_deep_translator,
                "scipy.signal": cls._load_scipy_signal,
            }

            if module_name in special_handlers:
                try:
                    module = special_handlers[module_name]()
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s via special handler", module_name,
                        extra={"component": "loader"},
                    )
                    return module
                except ImportError as e:
                    cls._logger.debug(
                        "Special handler for %s failed: %s", module_name, e,
                        extra={"component": "loader"},
                    )

            # Standard‑Import‑Pfad durchprobieren
            last_error = None
            for path in paths:
                try:
                    module = importlib.import_module(path)
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s from %s", module_name, path,
                        extra={"component": "loader"},
                    )
                    return module
                except ImportError as e:
                    last_error = e
                    continue

            # Kein Import möglich – Mock‑Modul zurückgeben
            cls._logger.debug(
                "Module %s not available: %s", module_name, last_error,
                extra={"component": "loader"},
            )
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_failures"] += 1

            # Jedes Mock‑Modul warnt nur EINMAL pro Sitzung
            class MockModule:
                _is_mock = True
                __name__ = module_name
                _warned: bool = False  # Klassenattribut, nicht Instanz

                def __getattr__(self, name: str) -> Any:
                    # Warnung nur beim allerersten Zugriff ausgeben
                    if not MockModule._warned:
                        MockModule._warned = True
                        logging.getLogger("dragon").warning(
                            "⚠️ Zugriff auf Mock-Modul '%s' – "
                            "die eigentliche Bibliothek ist nicht installiert. "
                            "Funktionen werden fehlschlagen.",
                            module_name,
                        )
                    raise ImportError(f"Module {module_name} not available")

            mock = MockModule()
            cls._loaded_modules[module_name] = mock
            return mock

    @classmethod
    def _load_torch(cls):
        import torch

        try:
            import torch._logging

            torch._logging.set_logs(all=logging.ERROR)
        except Exception:
            pass
        return torch

    @classmethod
    def _load_faster_whisper(cls):
        """
        Lädt die faster-whisper Bibliothek und gibt die WhisperModel-Klasse zurück.
        """
        import os
        os.environ.setdefault("CT2_VERBOSE", "0")
        from faster_whisper import WhisperModel

        if cls._logger.isEnabledFor(logging.DEBUG):
            try:
                import faster_whisper

                version = getattr(faster_whisper, "__version__", "unknown")
                cls._logger.debug(
                    "faster-whisper version %s geladen", version,
                    extra={"component": "loader"},
                )
            except Exception:
                pass

        return WhisperModel

    @classmethod
    def _load_numpy(cls):
        import numpy as np

        return np

    @classmethod
    def _load_deep_translator(cls):
        from deep_translator import GoogleTranslator

        return GoogleTranslator

    @classmethod
    def _load_scipy_signal(cls):
        import scipy.signal

        return scipy.signal

    @classmethod
    def is_available(cls, module_name: str, use_cache: bool = True) -> bool:
        """
        Prüft, ob ein Modul verfügbar ist (durch Suchpfad).
        """
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics["availability_checks"] += 1

        # Bereits (erfolgreich) geladen?
        if module_name in cls._loaded_modules:
            mod = cls._loaded_modules[module_name]
            return not getattr(mod, "_is_mock", False)

        # Cache prüfen (mit TTL)
        if use_cache:
            cls._cleanup_availability_cache()
            with cls._cache_lock:
                cached = cls._availability_cache.get(module_name)
                if cached is not None:
                    return cached[0]

        # Tatsächlich prüfen
        spec = importlib.util.find_spec(module_name)
        available = spec is not None

        if use_cache:
            with cls._cache_lock:
                cls._availability_cache[module_name] = (available, time.time())

        cls._logger.debug(
            "Availability check for %s: %s", module_name, available,
            extra={"component": "loader"},
        )
        return available

    @classmethod
    def clear_cache(cls, module_name: Optional[str] = None) -> None:
        """
        Leert den Modul‑Cache und den Verfügbarkeits‑Cache.
        """
        with cls._global_lock:
            if module_name is None:
                cls._loaded_modules.clear()
                cls._module_locks.clear()
                cls._availability_cache.clear()
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics = {
                            "load_attempts": 0,
                            "load_success": 0,
                            "load_failures": 0,
                            "cache_hits": 0,
                            "availability_checks": 0,
                        }
                cls._logger.debug("All caches cleared", extra={"component": "loader"})
            else:
                if module_name in cls._loaded_modules:
                    del cls._loaded_modules[module_name]
                if module_name in cls._module_locks:
                    del cls._module_locks[module_name]
                with cls._cache_lock:
                    if module_name in cls._availability_cache:
                        del cls._availability_cache[module_name]
                cls._logger.debug(
                    "Cache cleared for module %s", module_name,
                    extra={"component": "loader"},
                )

    @classmethod
    def get_metrics(cls) -> Dict[str, Any]:
        """Gibt die gesammelten Metriken zurück (leeres Dict, wenn Metriken deaktiviert)."""
        if not cls._metrics_enabled:
            return {}
        with cls._metrics_lock:
            return cls._metrics.copy()

    @classmethod
    def reset_metrics(cls) -> None:
        """Setzt die Metriken zurück (nur wenn Metriken aktiviert)."""
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics = {
                    "load_attempts": 0,
                    "load_success": 0,
                    "load_failures": 0,
                    "cache_hits": 0,
                    "availability_checks": 0,
                }
            cls._logger.debug("Metrics reset", extra={"component": "loader"})

class GPUStats:
    """
    Singleton‑artige Hilfsklasse für einmalige Initialisierung von pynvml.
    Stellt den GPU‑Handle und grundlegende Funktionen bereit.
    """

    _initialized = False
    _nvml_handle = None
    _nvml_available = False
    _lock = threading.Lock()

    @classmethod
    def _ensure_initialized(cls):
        """Initialisiert pynvml genau einmal (threadsicher)."""
        if cls._initialized:
            return
        with cls._lock:
            if cls._initialized:
                return
            try:
                import pynvml

                pynvml.nvmlInit()
                cls._nvml_handle = pynvml.nvmlDeviceGetHandleByIndex(0)
                cls._nvml_available = True
            except (ImportError, pynvml.NVMLError) as e:
                logger.debug(f"pynvml nicht verfügbar: {e}")
                cls._nvml_available = False
            finally:
                cls._initialized = True

    @classmethod
    def is_available(cls) -> bool:
        """Gibt zurück, ob pynvml erfolgreich initialisiert wurde."""
        cls._ensure_initialized()
        return cls._nvml_available

    @classmethod
    def get_temperature(cls) -> Optional[int]:
        """Aktuelle GPU‑Temperatur in °C oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetTemperature(
                cls._nvml_handle, pynvml.NVML_TEMPERATURE_GPU
            )
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_utilization(cls) -> Optional[int]:
        """GPU‑Auslastung in Prozent oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetUtilizationRates(cls._nvml_handle).gpu
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_memory_info(cls) -> Optional[Dict[str, int]]:
        """
        Gibt ein Dictionary mit Informationen über den GPU‑Speicher zurück.
        Enthält 'total', 'free' und 'used' in Bytes, oder None bei Fehler.
        """
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            mem = pynvml.nvmlDeviceGetMemoryInfo(cls._nvml_handle)
            return {
                "total": mem.total,
                "free": mem.free,
                "used": mem.used,
            }
        except pynvml.NVMLError:
            return None


class PlatformStderrFilter:
    """
    Filtert unerwünschte Zeilen aus dem stderr‑Stream, die von
    Plattform‑Bibliotheken (Rockchip, GPU‑Treibern, Windows‑Console)
    stammen und im normalen Betrieb keine relevante Information liefern.
    """

    def __init__(self, original_stderr: Any) -> None:
        """
        Args:
            original_stderr: Das originale stderr‑Objekt (z. B. ``sys.stderr``).
        """
        self.original_stderr = original_stderr
        self.filter_patterns: List[str] = [
            "mpp_soc:",
            "mpp_platform:",
            "can not found match soc name",
            "/proc/device-tree/compatible",
            "rockchip",
            "ffmpeg",
            "TORCH_NCCL",
        ]

        # Windows‑spezifische Muster nur auf der jeweiligen Plattform
        if IS_WINDOWS:
            self.filter_patterns.extend(
                [
                    "Failed to set direct console mode",
                    "Console code page",
                    "chcp",
                    "win32api",
                ]
            )

        # Thread‑Sicherheit für dynamische Erweiterungen
        self._lock = threading.RLock()

    def add_pattern(self, pattern: str) -> None:
        """
        Fügt einen weiteren Teilstring hinzu, der unterdrückt werden soll.
        Kann auch von Plugins oder anderen Modulen zur Laufzeit verwendet
        werden.
        """
        if not pattern or not isinstance(pattern, str):
            logger.warning(
                "PlatformStderrFilter.add_pattern: ungültiges Muster '%s' ignoriert",
                pattern,
            )
            return
        with self._lock:
            if pattern not in self.filter_patterns:
                self.filter_patterns.append(pattern)

    def load_from_config(self, config_file: Optional[str] = None) -> None:
        """
        Lädt zusätzliche Filter-Muster aus einer Textdatei und fügt sie
        mittels add_pattern() der internen Liste hinzu.
        """

        # 1. Pfad bestimmen
        if config_file is None:
            # Prüfen auf Umgebungsvariable
            config_file = os.environ.get("DRAGON_STDERR_FILTER_FILE", "").strip()
            if not config_file:
                # Fallback: Standardpfad im Konfigurationsverzeichnis
                try:
                    config_dir = PlatformUtils.get_platform_config_dir()
                except Exception:
                    # Wenn PlatformUtils nicht verfügbar, abbrechen
                    logger.debug(
                        "PlatformStderrFilter.load_from_config: "
                        "Kann Konfigurationsverzeichnis nicht ermitteln – überspringe."
                    )
                    return
                config_file = str(config_dir / "stderr_filters.txt")

        # 2. Datei einlesen (falls sie existiert)
        try:
            with open(config_file, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except FileNotFoundError:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "stderr_filter",
                    "Filter‑Datei '%s' nicht gefunden – keine Muster geladen.",
                    config_file,
                )
            return
        except PermissionError as e:
            logger.warning(
                "PlatformStderrFilter.load_from_config: Keine Leseberechtigung für '%s': %s",
                config_file,
                e,
            )
            return
        except OSError as e:
            logger.warning(
                "PlatformStderrFilter.load_from_config: Fehler beim Lesen von '%s': %s",
                config_file,
                e,
            )
            return
        except Exception as e:
            logger.warning(
                "PlatformStderrFilter.load_from_config: Unerwarteter Fehler beim Lesen von '%s': %s",
                config_file,
                e,
            )
            return

        # 3. Muster parsen und hinzufügen
        added_count = 0
        for line in lines:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            # Muster sind einfache Teilstrings – keine Regex
            self.add_pattern(line)
            added_count += 1

        if added_count > 0:
            logger.info(
                "PlatformStderrFilter: %d zusätzliche Muster aus '%s' geladen.",
                added_count,
                config_file,
            )
        elif DEBUG_LEVEL >= 3:
            log_debug(
                "stderr_filter",
                "Filter‑Datei '%s' enthielt keine gültigen Muster.",
                config_file,
            )

    def write(self, text: str) -> None:
        """Schreibt *text* nur dann nach stderr, wenn er kein Filter-Muster enthält."""
        # Leere Strings sofort ignorieren
        if not text:
            return

        # Kopie der Musterliste unter Lock (sehr kurz)
        with self._lock:
            patterns = self.filter_patterns

        # Enthält der Text eines der Muster? → unterdrücken
        if any(p in text for p in patterns):
            return

        # Ungefiltert weiterleiten
        self.original_stderr.write(text)

    def flush(self) -> None:
        """Leitet flush() an das originale stderr‑Objekt weiter."""
        self.original_stderr.flush()

if DEBUG_LEVEL < 3:
    sys.stderr = PlatformStderrFilter(sys.stderr)
    sys.stderr.load_from_config()
else:
    sys.stderr = sys.__stderr__




# -----------------------------------------------------------------------------
# Logging-Helfer (sichere Fallbacks)
# -----------------------------------------------------------------------------
def _safe_log_debug(component: str, msg: str, *args: Any, **kwargs: Any) -> None:
    try:
        from dragon_whisperer import log_debug
        log_debug(component, msg, *args, **kwargs)
    except (ImportError, NameError):
        if DEBUG_LEVEL >= 3 or component in DEBUG_COMPONENTS:
            logging.getLogger("dragon").debug(f"[{component}] {msg}", *args, **kwargs)

def _safe_log_exception(component: str, msg: str, exc: Exception, level: str = "error") -> None:
    try:
        from dragon_whisperer import log_exception
        log_exception(component, msg, exc, level)
    except (ImportError, NameError):
        logger = logging.getLogger("dragon")
        if level == "error":
            logger.error(f"[{component}] {msg}: {exc}", exc_info=True)
        elif level == "warning":
            logger.warning(f"[{component}] {msg}: {exc}", exc_info=True)
        else:
            logger.debug(f"[{component}] {msg}: {exc}", exc_info=True)

# -----------------------------------------------------------------------------
# Hauptklasse PlatformUtils
# -----------------------------------------------------------------------------
class PlatformUtils:
    """
    Plattformunabhängige Hilfsfunktionen für Dragon Whisperer.
    (Detaillierte Dokumentation siehe Modul-Docstring)
    """

    # --- Klassenattribute (Zustand, Caches, Locks) ---
    _environment_setup_done: ClassVar[bool] = False
    _environment_setup_lock: ClassVar[threading.RLock] = threading.RLock()

    _dependencies_checked: ClassVar[bool] = False
    _dependencies_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache: ClassVar[Dict[str, Tuple[bool, float]]] = {}
    _dependencies_cache_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache_ttl: ClassVar[float] = 60.0

    _ffmpeg_path: ClassVar[Optional[str]] = None
    _ffmpeg_path_lock: ClassVar[threading.RLock] = threading.RLock()

    _terminal_settings_saved: ClassVar[bool] = False
    _original_stty_settings: ClassVar[Optional[str]] = None
    _terminal_lock: ClassVar[threading.Lock] = threading.Lock()

    _base_dirs: ClassVar[Optional[List[Path]]] = None
    _user_dirs: ClassVar[List[Path]] = []
    _allowed_dirs_lock: ClassVar[threading.RLock] = threading.RLock()

    _test_home: ClassVar[Optional[Path]] = None
    _test_cwd: ClassVar[Optional[Path]] = None

    _DEBUG_COMPONENT: ClassVar[str] = "platform"
    _logger: ClassVar[logging.Logger] = logging.getLogger("dragon")

    _config_dir_logged: ClassVar[bool] = False

    _executable_cache: ClassVar[Dict[str, Optional[str]]] = {}
    _executable_cache_lock: ClassVar[threading.RLock] = threading.RLock()

    _console_configured: ClassVar[bool] = False
    _original_console_codepage_in: ClassVar[Optional[int]] = None
    _original_console_codepage_out: ClassVar[Optional[int]] = None
    _original_console_mode: ClassVar[Optional[int]] = None

    _is_container: ClassVar[Optional[bool]] = None
    _container_type: ClassVar[Optional[str]] = None

    # -------------------------------------------------------------------------
    # 1. Plattform- und Container-Erkennung
    # -------------------------------------------------------------------------
    @classmethod
    def is_wsl(cls) -> bool:
        """Erkennt, ob das System unter WSL (Windows Subsystem for Linux) läuft."""
        if not IS_LINUX:
            return False
        try:
            with open("/proc/version", "r") as f:
                version = f.read().lower()
                return "microsoft" in version or "wsl" in version
        except Exception:
            return False

    @classmethod
    def is_docker(cls) -> bool:
        """Erkennt, ob das System in einem Docker-Container läuft."""
        if not IS_LINUX:
            return False
        if os.path.exists("/.dockerenv"):
            return True
        try:
            with open("/proc/1/cgroup", "r") as f:
                return any("docker" in line for line in f)
        except Exception:
            return False

    @classmethod
    def is_flatpak(cls) -> bool:
        """Erkennt, ob das Programm als Flatpak läuft."""
        return "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ

    @classmethod
    def is_snap(cls) -> bool:
        """Erkennt, ob das Programm als Snap läuft."""
        return "SNAP" in os.environ or "SNAP_NAME" in os.environ

    @classmethod
    def get_container_type(cls) -> str:
        """Gibt den Containertyp zurück ('docker', 'wsl', 'flatpak', 'snap', 'none')."""
        if cls._container_type is None:
            if cls.is_docker():
                cls._container_type = "docker"
            elif cls.is_wsl():
                cls._container_type = "wsl"
            elif cls.is_flatpak():
                cls._container_type = "flatpak"
            elif cls.is_snap():
                cls._container_type = "snap"
            else:
                cls._container_type = "none"
        return cls._container_type

    @classmethod
    def is_containerized(cls) -> bool:
        """True, wenn das System in einer Container-Umgebung läuft."""
        return cls.get_container_type() != "none"

    @classmethod
    def is_headless(cls) -> bool:
        """Prüft, ob die Umgebung keine GUI unterstützt (kein DISPLAY, kein Wayland)."""
        if IS_WINDOWS:
            return False
        if IS_MACOS:
            return False
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            return False
        try:
            import tkinter
            root = tkinter.Tk()
            root.destroy()
            return False
        except Exception:
            return True

    # -------------------------------------------------------------------------
    # 2. Verzeichnis‑Whitelist (Dateizugriffssicherheit)
    # -------------------------------------------------------------------------
    @classmethod
    def set_allowed_dirs(cls, dirs: List[str]) -> None:
        """
        Setzt die Liste der zusätzlich erlaubten Benutzerverzeichnisse.

        Args:
            dirs: Liste von Verzeichnispfaden (als String). Ungültige Pfade
                  werden ignoriert, existierende und lesbare Verzeichnisse
                  werden aufgelöst und gespeichert.
        """
        if not dirs:
            cls._logger.debug(
                "set_allowed_dirs: Leere Liste – keine Änderungen.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return

        cls._logger.debug(
            f"Setting user dirs: {dirs}", extra={"component": cls._DEBUG_COMPONENT}
        )
        with cls._allowed_dirs_lock:
            resolved = []
            for d in dirs:
                if not d or not isinstance(d, str):
                    cls._logger.debug(
                        f"  → Skipped (invalid entry): {d!r}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                d = d.strip()
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                except Exception as e:
                    cls._logger.debug(
                        f"  → Skipped (resolution error): {d} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                try:
                    if not p.exists():
                        cls._logger.debug(
                            f"  → Skipped (does not exist): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not p.is_dir():
                        cls._logger.debug(
                            f"  → Skipped (not a directory): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not os.access(p, os.R_OK):
                        cls._logger.warning(
                            f"Verzeichnis {p} ist nicht lesbar – "
                            "Dateien darin können nicht geöffnet werden.",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                    resolved.append(p)
                    cls._logger.debug(
                        f"  → Resolved: {p}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except (PermissionError, OSError) as e:
                    cls._logger.debug(
                        f"  → Skipped (access error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except Exception as e:
                    cls._logger.debug(
                        f"  → Skipped (unexpected error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
            cls._user_dirs = resolved
            cls._base_dirs = None  # Cache invalidieren
            cls._logger.debug(
                f"Final user dirs: {[str(p) for p in resolved]}",
                extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def add_allowed_dir(cls, dir_path: str) -> bool:
        """Fügt ein einzelnes Verzeichnis zur Whitelist hinzu."""
        if not dir_path:
            return False
        current = cls.get_allowed_dirs()
        if dir_path in current:
            return True
        new_list = current + [dir_path]
        cls.set_allowed_dirs(new_list)
        return dir_path in cls.get_allowed_dirs()

    @classmethod
    def get_allowed_dirs(cls) -> List[str]:
        """Gibt die Liste der aktuell erlaubten Benutzerverzeichnisse als Strings zurück."""
        with cls._allowed_dirs_lock:
            return [str(p) for p in cls._user_dirs]

    @classmethod
    def reset_allowed_dirs(cls) -> None:
        """Setzt die Whitelist auf die Standard-Basisverzeichnisse zurück."""
        with cls._allowed_dirs_lock:
            cls._user_dirs = []
            cls._base_dirs = None

    @classmethod
    def is_path_allowed(cls, path: str) -> bool:
        """Prüft, ob ein gegebener Pfad innerhalb der erlaubten Verzeichnisse liegt."""
        try:
            real_path = Path(path).resolve()
        except Exception:
            return False
        for base in cls._get_allowed_dirs():
            try:
                real_path.relative_to(base)
                return True
            except ValueError:
                continue
        return False

    # -------------------------------------------------------------------------
    # 3. Konfigurationsverzeichnis
    # -------------------------------------------------------------------------
    @classmethod
    def get_platform_config_dir(cls) -> Path:
        """
        Gibt das plattformspezifische Konfigurationsverzeichnis zurück.

        Returns:
            Path: Verzeichnis, in dem dragon_settings.json und andere
                  Konfigurationsdateien gespeichert werden sollen.
        """
        if IS_WINDOWS:
            appdata = os.environ.get("APPDATA")
            if not appdata:
                appdata = str(Path.home() / "AppData" / "Roaming")
                cls._logger.debug(
                    "APPDATA not set, fallback to: %s",
                    appdata,
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            config_dir = Path(appdata) / "DragonWhisperer"
        elif IS_MACOS:
            config_dir = (
                Path.home() / "Library" / "Application Support" / "DragonWhisperer"
            )
        else:
            # Linux/Unix: XDG Base Directory Specification
            xdg_config = os.environ.get("XDG_CONFIG_HOME")
            if xdg_config:
                config_dir = Path(xdg_config) / "dragonwhisperer"
            else:
                config_dir = Path.home() / ".config" / "dragonwhisperer"
            # Flatpak-Override
            if cls.is_flatpak():
                config_dir = Path.home() / ".var/app/com.dragonwhisperer/config" / "dragonwhisperer"
            elif cls.is_snap():
                config_dir = Path.home() / "snap/dragonwhisperer/current/.config/dragonwhisperer"

        if not cls._config_dir_logged:
            cls._logger.debug(
                f"Config directory: {config_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            cls._config_dir_logged = True
        return config_dir

    @classmethod
    def ensure_platform_config_dir(cls) -> Path:
        """
        Stellt sicher, dass das Konfigurationsverzeichnis existiert.

        Returns:
            Path: Das (ggf. neu erstellte) Konfigurationsverzeichnis.
        """
        config_dir = cls.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
        cls._logger.debug(
            f"Ensured config directory exists: {config_dir}",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        return config_dir

    # -------------------------------------------------------------------------
    # 4. Prozess‑Terminierung (robust, mit Kindprozessen)
    # -------------------------------------------------------------------------
    @classmethod
    def kill_process_tree(cls, pid: int, timeout: float = 5.0) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse.

        Args:
            pid: Prozess-ID des Elternprozesses.
            timeout: Maximale Zeit in Sekunden für die Terminierung.

        Returns:
            True, wenn alle Prozesse beendet wurden, sonst False.
        """
        cls._logger.debug(
            f"Killing process tree for PID {pid} (timeout={timeout}s)",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        start_time = time.monotonic()

        # ---- 1. Versuch: psutil (bevorzugt) ----
        try:
            import psutil
            parent = psutil.Process(pid)
            children = parent.children(recursive=True)
            cls._logger.debug(
                f"  psutil: Found {len(children)} child processes",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            for child in children:
                try:
                    child.terminate()
                    cls._logger.debug(
                        f"    Terminated child {child.pid}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except psutil.NoSuchProcess:
                    pass
            gone, alive = psutil.wait_procs(children, timeout=2.0)
            for child in alive:
                try:
                    child.kill()
                    cls._logger.debug(
                        f"    Killed child {child.pid}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except psutil.NoSuchProcess:
                    pass
            parent.terminate()
            parent.wait(timeout=2.0)
            cls._logger.debug(
                f"  Terminated parent {pid}", extra={"component": cls._DEBUG_COMPONENT}
            )
            return True
        except ImportError:
            cls._logger.debug(
                "  psutil not available, using fallback",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except psutil.NoSuchProcess:
            cls._logger.debug(
                f"  Process {pid} does not exist",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return True
        except Exception as e:
            cls._logger.debug(
                f"  psutil error: {e}", extra={"component": cls._DEBUG_COMPONENT}
            )

        # ---- 2. Fallback ohne psutil ----
        try:
            if IS_WINDOWS:
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=max(0.1, timeout - (time.monotonic() - start_time)),
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                # Kurze Wartezeit, bis Prozesse terminiert sind
                time.sleep(0.5)
                try:
                    os.kill(pid, 0)  # Signal 0 = nur Existenz prüfen
                    cls._logger.debug(
                        f"  Process {pid} still alive after taskkill",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    return False
                except ProcessLookupError:
                    return True
            else:
                # Unix: killpg (Prozessgruppe)
                try:
                    pgid = os.getpgid(pid)
                    os.killpg(pgid, py_signal.SIGKILL)
                    time.sleep(0.2)
                    cls._logger.debug(
                        f"  Used killpg for PID {pid} (PGID {pgid})",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    return True
                except (ProcessLookupError, PermissionError) as e:
                    cls._logger.debug(
                        f"  killpg failed: {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                # pkill als Alternative
                subprocess.run(
                    ["pkill", "-9", "-P", str(pid)],
                    capture_output=True,
                    timeout=2.0,
                    check=False,
                )
                time.sleep(0.2)
                try:
                    os.kill(pid, 0)
                    return False
                except ProcessLookupError:
                    return True
        except subprocess.TimeoutExpired:
            cls._logger.debug(
                f"  Timeout killing process tree {pid}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except (OSError, subprocess.CalledProcessError) as e:
            cls._logger.debug(
                f"  Error killing process tree {pid}: {e}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except Exception as e:
            cls._logger.debug(
                f"  Unexpected error killing process tree {pid}: {e}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        return False

    @classmethod
    def terminate_process(
        cls,
        proc: subprocess.Popen,
        *,
        child_terminate_timeout: float = 2.0,
        child_kill_wait: float = 1.0,
        parent_terminate_timeout: float = 2.0,
        parent_kill_wait: float = 1.0,
        fallback_terminate_timeout: float = 2.0,
        fallback_kill_wait: float = 1.0,
        stats_callback: Optional[Callable[[str], None]] = None,
    ) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse robust (statische Methode).

        Args:
            proc: Der zu beendende Subprozess.
            child_terminate_timeout: Timeout für SIGTERM auf Kindprozesse (psutil).
            child_kill_wait: Wartezeit nach SIGKILL auf Kindprozesse.
            parent_terminate_timeout: Timeout für SIGTERM auf Elternprozess.
            parent_kill_wait: Wartezeit nach SIGKILL auf Elternprozess.
            fallback_terminate_timeout: Timeout für Fallback‑Terminierung (ohne psutil).
            fallback_kill_wait: Wartezeit nach Fallback‑SIGKILL.
            stats_callback: Optionaler Callback für Statistik (erhält den Namen der erfolgreichen Methode).

        Returns:
            True, wenn der Prozess beendet wurde, sonst False.
        """
        if proc is None or proc.poll() is not None:
            return True

        pid = proc.pid
        if pid is None:
            # Prozess ohne PID – direkt terminate versuchen
            try:
                proc.terminate()
                proc.wait(timeout=2.0)
                return proc.poll() is not None
            except Exception:
                return False

        # 1. psutil-Zweig
        try:
            import psutil
            parent = psutil.Process(pid)
            children = parent.children(recursive=True)
            for child in children:
                try:
                    child.terminate()
                except psutil.NoSuchProcess:
                    pass
            psutil.wait_procs(children, timeout=child_terminate_timeout)
            for child in children:
                if child.is_running():
                    try:
                        child.kill()
                    except psutil.NoSuchProcess:
                        pass
            parent.terminate()
            try:
                parent.wait(timeout=parent_terminate_timeout)
                if stats_callback:
                    stats_callback("psutil")
                return True
            except psutil.TimeoutExpired:
                parent.kill()
                parent.wait(timeout=parent_kill_wait)
                if stats_callback:
                    stats_callback("psutil_kill")
                return True
        except ImportError:
            pass
        except psutil.NoSuchProcess:
            return True
        except Exception as e:
            _safe_log_debug("proc", f"psutil termination error: {e}")

        # 2. Fallback ohne psutil
        try:
            if IS_WINDOWS:
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("taskkill")
                    return True
                subprocess.run(
                    ["wmic", "process", "where", f"ParentProcessId={pid}", "call", "terminate"],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                proc.kill()
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("wmic")
                    return True
            else:
                try:
                    pgid = os.getpgid(pid)
                    os.killpg(pgid, py_signal.SIGKILL)
                    time.sleep(0.2)
                    if proc.poll() is not None:
                        if stats_callback:
                            stats_callback("killpg")
                        return True
                except (ProcessLookupError, PermissionError):
                    pass
                subprocess.run(
                    ["pkill", "-9", "-P", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                )
                os.kill(pid, py_signal.SIGKILL)
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("pkill")
                    return True
        except Exception as e:
            _safe_log_debug("proc", f"Fallback termination error: {e}")

        # 3. Letzter direkter Versuch
        try:
            proc.terminate()
            proc.wait(timeout=fallback_terminate_timeout)
            if proc.poll() is not None:
                if stats_callback:
                    stats_callback("terminate")
                return True
            proc.kill()
            proc.wait(timeout=fallback_kill_wait)
            if proc.poll() is not None:
                if stats_callback:
                    stats_callback("kill")
                return True
        except Exception:
            pass

        if stats_callback:
            stats_callback("failed")
        return False

    # -------------------------------------------------------------------------
    # 5. Abhängigkeitsprüfung (kritisch + optional)
    # -------------------------------------------------------------------------
    @classmethod
    def check_platform_dependencies(cls, force: bool = False) -> bool:
        """
        Prüft, ob alle kritischen und optionalen Abhängigkeiten vorhanden sind.

        Args:
            force: Wenn True, wird die Prüfung erzwungen (Cache ignoriert).

        Returns:
            True, wenn alle kritischen Abhängigkeiten erfüllt sind.
            Bei fehlenden kritischen Abhängigkeiten wird ein RuntimeError ausgelöst.

        Raises:
            RuntimeError: Wenn mindestens eine kritische Abhängigkeit fehlt.
        """
        with cls._dependencies_lock:
            if not force and cls._dependencies_checked:
                cls._logger.debug(
                    "Dependencies already checked, skipping",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return True

            if force:
                cls._logger.info("🔄 Forced dependency re-check requested")
                cls._dependencies_checked = False
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache.clear()

            missing_critical: List[str] = []
            issues: List[str] = []

            cls._logger.info("🔍 Checking platform dependencies...")
            cls._logger.debug(
                "Starting dependency check", extra={"component": cls._DEBUG_COMPONENT}
            )

            # Hilfsfunktion für Tool‑Prüfung (mit Cache)
            def check_tool(name: str) -> bool:
                with cls._dependencies_cache_lock:
                    now = time.monotonic()
                    entry = cls._dependencies_cache.get(f"tool_{name}")
                    if entry and now - entry[1] < cls._dependencies_cache_ttl:
                        return entry[0]
                found = cls._find_executable(name) is not None
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache[f"tool_{name}"] = (found, time.monotonic())
                return found

            cls._check_critical_tools(check_tool, missing_critical, issues)
            cls._check_optional_python_packages(issues)
            cls._check_optional_system_tools(check_tool, issues)
            cls._check_tts_components(check_tool, issues)
            cls._check_audio_players(check_tool, issues)

            if missing_critical:
                error_msg = cls._build_missing_critical_message(missing_critical, issues)
                cls._dependencies_checked = False
                raise RuntimeError(error_msg)

            if issues:
                for issue in issues:
                    cls._logger.warning(f"⚠️ {issue}")

            cls._logger.info("✅ Alle kritischen Abhängigkeiten gefunden")
            cls._dependencies_checked = True
            return True

    @classmethod
    def _check_critical_tools(cls, check_tool, missing: List[str], issues: List[str]) -> None:
        """Prüft ffmpeg und yt-dlp (kritische externe Tools)."""
        if not check_tool("ffmpeg"):
            missing.append("ffmpeg")
            issues.append("FFmpeg not found in PATH or standard locations")
            cls._logger.debug("  ✗ ffmpeg missing")
        else:
            cls._logger.debug("  ✓ ffmpeg found")

        if not check_tool("yt-dlp"):
            missing.append("yt-dlp")
            issues.append("yt-dlp not found in PATH")
            cls._logger.debug("  ✗ yt-dlp missing")
        else:
            cls._logger.debug("  ✓ yt-dlp found")

    @classmethod
    def _check_optional_python_packages(cls, issues: List[str]) -> None:
        """
        Prüft optionale Python-Pakete und fügt Warnungen zur `issues`-Liste hinzu.
        Plattformspezifische Warnungen werden nur auf dem jeweiligen Betriebssystem ausgegeben.
        Module, die später über FastLazyLoader geladen werden (whisper, torch, numpy, scipy),
        werden hier nicht als fehlend gemeldet, da sie erst nach der Abhängigkeitsprüfung
        initialisiert werden. Stattdessen werden DEBUG-Meldungen ausgegeben.
        """
        # ------------------------------------------------------------------
        # 1. Whisper-Backend (wird später geladen – keine Warnung hier)
        # ------------------------------------------------------------------
        if not FASTER_WHISPER_AVAILABLE and not OPENAI_WHISPER_AVAILABLE:
            # Nur Debug, da die Engine später in den Demo-Modus fällt
            log_debug(
                "platform",
                "Kein Whisper-Backend gefunden – wird später im Demo-Modus behandelt",
            )

        # ------------------------------------------------------------------
        # 2. deep-translator (wird später geladen)
        # ------------------------------------------------------------------
        if not TRANSLATOR_AVAILABLE:
            log_debug(
                "platform",
                "deep-translator nicht verfügbar (Übersetzung wird später ggf. eingeschränkt)",
            )

        # ------------------------------------------------------------------
        # 3. PyTorch (optional, für GPU-Beschleunigung)
        # ------------------------------------------------------------------
        if not TORCH_AVAILABLE:
            log_debug(
                "platform",
                "PyTorch nicht verfügbar – GPU-Beschleunigung deaktiviert",
            )

        # ------------------------------------------------------------------
        # 4. numpy (benötigt für Audioverarbeitung)
        # ------------------------------------------------------------------
        if not NUMPY_AVAILABLE:
            log_debug(
                "platform",
                "numpy nicht verfügbar – Audio-Verbesserungen eingeschränkt",
            )

        # ------------------------------------------------------------------
        # 5. scipy (optional, für Signalverarbeitung)
        # ------------------------------------------------------------------
        if not SCIPY_AVAILABLE:
            log_debug(
                "platform",
                "scipy nicht verfügbar – Signalverarbeitung eingeschränkt",
            )

        # ------------------------------------------------------------------
        # 6. argostranslate (offline-Übersetzung)
        # ------------------------------------------------------------------
        if not ARGOS_AVAILABLE:
            issues.append(
                "argos-translate not available (offline translation limited)"
            )

        # ------------------------------------------------------------------
        # 7. psutil (System-Monitoring)
        # ------------------------------------------------------------------
        if not PSUTIL_AVAILABLE:
            issues.append(
                "psutil not available (system monitoring limited)"
            )

        # ------------------------------------------------------------------
        # 8. pynvml (detaillierte GPU-Statistiken)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("pynvml") is None:
            # Keine Warnung, nur Debug, da es viele Systeme ohne NVIDIA-GPU gibt
            log_debug("platform", "pynvml not available (detailed GPU stats limited)")

        # ------------------------------------------------------------------
        # 9. noisereduce (Rauschunterdrückung)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("noisereduce") is None:
            issues.append(
                "noisereduce not available (audio enhancement limited)"
            )

        # ------------------------------------------------------------------
        # 10. rapidfuzz (schnelle Textähnlichkeit)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("rapidfuzz") is None:
            issues.append(
                "rapidfuzz not available (duplicate detection slower)"
            )

        # ------------------------------------------------------------------
        # 11. python-docx (Word-Export)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("docx") is None:
            issues.append(
                "python-docx not available (Word export disabled)"
            )

        # ------------------------------------------------------------------
        # 12. tiktoken (Token-Schätzung für LLM)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("tiktoken") is None:
            issues.append(
                "tiktoken not available (token estimation for LLM limited)"
            )

        # ------------------------------------------------------------------
        # 13. pyspellchecker (Hotword-Filterung)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("spellchecker") is None:
            issues.append(
                "pyspellchecker not available (hotword filtering limited)"
            )

        # ------------------------------------------------------------------
        # 14. keyring (sicherer Passwortspeicher)
        # ------------------------------------------------------------------
        if importlib.util.find_spec("keyring") is None:
            issues.append(
                "keyring not available (secure password storage disabled)"
            )

        # ------------------------------------------------------------------
        # 15. win10toast (Windows-Desktop-Benachrichtigungen)
        # ------------------------------------------------------------------
        if IS_WINDOWS and importlib.util.find_spec("win10toast") is None:
            issues.append(
                "win10toast not installed (desktop notifications disabled)"
            )

        # ------------------------------------------------------------------
        # 16. pyobjc (macOS-Desktop-Benachrichtigungen)
        # ------------------------------------------------------------------
        if IS_MACOS and importlib.util.find_spec("pyobjc") is None:
            issues.append(
                "pyobjc not installed (macOS notifications disabled)"
            )

    @classmethod
    def _check_optional_system_tools(cls, check_tool, issues: List[str]) -> None:
        """Prüft optionale System-Tools (VLC, …)."""
        vlc_found = check_tool("vlc")
        if not vlc_found and IS_WINDOWS:
            for p in [
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]:
                if os.path.exists(p):
                    vlc_found = True
                    break
        if not vlc_found:
            issues.append("vlc not found (DVB‑S streams will not work)")

    @classmethod
    def _check_tts_components(cls, check_tool, issues: List[str]) -> None:
        """Prüft TTS‑Komponenten (espeak, piper)."""
        if not check_tool("espeak"):
            issues.append("espeak not found (lightweight TTS fallback unavailable)")

        piper_found = check_tool("piper")
        if not piper_found:
            # Fallback: Prüfe, ob Piper‑Modelle im Cache existieren
            try:
                cache_dir = cls.get_piper_cache_dir()
                if os.path.isdir(cache_dir):
                    for f in os.listdir(cache_dir):
                        if f.endswith(".onnx") and os.path.getsize(os.path.join(cache_dir, f)) > 0:
                            piper_found = True
                            break
            except Exception:
                pass
        if not piper_found:
            issues.append("piper not found (high‑quality TTS will be unavailable)")

    @classmethod
    def _check_audio_players(cls, check_tool, issues: List[str]) -> None:
        """Prüft, ob mindestens ein Audio-Player verfügbar ist."""
        players = [name for name in ["ffplay", "aplay", "paplay", "sox"] if check_tool(name)]
        if not players:
            issues.append("No audio player found – TTS will not produce sound")

    @classmethod
    def _build_missing_critical_message(cls, missing: List[str], issues: List[str]) -> str:
        """Erstellt eine detaillierte Fehlermeldung für fehlende kritische Abhängigkeiten."""
        msg = f"❌ Fehlende kritische Abhängigkeiten: {', '.join(missing)}\n\n"
        msg += "\n".join(issues) + "\n"

        if "ffmpeg" in missing:
            msg += "\nFFmpeg Installation:\n"
            if IS_WINDOWS:
                msg += "  • Ausführen: winget install --source winget Gyan.FFmpeg\n"
            elif IS_MACOS:
                msg += "  • brew install ffmpeg\n"
            else:
                msg += "  • sudo apt install ffmpeg\n"
        if "yt-dlp" in missing:
            msg += "\nyt-dlp Installation:\n"
            msg += "  • pip install yt-dlp\n"
        if "tkinter" in missing:
            msg += "\nTkinter Installation:\n"
            msg += "  • Usually included with Python. On Linux: sudo apt-get install python3-tk\n"
        if "numpy" in missing:
            msg += "\nnumpy Installation:\n"
            msg += "  • pip install numpy\n"
        msg += "\n💡 Nach der Installation starten Sie Dragon Whisperer neu."
        return msg

    # -------------------------------------------------------------------------
    # 6. Pfadauflösung für ausführbare Dateien (mit Cache)
    # -------------------------------------------------------------------------
    @classmethod
    def _find_executable(cls, name: str) -> Optional[str]:
        """
        Findet eine ausführbare Datei (mit Cache). Threadsicher.

        Zuerst wird im System‑PATH gesucht, dann im Scripts‑Verzeichnis
        der aktuellen Python‑Umgebung (venv). Das Ergebnis wird gecacht.

        Args:
            name: Name der ausführbaren Datei (z. B. "ffmpeg").

        Returns:
            Absoluter Pfad zur Datei oder None, wenn nicht gefunden.
        """
        with cls._executable_cache_lock:
            if name in cls._executable_cache:
                return cls._executable_cache[name]

        exe = shutil.which(name)
        if exe:
            with cls._executable_cache_lock:
                cls._executable_cache[name] = exe
            if cls._logger.isEnabledFor(logging.DEBUG):
                cls._logger.debug(f"  → {name} gefunden im PATH: {exe}")
            return exe

        # Fallback: im Scripts-Verzeichnis des aktuellen Python-Interpreters suchen
        scripts_dir = os.path.dirname(sys.executable)
        candidate = os.path.join(scripts_dir, f"{name}{'.exe' if IS_WINDOWS else ''}")
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK if not IS_WINDOWS else os.R_OK):
            with cls._executable_cache_lock:
                cls._executable_cache[name] = candidate
            if cls._logger.isEnabledFor(logging.DEBUG):
                cls._logger.debug(f"  → {name} gefunden unter {candidate} (venv‑Fallback)")
            return candidate

        with cls._executable_cache_lock:
            cls._executable_cache[name] = None
        return None

    @classmethod
    def get_executable_path(cls, name: str) -> Optional[str]:
        """Öffentliche Methode zum Abrufen des Pfads einer ausführbaren Datei."""
        return cls._find_executable(name)

    @classmethod
    def get_ffmpeg_path(cls) -> Optional[str]:
        """
        Ermittelt den Pfad zur FFmpeg‑Executable (gecached, threadsicher).

        Returns:
            Absoluter Pfad zu ffmpeg oder None, wenn nicht gefunden.
        """
        with cls._ffmpeg_path_lock:
            if cls._ffmpeg_path is not None:
                return cls._ffmpeg_path

            env_path = os.environ.get("FFMPEG_PATH")
            if env_path and os.path.exists(env_path):
                cls._ffmpeg_path = env_path
                return cls._ffmpeg_path

            ffmpeg_path = cls._find_executable("ffmpeg")
            if ffmpeg_path:
                cls._ffmpeg_path = ffmpeg_path
                return cls._ffmpeg_path

            # Plattformspezifische Standardpfade als letzte Reserve
            if IS_WINDOWS:
                paths = [
                    "C:\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files (x86)\\ffmpeg\\bin\\ffmpeg.exe",
                ]
            elif IS_MACOS:
                paths = [
                    "/usr/local/bin/ffmpeg",
                    "/opt/homebrew/bin/ffmpeg",
                    "/usr/bin/ffmpeg",
                ]
            else:
                paths = [
                    "/usr/bin/ffmpeg",
                    "/usr/local/bin/ffmpeg",
                ]
            for path in paths:
                if os.path.exists(path):
                    cls._ffmpeg_path = path
                    return cls._ffmpeg_path

            cls._ffmpeg_path = None
            return None

    # -------------------------------------------------------------------------
    # 7. Plattforminformationen (öffentlich)
    # -------------------------------------------------------------------------
    @classmethod
    def get_platform_info(cls) -> Dict[str, Any]:
        """
        Liefert ein Dictionary mit detaillierten Plattforminformationen.

        Returns:
            Dict mit Schlüsseln wie 'system', 'is_windows', 'cpu_count', etc.
        """
        info: Dict[str, Any] = {
            "system": SYSTEM,
            "is_windows": IS_WINDOWS,
            "is_macos": IS_MACOS,
            "is_linux": IS_LINUX,
            "is_arm": IS_ARM,
            "is_x86": IS_X86,
            "is_wsl": cls.is_wsl(),
            "is_docker": cls.is_docker(),
            "is_flatpak": cls.is_flatpak(),
            "is_snap": cls.is_snap(),
            "is_containerized": cls.is_containerized(),
            "container_type": cls.get_container_type(),
            "is_headless": cls.is_headless(),
            "python_version": sys.version,
            "python_executable": sys.executable,
            "current_directory": os.getcwd(),
            "environment_setup": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "cpu_model": cls.get_cpu_model(),
            "total_ram_gb": cls.get_total_ram_gb(),
            "username": cls.get_username(),
            "hostname": cls.get_hostname(),
            "timezone": cls.get_timezone(),
            "desktop_environment": cls.get_desktop_environment(),
        }
        # CPU‑Anzahl
        try:
            import psutil
            info["cpu_count"] = psutil.cpu_count()
            info["cpu_count_logical"] = psutil.cpu_count(logical=True)
            freq = psutil.cpu_freq()
            info["cpu_freq_current_mhz"] = freq.current if freq else None
            mem = psutil.virtual_memory()
            info["memory_total_gb"] = mem.total / (1024**3)
            info["memory_available_gb"] = mem.available / (1024**3)
            info["memory_percent"] = mem.percent
            disk = psutil.disk_usage(os.getcwd())
            info["disk_free_gb"] = disk.free / (1024**3)
            info["disk_total_gb"] = disk.total / (1024**3)
        except ImportError:
            info["cpu_count"] = os.cpu_count()
            info["memory_total_gb"] = cls.get_total_ram_gb()
        except Exception as e:
            cls._logger.debug(f"psutil info error: {e}")

        # GPU-Informationen (via pynvml)
        try:
            import pynvml
            pynvml.nvmlInit()
            handle = pynvml.nvmlDeviceGetHandleByIndex(0)
            mem = pynvml.nvmlDeviceGetMemoryInfo(handle)
            info["gpu_name"] = pynvml.nvmlDeviceGetName(handle).decode()
            info["gpu_memory_total_gb"] = mem.total / (1024**3)
            info["gpu_memory_used_gb"] = mem.used / (1024**3)
            info["gpu_temperature_c"] = pynvml.nvmlDeviceGetTemperature(handle, pynvml.NVML_TEMPERATURE_GPU)
            info["gpu_utilization_percent"] = pynvml.nvmlDeviceGetUtilizationRates(handle).gpu
            pynvml.nvmlShutdown()
        except ImportError:
            pass
        except Exception as e:
            cls._logger.debug(f"pynvml error: {e}")
        return info

    @classmethod
    def print_platform_info(cls) -> None:
        """Gibt die Plattforminformationen übersichtlich im Log aus."""
        info = cls.get_platform_info()
        cls._logger.info("\n" + "=" * 60)
        cls._logger.info("🐉 PLATFORM INFORMATION")
        cls._logger.info("=" * 60)
        for key, value in info.items():
            if key not in ["environment_setup", "dependencies_checked"]:
                cls._logger.info(f"{key:25} {value}")
        cls._logger.info("-" * 60)
        cls._logger.info(
            f"{'Environment Setup':25} {'✅' if info['environment_setup'] else '❌'}"
        )
        cls._logger.info(
            f"{'Dependencies Checked':25} {'✅' if info['dependencies_checked'] else '❌'}"
        )
        cls._logger.info("=" * 60)

    @classmethod
    def get_debug_info(cls) -> Dict[str, Any]:
        """
        Liefert detaillierte Debug‑Informationen über den internen Zustand.

        Returns:
            Dict mit internen Variablen (für Diagnosezwecke).
        """
        with cls._allowed_dirs_lock:
            user_dirs = [str(p) for p in cls._user_dirs]
            base_dirs = (
                [str(p) for p in cls._get_base_dirs()]
                if cls._base_dirs is not None
                else []
            )
        return {
            "user_dirs": user_dirs,
            "base_dirs": base_dirs,
            "ffmpeg_path": cls._ffmpeg_path,
            "terminal_settings_saved": cls._terminal_settings_saved,
            "original_stty_settings": cls._original_stty_settings,
            "environment_setup_done": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "test_home_override": str(cls._test_home) if cls._test_home else None,
            "test_cwd_override": str(cls._test_cwd) if cls._test_cwd else None,
            "console_configured": cls._console_configured,
            "container_type": cls.get_container_type(),
        }

    # -------------------------------------------------------------------------
    # 8. Umgebungseinrichtung (PATH, Konsole, Terminal)
    # -------------------------------------------------------------------------
    @classmethod
    def setup_platform_environment(cls) -> None:
        """
        Richtet plattformspezifische Umgebungsvariablen und Konsolen ein.

        Diese Methode sollte einmal zu Beginn des Programms aufgerufen werden.
        Sie ist idempotent (mehrfache Aufrufe sind ungefährlich).
        """
        with cls._environment_setup_lock:
            if cls._environment_setup_done:
                cls._logger.debug(
                    "Environment already set up",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return

            cls._logger.info("🔧 Setting up platform environment...")
            cls._logger.debug(
                "Starting environment setup", extra={"component": cls._DEBUG_COMPONENT}
            )

            cls._save_terminal_settings()
            atexit.register(cls._restore_terminal_settings)

            if IS_WINDOWS:
                cls._setup_windows_console()
                atexit.register(cls._restore_windows_console)
                cls._logger.debug(
                    "Windows console setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            elif IS_MACOS:
                cls._setup_macos_temp_dir()
                cls._logger.debug(
                    "macOS temp dir setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            else:
                cls._logger.debug(
                    "Linux: no extra setup needed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                if cls.is_containerized():
                    cls._logger.info(f"🐳 Running in container: {cls.get_container_type()}")

            # Scripts‑Pfade zum PATH hinzufügen (für pip‑installierte Tools)
            cls._add_scripts_to_path()

            # Environment-Variablen für Unicode/UTF-8
            if IS_WINDOWS:
                os.environ["PYTHONIOENCODING"] = "utf-8"
            os.environ["PYTHONUTF8"] = "1"

            cls._environment_setup_done = True
            cls._logger.info("✅ Platform environment setup complete")
            cls._logger.debug(
                "Environment setup finished", extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def _add_scripts_to_path(cls) -> None:
        """Fügt die Scripts‑Verzeichnisse der aktuellen Python‑Umgebung zum PATH hinzu."""
        path_env = os.environ.get('PATH', '')
        paths_to_add: List[str] = []

        # 1. sysconfig.get_path('scripts')
        try:
            import sysconfig
            scripts_dir = sysconfig.get_path('scripts')
            if scripts_dir and os.path.isdir(scripts_dir):
                paths_to_add.append(scripts_dir)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls._logger.debug(
                    "Konnte Scripts‑Pfad (sysconfig) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        # 2. site.getuserbase()/Scripts (für --user Installationen)
        try:
            import site
            user_base = site.getuserbase()
            if IS_WINDOWS:
                user_scripts = os.path.join(user_base, 'Scripts')
            else:
                user_scripts = os.path.join(user_base, 'bin')
            if os.path.isdir(user_scripts):
                paths_to_add.append(user_scripts)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls._logger.debug(
                    "Konnte Benutzer‑Scripts‑Pfad (site) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        # 3. Direktes Scripts‑Verzeichnis des Interpreters (falls nicht schon enthalten)
        scripts_dir = os.path.dirname(sys.executable)
        if os.path.isdir(scripts_dir) and scripts_dir not in paths_to_add:
            paths_to_add.append(scripts_dir)

        for p in paths_to_add:
            if p not in path_env.split(os.pathsep):
                path_env = p + os.pathsep + path_env
                if DEBUG_LEVEL >= 2:
                    cls._logger.debug(
                        "Scripts‑Pfad zum PATH hinzugefügt: %s",
                        p,
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        os.environ['PATH'] = path_env

    # -------------------------------------------------------------------------
    # 9. Windows‑Konsolen‑Setup (UTF‑8, VT)
    # -------------------------------------------------------------------------
    @classmethod
    def _get_windows_version(cls) -> Tuple[int, int, int]:
        """Gibt Windows-Version als Tupel (major, minor, build) zurück."""
        if not IS_WINDOWS:
            return (0, 0, 0)
        try:
            import ctypes
            class OSVERSIONINFOEXW(ctypes.Structure):
                _fields_ = [
                    ('dwOSVersionInfoSize', ctypes.c_ulong),
                    ('dwMajorVersion', ctypes.c_ulong),
                    ('dwMinorVersion', ctypes.c_ulong),
                    ('dwBuildNumber', ctypes.c_ulong),
                    ('dwPlatformId', ctypes.c_ulong),
                    ('szCSDVersion', ctypes.c_wchar * 128),
                    ('wServicePackMajor', ctypes.c_ushort),
                    ('wServicePackMinor', ctypes.c_ushort),
                    ('wSuiteMask', ctypes.c_ushort),
                    ('wProductType', ctypes.c_ubyte),
                    ('wReserved', ctypes.c_ubyte)
                ]
            kernel32 = ctypes.windll.kernel32
            ver = OSVERSIONINFOEXW()
            ver.dwOSVersionInfoSize = ctypes.sizeof(ver)
            if kernel32.RtlGetVersion(ctypes.byref(ver)) == 0:
                return (ver.dwMajorVersion, ver.dwMinorVersion, ver.dwBuildNumber)
        except Exception:
            pass

        try:
            import platform
            ver = platform.version().split('.')
            if len(ver) >= 3:
                try:
                    return (int(ver[0]), int(ver[1]), int(ver[2]))
                except ValueError:
                    pass
        except Exception:
            pass
        return (0, 0, 0)

    @classmethod
    def _setup_windows_console(cls) -> bool:
        """
        Aktiviert UTF‑8 und virtuelle Terminal‑Sequenzen unter Windows,
        sofern die Windows‑Version dies unterstützt (mindestens Windows 10
        Build 10586).  Die Konfiguration wird nur einmal durchgeführt.

        Returns:
            True, wenn die Konsole erfolgreich konfiguriert wurde, sonst False.
        """
        if not IS_WINDOWS or cls._console_configured:
            return cls._console_configured

        try:
            import ctypes
            from ctypes import wintypes
        except ImportError:
            cls._logger.warning(
                "ctypes nicht verfügbar – Windows‑Konsolen‑Setup nicht möglich."
            )
            return False

        kernel32 = ctypes.windll.kernel32
        kernel32.SetConsoleCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleCP.restype = wintypes.BOOL
        kernel32.SetConsoleOutputCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleOutputCP.restype = wintypes.BOOL
        kernel32.GetConsoleMode.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD)]
        kernel32.GetConsoleMode.restype = wintypes.BOOL
        kernel32.SetConsoleMode.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetConsoleMode.restype = wintypes.BOOL

        STD_OUTPUT_HANDLE = -11
        hOut = kernel32.GetStdHandle(STD_OUTPUT_HANDLE)
        if hOut is None or hOut == ctypes.c_void_p(-1).value:
            cls._logger.warning("Standard‑Ausgabe‑Handle nicht verfügbar – Konsolen‑Setup fehlgeschlagen.")
            return False

        mode_out = wintypes.DWORD()
        if not kernel32.GetConsoleMode(hOut, ctypes.byref(mode_out)):
            cls._logger.warning("GetConsoleMode für Ausgabe fehlgeschlagen – Kann Konsolen‑Modus nicht ändern.")
            return False

        cls._original_console_mode = mode_out.value
        cls._original_console_codepage_in = kernel32.GetConsoleCP()
        cls._original_console_codepage_out = kernel32.GetConsoleOutputCP()

        # UTF‑8 setzen (65001)
        if cls._original_console_codepage_in != 65001:
            if not kernel32.SetConsoleCP(65001):
                cls._logger.warning("SetConsoleCP(65001) fehlgeschlagen – Eingabe‑Codepage nicht geändert.")
        if cls._original_console_codepage_out != 65001:
            if not kernel32.SetConsoleOutputCP(65001):
                cls._logger.warning("SetConsoleOutputCP(65001) fehlgeschlagen – Ausgabe‑Codepage nicht geändert.")

        major, minor, build = cls._get_windows_version()
        if major >= 10 and build >= 10586:
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            ENABLE_PROCESSED_OUTPUT = 0x0001
            new_mode = mode_out.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING | ENABLE_PROCESSED_OUTPUT
            if (mode_out.value & ENABLE_VIRTUAL_TERMINAL_PROCESSING) == 0:
                if kernel32.SetConsoleMode(hOut, new_mode):
                    cls._logger.debug(
                        "Windows console: VT‑Verarbeitung aktiviert (Ausgabe).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                else:
                    cls._logger.debug(
                        f"VT‑Aktivierung fehlgeschlagen – wird ignoriert (Build {build}).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        else:
            cls._logger.debug(
                f"VT processing not supported on this Windows version (build {build})",
                extra={"component": cls._DEBUG_COMPONENT},
            )

        # Optional: VT für Eingabe aktivieren (auch nur ab ausreichend neuer Version)
        if major >= 10 and build >= 10586:
            STD_INPUT_HANDLE = -10
            hIn = kernel32.GetStdHandle(STD_INPUT_HANDLE)
            if hIn not in (None, ctypes.c_void_p(-1).value):
                mode_in = wintypes.DWORD()
                if kernel32.GetConsoleMode(hIn, ctypes.byref(mode_in)):
                    ENABLE_VIRTUAL_TERMINAL_INPUT = 0x0200
                    if (mode_in.value & ENABLE_VIRTUAL_TERMINAL_INPUT) == 0:
                        kernel32.SetConsoleMode(hIn, mode_in.value | ENABLE_VIRTUAL_TERMINAL_INPUT)
                        if DEBUG_LEVEL >= 4:
                            _safe_log_debug("console", "VT‑Eingabe aktiviert.")

        cls._console_configured = True
        return True

    @classmethod
    def _restore_windows_console(cls) -> None:
        """Stellt die ursprünglichen Konsolen‑Einstellungen wieder her."""
        if not IS_WINDOWS or not cls._console_configured:
            return
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            if cls._original_console_codepage_out is not None:
                kernel32.SetConsoleOutputCP(cls._original_console_codepage_out)
            if cls._original_console_codepage_in is not None:
                kernel32.SetConsoleCP(cls._original_console_codepage_in)
            if cls._original_console_mode is not None:
                hOut = kernel32.GetStdHandle(-11)
                if hOut not in (None, ctypes.c_void_p(-1).value):
                    kernel32.SetConsoleMode(hOut, cls._original_console_mode)
            cls._logger.debug(
                "Windows‑Konsolen‑Einstellungen wiederhergestellt.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except Exception as e:
            cls._logger.debug(f"Fehler beim Wiederherstellen der Konsole: {e}")
        finally:
            cls._console_configured = False

    @classmethod
    def _setup_macos_temp_dir(cls) -> None:
        """Erstellt ein temporäres Verzeichnis für Dragon Whisperer unter macOS."""
        temp_dir = Path(tempfile.gettempdir()) / "dragonwhisperer"
        try:
            temp_dir.mkdir(parents=True, exist_ok=True)
            cls._logger.debug(
                f"macOS temp dir ensured: {temp_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except (OSError, PermissionError) as e:
            cls._logger.warning(f"⚠️ macOS temp dir creation failed: {e}")

    @classmethod
    def _save_terminal_settings(cls) -> None:
        """Speichert die aktuellen Terminal‑Einstellungen (Linux)."""
        if not IS_LINUX or cls._terminal_settings_saved:
            return
        with cls._terminal_lock:
            try:
                result = subprocess.run(
                    ["stty", "-g"],
                    capture_output=True,
                    text=True,
                    check=False,
                    timeout=2,
                )
                if result.returncode == 0 and result.stdout:
                    cls._original_stty_settings = result.stdout.strip()
                    cls._terminal_settings_saved = True
                    cls._logger.debug(
                        "Terminal settings saved",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
            except (subprocess.TimeoutExpired, OSError):
                if DEBUG_LEVEL >= 2:
                    cls._logger.debug("stty -g failed")

    @classmethod
    def _restore_terminal_settings(cls) -> None:
        """Stellt die ursprünglichen Terminal‑Einstellungen wieder her (Linux)."""
        if not IS_LINUX or cls._original_stty_settings is None:
            return
        with cls._terminal_lock:
            try:
                subprocess.run(
                    ["stty", cls._original_stty_settings], check=False, timeout=2
                )
                cls._logger.debug(
                    "Terminal settings restored",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            except Exception:
                pass

    # -------------------------------------------------------------------------
    # 10. Theme‑Anwendung auf Tkinter‑Widgets
    # -------------------------------------------------------------------------
    @classmethod
    def apply_theme_to_widget_tree(
        cls,
        root_widget: tk.Widget,
        theme: Any,
        update_idletasks: bool = True,
        include_ttk: bool = True,
        ttk_styles: Optional[Dict[str, Dict[str, str]]] = None,
    ) -> None:
        """
        Wendet das übergebene Theme rekursiv auf alle tk‑Widgets im Teilbaum an.

        Diese Methode ist iterativ (Stack) und daher auch für sehr tiefe
        Widget‑Bäume geeignet. Sie behandelt sowohl normale tk‑Widgets als auch
        ttk‑Widgets (optional) und spezielle Container wie ScrolledText oder
        PanedWindow.

        Args:
            root_widget: Wurzel-Widget (z.B. Toplevel oder Frame).
            theme: Theme-Objekt (Attribute wie BG_PRIMARY, TEXT_PRIMARY, etc.)
            update_idletasks: Wenn True, wird `update_idletasks()` aufgerufen.
            include_ttk: Wenn True, werden ttk‑Widgets mit Standard‑Styles konfiguriert.
            ttk_styles: Optionales Dict mit Style‑Überschreibungen für ttk‑Widgets.
        """
        if not GUI_AVAILABLE or root_widget is None:
            return

        # Hilfsfunktionen
        def _get_theme_attr(attr: str, fallback: str) -> str:
            try:
                return getattr(theme, attr, fallback)
            except Exception:
                try:
                    return getattr(DarkTheme(), attr, fallback)
                except Exception:
                    return fallback

        def _safe_configure(widget: tk.Widget, **kwargs: Any) -> None:
            if not kwargs:
                return
            clean = {k: v for k, v in kwargs.items() if isinstance(k, str) and k.strip()}
            if not clean:
                return
            try:
                widget.configure(**clean)
            except tk.TclError:
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug("theme", f"_safe_configure({widget}) Fehler: {e}")

        def _apply_ttk_style(widget: ttk.Widget, style_name: str) -> None:
            if not include_ttk:
                return
            try:
                style = ttk.Style()
                base_style: Dict[str, str] = {}
                if ttk_styles is not None and style_name in ttk_styles:
                    base_style.update(ttk_styles[style_name])
                base_style.setdefault("fieldbackground", _get_theme_attr("INPUT_BG", _get_theme_attr("BG_TERTIARY", "#242d38")))
                base_style.setdefault("background", _get_theme_attr("BG_TERTIARY", "#242d38"))
                base_style.setdefault("foreground", _get_theme_attr("TEXT_PRIMARY", "#e6edf3"))
                base_style.setdefault("selectbackground", _get_theme_attr("COMBO_SELECTION", "#1f6feb"))
                base_style.setdefault("selectforeground", _get_theme_attr("TEXT_PRIMARY", "#e6edf3"))
                style.configure(style_name, **base_style)
                widget.configure(style=style_name)
            except Exception:
                pass

        # Iterativer Stack
        stack: List[Union[tk.Widget, tk.Toplevel]] = [root_widget]
        total_updated = 0
        total_skipped_ttk = 0

        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue

            w_class = widget.__class__

            # ttk‑Widgets
            if issubclass(w_class, ttk.Widget):
                if not include_ttk:
                    total_skipped_ttk += 1
                    try:
                        stack.extend(widget.winfo_children())
                    except tk.TclError:
                        pass
                    continue

                style_name = None
                if isinstance(widget, ttk.Combobox):
                    style_name = "Dark.TCombobox"
                elif isinstance(widget, ttk.Progressbar):
                    style_name = "Dark.Horizontal.TProgressbar"
                elif isinstance(widget, ttk.Entry):
                    style_name = "Dark.TEntry"
                elif isinstance(widget, ttk.Label):
                    style_name = "Dark.TLabel"
                elif isinstance(widget, ttk.Button):
                    style_name = "Dark.TButton"
                if style_name:
                    _apply_ttk_style(widget, style_name)

                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Spezialfall: ScrolledText
            if w_class == scrolledtext.ScrolledText:
                try:
                    inner = widget.text
                    if inner and inner.winfo_exists():
                        _safe_configure(
                            inner,
                            bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                            fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                            selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        )
                        total_updated += 1
                except Exception:
                    pass
                try:
                    vbar = widget.vbar
                    if vbar and vbar.winfo_exists():
                        _safe_configure(
                            vbar,
                            bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                            activebackground=_get_theme_attr("SCROLLBAR_HOVER", "#999999"),
                            troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                        total_updated += 1
                except Exception:
                    pass
                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Spezialfall: PanedWindow
            if w_class == tk.PanedWindow:
                try:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        sashrelief="raised",
                        sashwidth=4,
                    )
                    total_updated += 1
                except Exception:
                    pass
                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Standard‑tk‑Widgets
            try:
                if w_class in (tk.Label,):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_PRIMARY", "#ffffff"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class in (tk.Button,):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_TERTIARY", "#cccccc"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        activebackground=_get_theme_attr("BG_HOVER", "#dddddd"),
                        activeforeground=_get_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    total_updated += 1
                elif w_class in (tk.Checkbutton, tk.Radiobutton):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        activebackground=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        activeforeground=_get_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    total_updated += 1
                elif w_class in (tk.Entry, tk.Spinbox, tk.Text):
                    input_bg = _get_theme_attr("INPUT_BG", _get_theme_attr("BG_TERTIARY", "#ffffff"))
                    _safe_configure(
                        widget,
                        bg=input_bg,
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    if w_class == tk.Spinbox:
                        _safe_configure(widget, buttonbackground=_get_theme_attr("BG_TERTIARY", "#e5e5e5"))
                    total_updated += 1
                elif w_class == tk.Frame:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                elif w_class == tk.LabelFrame:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scale:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Listbox:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scrollbar:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                        activebackground=_get_theme_attr("SCROLLBAR_HOVER", "#999999"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Canvas:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                else:
                    try:
                        widget.configure(bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                        total_updated += 1
                    except tk.TclError:
                        pass
            except (tk.TclError, AttributeError):
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug("theme", f"Fehler bei {w_class.__name__}: {e}")

            try:
                stack.extend(widget.winfo_children())
            except tk.TclError:
                pass

        if update_idletasks:
            try:
                root_widget.update_idletasks()
            except tk.TclError:
                pass

        if DEBUG_LEVEL >= 3:
            _safe_log_debug(
                "theme",
                f"apply_theme_to_widget_tree: {total_updated} tk-Widgets aktualisiert, "
                f"{total_skipped_ttk} ttk-Widgets übersprungen (include_ttk={include_ttk})",
            )

    # -------------------------------------------------------------------------
    # 11. URL‑ und Pfad‑Validierung (sicher)
    # -------------------------------------------------------------------------
    @classmethod
    def sanitize_url(cls, url: str) -> str:
        """Entfernt überflüssige Whitespaces und bereinigt die URL."""
        return url.strip() if url else ""

    @classmethod
    def validate_file_path(
        cls, file_url: str, allowed_dirs: Optional[List[str]] = None
    ) -> Tuple[bool, str]:
        """
        Validiert eine file://‑URL.

        Args:
            file_url: Die URL im Format file://...
            allowed_dirs: Zusätzlich erlaubte Verzeichnisse (optional).

        Returns:
            (True, absoluter Pfad) oder (False, Fehlermeldung).
        """
        cls._logger.debug(
            f"Validating file URL: {file_url}",
            extra={"component": cls._DEBUG_COMPONENT},
        )

        if not file_url.startswith("file://"):
            return False, "Keine file://-URL"

        try:
            if IS_WINDOWS and file_url.startswith("file:///"):
                path_part = file_url[8:]
            else:
                path_part = file_url[len("file://"):]
            path_part = urllib.request.url2pathname(path_part)
        except Exception as e:
            return False, f"Pfad kann nicht extrahiert werden: {e}"

        try:
            real_path = Path(path_part).resolve()
        except Exception as e:
            return False, f"Pfad kann nicht normalisiert werden: {e}"

        if not real_path.exists():
            return False, f"Datei existiert nicht: {real_path}"
        if not real_path.is_file():
            return False, "Keine gültige Datei (möglicherweise ein Verzeichnis)"

        allowed_bases = cls._get_allowed_dirs()
        if allowed_dirs:
            for d in allowed_dirs:
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                    if p.exists():
                        allowed_bases.append(p)
                except Exception:
                    pass

        if not allowed_bases:
            return False, "Keine erlaubten Verzeichnisse definiert"

        for base in allowed_bases:
            try:
                real_path.relative_to(base)
                return True, str(real_path)
            except ValueError:
                continue

        return False, "Datei außerhalb der erlaubten Verzeichnisse"

    @classmethod
    def validate_url(cls, url: str) -> Tuple[bool, str]:
        """
        Validiert eine beliebige URL (http, https, file, dvb, ...).

        Args:
            url: Die zu validierende URL.

        Returns:
            (True, "ok") oder (False, Fehlermeldung).
        """
        if not url:
            return False, "URL is empty"

        url = cls.sanitize_url(url)
        cls._logger.debug(
            f"Validating URL: {url}", extra={"component": cls._DEBUG_COMPONENT}
        )

        if url.startswith(("dvb://", "dvb-s://")):
            return cls._validate_dvb_url(url)
        if url.startswith("file://"):
            return cls.validate_file_path(url)

        if not url.startswith(("http://", "https://")):
            return False, f"Nicht unterstütztes URL-Schema: {url[:50]}"

        try:
            parsed = urllib.parse.urlparse(url)
            if not parsed.netloc:
                return False, "Keine Netzwerkadresse in URL"

            allowed_chars = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
            components = parsed.path + parsed.query + parsed.fragment + parsed.params
            if not re.match(f"^[{allowed_chars}]*$", components):
                return False, f"URL enthält nicht erlaubte Zeichen: {components[:50]}"

            return True, "ok"
        except Exception as e:
            return False, f"URL-Parsing fehlgeschlagen: {e}"

    @classmethod
    def _validate_dvb_url(cls, url: str) -> Tuple[bool, str]:
        """Validiert eine DVB‑URL (dvb:// oder dvb-s://)."""
        params_part = url[8:] if url.startswith("dvb-s://") else url[6:]
        allowed = r"a-zA-Z0-9=&\-_.+"
        if not re.match(f"^[{allowed}]*$", params_part):
            return False, f"DVB-Parameter enthalten ungültige Zeichen: {params_part[:50]}"
        if "frequency=" not in params_part:
            return False, "DVB-URL muss 'frequency=' enthalten"
        return True, "ok"

