    def __init__(self, parent: tk.Tk, gui_ref: Any) -> None:
        """Initialisiert den Dialog vollständig und threadsicher."""
        self.gui = gui_ref
        self._stop_event = threading.Event()
        self._current_process: Optional[subprocess.Popen] = None
        self._process_lock = threading.RLock()
        self.in_venv = hasattr(sys, "real_prefix") or (
            hasattr(sys, "base_prefix") and sys.base_prefix != sys.prefix
        )
        self.platform = SYSTEM.lower()
        self.pkg_manager = self._detect_package_manager()
        self._closed = False
        self._active_threads: List[threading.Thread] = []
        self._active_threads_lock = threading.Lock()
        self._update_running = False

        self._vlc_installed = self._is_vlc_installed()

        self._tool_installed_cache: Dict[str, bool] = {}
        self.package_labels: List[Tuple[str, tk.Label]] = []
        self._prev_available: Dict[str, bool] = {}

        super().__init__(
            parent,
            "🐉 Abhängigkeiten installieren / aktualisieren",
            width=960,
            height=820,
            modal=True,
        )
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "InstallDependencyDialog initialisiert")

    @staticmethod
    def _detect_package_manager() -> str:
        """Erkennt den bevorzugten systemeigenen Paketmanager."""
        if IS_WINDOWS:
            return "winget" if shutil.which("winget") else "manual"
        if IS_MACOS:
            return "brew" if shutil.which("brew") else "manual"
        for manager, binary in [
            ("apt", "apt-get"), ("dnf", "dnf"), ("yum", "yum"),
            ("pacman", "pacman"), ("zypper", "zypper"), ("apk", "apk"),
        ]:
            if shutil.which(binary):
                return manager
        return "manual"

    def update_critical_packages(self) -> None:
        """Startet die Aktualisierung der kritischen Python‑Pakete."""
        try:
            if self._closed or not self.dialog.winfo_exists():
                return
        except tk.TclError:
            return
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "Update kritischer Pakete gestartet")
        self._update_running = True
        if (hasattr(self, 'update_critical_btn')
                and self.update_critical_btn is not None
                and self.update_critical_btn.winfo_exists()):
            try:
                self.update_critical_btn.config(state="disabled", text="⏳ Aktualisiere...")
            except tk.TclError:
                pass
        self._enable_ui(False)
        if (hasattr(self, 'cancel_btn')
                and self.cancel_btn is not None
                and self.cancel_btn.winfo_exists()):
            try:
                self.cancel_btn.config(state="normal")
            except tk.TclError:
                pass
        self._append_output("\n⚠️ KRITISCHE PAKETE AKTUALISIEREN\n")
        for pkg in self.CRITICAL_PYTHON_PACKAGES:
            self._append_output(f"  • {pkg}\n")
        self._append_output("\n")
        thread = threading.Thread(
            target=self._update_critical_worker, daemon=True,
            name="InstallDependency-CriticalUpdateWorker",
        )
        try:
            with self._active_threads_lock:
                self._active_threads.append(thread)
            thread.start()
        except RuntimeError as exc:
            logger.error("Kritischer Update-Thread konnte nicht gestartet werden: %s", exc)
            self._append_output(f"❌ Fehler beim Starten des Updates: {exc}\n")
            self._update_running = False
            self._enable_ui(True)

    @classmethod
    def _is_vlc_installed(cls) -> bool:
        """Prüft, ob VLC Media Player installiert ist."""
        cache_attr = "_vlc_installed_cache"
        cached = getattr(cls, cache_attr, None)
        if isinstance(cached, bool):
            return cached
        try:
            if shutil.which("vlc"):
                setattr(cls, cache_attr, True)
                return True
        except Exception:
            pass
        if IS_WINDOWS:
            typical_paths = [
                os.path.expandvars(r"%ProgramFiles%\VideoLAN\VLC\vlc.exe"),
                os.path.expandvars(r"%ProgramFiles(x86)%\VideoLAN\VLC\vlc.exe"),
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]
            for path in typical_paths:
                if os.path.isfile(path):
                    setattr(cls, cache_attr, True)
                    return True
        setattr(cls, cache_attr, False)
        return False

    @staticmethod
    def _is_admin() -> bool:
        if not IS_WINDOWS:
            return True
        try:
            import ctypes
            return ctypes.windll.shell32.IsUserAnAdmin() != 0
        except Exception:
            return False

    # ------------------------------------------------------------------
    # UI‑Aufbau
    # ------------------------------------------------------------------
    def build_ui(self) -> None:
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui gestartet")
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        canvas = tk.Canvas(self.main, bg=theme.BG_PRIMARY, highlightthickness=0)
        scrollbar = tk.Scrollbar(self.main, orient="vertical", command=canvas.yview)
        self.scrollable_frame = tk.Frame(canvas, bg=theme.BG_PRIMARY)

        self.scrollable_frame.bind(
            "<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        canvas.create_window((0, 0), window=self.scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        def _on_mousewheel(event):
            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            return "break"
        def _on_mousewheel_linux(event):
            if event.num == 4:
                canvas.yview_scroll(-1, "units")
            elif event.num == 5:
                canvas.yview_scroll(1, "units")
            return "break"

        canvas.bind("<MouseWheel>", _on_mousewheel, add="+")
        canvas.bind("<Button-4>", _on_mousewheel_linux, add="+")
        canvas.bind("<Button-5>", _on_mousewheel_linux, add="+")
        self.scrollable_frame.bind("<MouseWheel>", _on_mousewheel, add="+")
        self.scrollable_frame.bind("<Button-4>", _on_mousewheel_linux, add="+")
        self.scrollable_frame.bind("<Button-5>", _on_mousewheel_linux, add="+")

        self._build_system_packages_section()
        self._build_python_packages_section()
        self._build_piper_voices_section()
        self._build_update_section()
        self._build_output_section()
        self._build_control_buttons()

        self._refresh_package_status()
        self.scrollable_frame.update_idletasks()
        canvas.configure(scrollregion=canvas.bbox("all"))
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui abgeschlossen")

    def _build_system_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        sys_frame = tk.LabelFrame(
            self.scrollable_frame, text="🖥️ Systempakete (externe Tools)",
            bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE if hasattr(Fonts, "SUBTITLE") else ("Segoe UI", 10, "bold"),
            padx=10, pady=5,
        )
        sys_frame.pack(fill="x", pady=5, padx=5)

        self.sys_vars: Dict[str, tk.BooleanVar] = {}
        for pkg_name, pkg_data in self.SYSTEM_PACKAGES.items():
            installed = self._is_tool_installed(pkg_name)
            if installed:
                tk.Label(
                    sys_frame, text=f"✅ {pkg_name} (bereits installiert)",
                    bg=theme.BG_SECONDARY, fg=theme.SUCCESS, anchor="w",
                ).pack(fill="x", pady=1)
                continue

            if not (self.pkg_manager in pkg_data or "pip" in pkg_data or "fallback" in pkg_data):
                tk.Label(
                    sys_frame, text=f"⚠️ {pkg_name} (nicht unterstützt auf diesem System)",
                    bg=theme.BG_SECONDARY, fg=theme.WARNING, anchor="w",
                ).pack(fill="x", pady=1)
                continue

            is_critical = pkg_name in self.CRITICAL_SYSTEM_PACKAGES
            var = tk.BooleanVar(value=is_critical)
            cb = tk.Checkbutton(
                sys_frame,
                text=f"{pkg_name} {'⚠️ kritisch' if is_critical else '(optional)'}",
                variable=var,
                bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
                selectcolor=theme.BG_TERTIARY, activebackground=theme.BG_HOVER,
                anchor="w",
            )
            cb.pack(fill="x", pady=1)
            self.sys_vars[pkg_name] = var
            tip = f"Installiert {pkg_name} über {self.pkg_manager or 'Fallback'}"
            if is_critical:
                tip += "\n(⚠️ Für den Betrieb zwingend erforderlich)"
            ToolTip(cb, tip)

        if not self.in_venv and not self._is_admin():
            tk.Label(
                sys_frame,
                text="⚠️  Sie installieren Pakete systemweit (kein venv).\n"
                     "   Tipp: Verwenden Sie eine virtuelle Umgebung für mehr Sicherheit.",
                bg=theme.BG_SECONDARY, fg=theme.WARNING,
                font=Fonts.SMALL if hasattr(Fonts, "SMALL") else ("Segoe UI", 7),
                justify="left",
            ).pack(fill="x", pady=5)

        if IS_WINDOWS and self.pkg_manager == "winget" and not self._is_admin():
            tk.Button(
                sys_frame, text="🛡️ Als Administrator neu starten",
                command=self._restart_as_admin,
                bg=theme.WARNING, fg=theme.TEXT_PRIMARY,
                font=Fonts.BUTTON if hasattr(Fonts, "BUTTON") else ("Segoe UI", 9),
                padx=10, pady=5, cursor="hand2",
                activebackground=theme.DRAGON_GREEN,
            ).pack(pady=(5, 0))

    def _build_python_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        py_frame = tk.LabelFrame(
            self.scrollable_frame, text="🐍 Python-Pakete (pip)",
            bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE if hasattr(Fonts, "SUBTITLE") else ("Segoe UI", 10, "bold"),
            padx=10, pady=5,
        )
        py_frame.pack(fill="x", pady=5, padx=5)

        left_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        left_col.pack(side="left", fill="both", expand=True, padx=5)
        right_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        right_col.pack(side="right", fill="both", expand=True, padx=5)

        self.py_vars: Dict[str, tk.BooleanVar] = {}
        self.package_labels.clear()
        half = len(self.PYTHON_PACKAGES) // 2
        for i, (pkg_name, display_text, check_func) in enumerate(self.PYTHON_PACKAGES):
            if pkg_name == "pywin32" and not IS_WINDOWS:
                continue
            target = left_col if i < half else right_col
            if not check_func():
                is_critical = pkg_name in self.CRITICAL_PYTHON_PACKAGES
                var = tk.BooleanVar(value=is_critical)
                cb = tk.Checkbutton(
                    target,
                    text=f"{display_text} {'⚠️' if is_critical else ''}",
                    variable=var,
                    bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY, activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.pack(fill="x", pady=1)
                self.py_vars[pkg_name] = var
                tip = f"Installiert {pkg_name} mit pip"
                if is_critical:
                    tip += "\n(⚠️ Für den Betrieb zwingend erforderlich)"
                ToolTip(cb, tip)
            else:
                lbl = tk.Label(
                    target, text=f"✅ {display_text}",
                    bg=theme.BG_SECONDARY, fg=theme.SUCCESS, anchor="w",
                )
                lbl.pack(fill="x", pady=1)
                self.package_labels.append((pkg_name, lbl))

    def _build_piper_voices_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        voice_frame = tk.LabelFrame(
            self.scrollable_frame, text="🎤 Piper-Stimmen (hochwertige TTS)",
            bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE if hasattr(Fonts, "SUBTITLE") else ("Segoe UI", 10, "bold"),
            padx=10, pady=5,
        )
        voice_frame.pack(fill="x", pady=5, padx=5)

        info_label = tk.Label(
            voice_frame,
            text="💡 Fehlt eine Sprache? Sie können Stimmen manuell von Hugging Face herunterladen.\n"
                 "   ℹ️ Bewegen Sie die Maus über diesen Text für eine Anleitung.",
            bg=theme.BG_SECONDARY, fg=theme.TEXT_SECONDARY,
            font=Fonts.SMALL if hasattr(Fonts, "SMALL") else ("Segoe UI", 7),
            justify="left",
        )
        info_label.pack(anchor="w", pady=(0, 5))

        tooltip_path = None
        try:
            if hasattr(TTSManager, "get_piper_cache_dir"):
                tooltip_path = TTSManager.get_piper_cache_dir()
            else:
                tooltip_path = os.path.join(
                    os.path.expanduser("~"),
                    ".cache" if not IS_WINDOWS else "AppData\\Roaming", "piper",
                )
        except Exception:
            tooltip_path = os.path.join(os.path.expanduser("~"), "piper_models")
        manual_steps = (
            "Manuelle Installation:\n"
            "1. Besuchen Sie: https://huggingface.co/rhasspy/piper-voices\n"
            "2. Navigieren Sie zu Sprache / Sprecher / Qualität.\n"
            "3. Laden Sie .onnx und .onnx.json herunter.\n"
            "4. Speichern Sie beide Dateien in:\n"
            f"   {tooltip_path}\n"
            "Nach einem Neustart wird die Stimme erkannt."
        )
        ToolTip(info_label, manual_steps)

        voice_buttons_frame = tk.Frame(voice_frame, bg=theme.BG_SECONDARY)
        voice_buttons_frame.pack(fill="x")

        self.voice_vars: Dict[str, tk.BooleanVar] = {}
        cache_dir = TTSManager.get_piper_cache_dir()
        os.makedirs(cache_dir, exist_ok=True)

        row, col = 0, 0
        for voice_name, display_name in self.PIPER_VOICES.items():
            model_path = os.path.join(cache_dir, f"{voice_name}.onnx")
            json_path = os.path.join(cache_dir, f"{voice_name}.onnx.json")
            fully_installed = (
                os.path.exists(model_path) and os.path.getsize(model_path) > 0
                and os.path.exists(json_path) and os.path.getsize(json_path) > 0
            )

            if not fully_installed:
                var = tk.BooleanVar(value=False)
                cb = tk.Checkbutton(
                    voice_buttons_frame, text=display_name, variable=var,
                    bg=theme.BG_SECONDARY, fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY, activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.grid(row=row, column=col, sticky="w", padx=10, pady=2)
                self.voice_vars[voice_name] = var
                if os.path.exists(model_path) and os.path.getsize(model_path) > 0:
                    ToolTip(cb, "✅ Modell vorhanden, aber Konfigurationsdatei fehlt – wird nachgeladen")
                else:
                    ToolTip(cb, f"Lädt {voice_name} herunter (ca. 50-200 MB)")
            else:
                tk.Label(
                    voice_buttons_frame, text=f"✅ {display_name}",
                    bg=theme.BG_SECONDARY, fg=theme.SUCCESS, anchor="w",
                ).grid(row=row, column=col, sticky="w", padx=10, pady=2)
            col += 1
            if col > 2:
                col = 0
                row += 1

