    # ------------------------------------------------------------------
    # Hilfsmethoden für UI‑Updates
    # ------------------------------------------------------------------
    def _safe_after(self, delay_ms: int, callback: Callable, *args, **kwargs) -> None:
        def wrapper():
            try:
                if self._closed or not self.dialog.winfo_exists():
                    return
            except tk.TclError:
                return
            try:
                callback(*args, **kwargs)
            except tk.TclError:
                pass
        self.dialog.after(delay_ms, wrapper)

    def _append_output(self, text: str) -> None:
        self._safe_after(0, lambda: self._output_text_insert(text))

    def _output_text_insert(self, text: str) -> None:
        if hasattr(self, "output_text") and self.output_text.winfo_exists():
            self.output_text.insert("end", text)
            self.output_text.see("end")

    def _update_progress(self, pct: float, step_text: str = "") -> None:
        self._safe_after(0, lambda: self.progress_var.set(min(pct, 100.0)))
        if step_text:
            self._safe_after(0, lambda: self._step_label.config(text=step_text[:80]))

    def _enable_ui(self, enabled: bool) -> None:
        self._safe_after(0, lambda: self._enable_ui_gui(enabled))

    def _enable_ui_gui(self, enabled: bool) -> None:
        if self._closed or not self.dialog.winfo_exists():
            return
        state = "normal" if enabled else "disabled"
        for widget_attr in ("install_btn", "update_critical_btn", "update_all_btn", "close_btn"):
            widget = getattr(self, widget_attr, None)
            if widget is not None and widget.winfo_exists():
                widget.config(state=state)
        for var_dict in (self.sys_vars, self.py_vars, self.voice_vars):
            for var in var_dict.values():
                widget = self._find_checkbutton_by_var(var)
                if widget and widget.winfo_exists():
                    widget.config(state=state)
        if enabled:
            if self.cancel_btn.winfo_exists():
                self.cancel_btn.config(state="disabled")
        else:
            if self.cancel_btn.winfo_exists():
                self.cancel_btn.config(state="normal")

    def _find_checkbutton_by_var(self, var: tk.BooleanVar) -> Optional[tk.Checkbutton]:
        if not hasattr(self, "scrollable_frame") or self.scrollable_frame is None:
            return None
        if self._closed or not self.dialog.winfo_exists():
            return None
        stack: List[tk.Widget] = [self.scrollable_frame]
        while stack:
            parent = stack.pop()
            try:
                if not parent.winfo_exists():
                    continue
            except tk.TclError:
                continue
            try:
                children = parent.winfo_children()
            except tk.TclError:
                continue
            for child in children:
                if isinstance(child, tk.Checkbutton):
                    try:
                        linked_var = child.cget("variable")
                    except tk.TclError:
                        continue
                    if linked_var == str(var):
                        return child
                stack.append(child)
        return None

    def _is_tool_installed(self, name: str, force_refresh: bool = False) -> bool:
        """
        Prüft, ob ein System‑Tool (z. B. ffmpeg, yt‑dlp, vlc) installiert
        und im Pfad auffindbar ist.

        Das Ergebnis wird in einem threadsicheren Cache (`_tool_installed_cache`)
        gespeichert.  Mit `force_refresh=True` wird ein vorhandener Cache‑
        Eintrag für *name* gelöscht und die Prüfung erneut durchgeführt.
        Dies wird nach einer erfolgreichen Installation des Tools aufgerufen,
        damit der Cache sofort den aktuellen Status widerspiegelt.
        """
        # Sicherstellen, dass der Cache und das Lock existieren
        if not hasattr(self, "_tool_installed_cache"):
            self._tool_installed_cache = {}
        if not hasattr(self, "_tool_installed_lock"):
            self._tool_installed_lock = threading.RLock()

        with self._tool_installed_lock:
            # Bei explizitem Refresh den alten Eintrag entfernen
            if force_refresh:
                self._tool_installed_cache.pop(name, None)

            # Cache‑Treffer ohne Refresh
            if name in self._tool_installed_cache:
                return self._tool_installed_cache[name]

        # Tatsächliche Prüfung (ohne Lock, um den kritischen Bereich klein zu halten)
        found = PlatformUtils._find_executable(name) is not None

        # Bei einigen Tools (VLC, Piper) zusätzliche plattformspezifische Prüfungen
        if not found:
            if name == "vlc" and hasattr(self, "_vlc_installed"):
                found = self._vlc_installed
            elif name == "piper" and IS_WINDOWS:
                # Suche nach piper.exe via winget-Pfad
                local_appdata = os.environ.get("LOCALAPPDATA", "")
                if local_appdata:
                    base = os.path.join(local_appdata, "Microsoft", "WinGet", "Packages")
                    pattern = os.path.join(base, "GitHub.Piper_*", "piper.exe")
                    found = bool(glob.glob(pattern))

        # Ergebnis im Cache ablegen
        with self._tool_installed_lock:
            self._tool_installed_cache[name] = found

        return found

    # ------------------------------------------------------------------
    # Statusaktualisierung
    # ------------------------------------------------------------------
    def _refresh_package_status(self) -> None:
        def _update_labels() -> None:
            try:
                if self._closed or not self.dialog.winfo_exists():
                    return
            except tk.TclError:
                return
            try:
                _PYTHON_PACKAGE_MODULE_MAP: Dict[str, str] = {
                    "deep-translator": "deep_translator",
                    "faster-whisper": "faster_whisper",
                    "psutil": "psutil",
                    "pynvml": "pynvml",
                    "argos-translate": "argostranslate",
                    "rapidfuzz": "rapidfuzz",
                    "python-docx": "docx",
                    "pyspellchecker": "spellchecker",
                    "tiktoken": "tiktoken",
                }
                try:
                    theme = self.gui.current_theme
                except Exception:
                    theme = DarkTheme()
                success_color = getattr(theme, "SUCCESS", "#238636")
                error_color = getattr(theme, "ERROR", "#f85149")
                for pkg_name, lbl in self.package_labels:
                    try:
                        if not lbl.winfo_exists():
                            continue
                    except tk.TclError:
                        continue
                    module_name = _PYTHON_PACKAGE_MODULE_MAP.get(pkg_name, pkg_name.replace("-", "_"))
                    available = False
                    try:
                        available = importlib.util.find_spec(module_name) is not None
                    except ModuleNotFoundError:
                        available = False
                    except Exception as e:
                        logger.warning(f"find_spec für {module_name} fehlgeschlagen: {e}")
                        available = False
                    was_available = self._prev_available.get(pkg_name, None)
                    if was_available is not None and available and not was_available:
                        try:
                            FastLazyLoader.clear_cache(module_name)
                        except Exception:
                            pass
                    self._prev_available[pkg_name] = available
                    status_icon = "✅" if available else "❌"
                    color = success_color if available else error_color
                    try:
                        lbl.config(text=f"{status_icon} {pkg_name}", fg=color)
                    except tk.TclError:
                        pass
            except Exception:
                pass
        self._safe_after(0, _update_labels)

    # ------------------------------------------------------------------
    # Installationslogik
    # ------------------------------------------------------------------
    def install_selected(self) -> None:
        if self._closed or not self.dialog.winfo_exists():
            return
        sys_pkgs = [pkg for pkg, var in self.sys_vars.items() if var.get()]
        py_pkgs = [pkg for pkg, var in self.py_vars.items() if var.get()]
        voices = [voice for voice, var in self.voice_vars.items() if var.get()]
        if not (sys_pkgs or py_pkgs or voices):
            self.status_var.set("❌ Nichts ausgewählt")
            return
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", f"Installation gestartet: sys={sys_pkgs}, py={py_pkgs}, voices={voices}")
        self._update_running = True
        if hasattr(self, "output_text") and self.output_text is not None and self.output_text.winfo_exists():
            try:
                self.output_text.delete("1.0", "end")
            except tk.TclError:
                pass
        self._append_output("🚀 Der Drache erhebt sich – Installation beginnt...\n")
        self._enable_ui(False)
        if hasattr(self, "cancel_btn") and self.cancel_btn is not None and self.cancel_btn.winfo_exists():
            try:
                self.cancel_btn.config(state="normal")
            except tk.TclError:
                pass
        self.status_var.set("⚙️ Installation läuft...")
        self._update_progress(0.0, "Starte…")
        self._stop_event.clear()
        thread = threading.Thread(
            target=self._install_worker, args=(sys_pkgs, py_pkgs, voices), daemon=True,
            name="InstallDependency-Worker",
        )
        try:
            with self._active_threads_lock:
                self._active_threads.append(thread)
            thread.start()
        except RuntimeError as exc:
            logger.error("Installations-Thread konnte nicht gestartet werden: %s", exc)
            self._append_output(f"❌ Fehler beim Starten der Installation: {exc}\n")
            self._update_running = False
            self._enable_ui(True)
            if hasattr(self, "cancel_btn") and self.cancel_btn is not None:
                try:
                    self.cancel_btn.config(state="disabled")
                except tk.TclError:
                    pass
            self.status_var.set("❌ Fehler beim Starten")

    def _install_worker(self, sys_pkgs, py_pkgs, voices):
        total_steps = len(sys_pkgs) + (1 if py_pkgs else 0) + (1 if voices else 0)
        current_step = 0
        def update_progress(step_text: str) -> None:
            nonlocal current_step
            pct = (current_step / max(total_steps, 1)) * 100
            self._update_progress(pct, step_text)
        try:
            for pkg in sys_pkgs:
                if self._stop_event.is_set():
                    self._append_output("⏹️ Systempakete‑Installation abgebrochen\n")
                    break
                self._append_output(f"\n📦 Installiere Systempaket: {pkg}\n")
                current_step += 1
                update_progress(f"Systempaket: {pkg}")
                success = self._install_system_package(pkg)
                self._append_output(f"{'✅' if success else '❌'} {pkg}\n")
            if py_pkgs and not self._stop_event.is_set():
                self._append_output(f"\n🐍 Python‑Pakete: {', '.join(py_pkgs)}\n")
                current_step += 1
                update_progress(f"Python‑Pakete ({len(py_pkgs)} Stück)")
                success = self._install_python_packages(py_pkgs, upgrade=True)
                self._append_output(f"{'✅' if success else '❌'} Python‑Pakete\n")
            if voices and not self._stop_event.is_set():
                self._append_output(f"\n🎤 Piper‑Stimmen: {', '.join(voices)}\n")
                current_step += 1
                update_progress(f"Piper‑Stimmen ({len(voices)} Stück)")
                success = self._download_piper_voices(voices)
                self._append_output(f"{'✅' if success else '❌'} Piper‑Stimmen\n")
            self._update_progress(100.0, "Fertig ✅")
            final_msg = ("✅ Installation abgeschlossen – bereit zum Abheben!"
                         if not self._stop_event.is_set() else "⏹️ Installation abgebrochen.")
            try:
                self.status_var.set(final_msg)
            except (tk.TclError, AttributeError):
                pass
            if not self._stop_event.is_set():
                self._refresh_package_status()
        except Exception as e:
            self._append_output(f"\n❌ Unerwarteter Fehler: {e}\n")
            self._update_progress(0.0, "Fehler ❌")
            try:
                self.status_var.set("❌ Fehler bei Installation")
            except (tk.TclError, AttributeError):
                pass
            logger.exception("Fehler in _install_worker")
        finally:
            self._update_running = False
            self._enable_ui(True)
            current = threading.current_thread()
            with self._active_threads_lock:
                try:
                    self._active_threads.remove(current)
                except ValueError:
                    pass

    def _install_system_package(self, pkg: str) -> bool:
        pkg_data = self.SYSTEM_PACKAGES.get(pkg, {})
        if IS_WINDOWS and "pip" in pkg_data:
            self._append_output(f"🐍 Installiere {pkg} über pip...\n")
            return self._install_python_packages([pkg_data["pip"]], upgrade=True)
        if self.pkg_manager == "winget" and "winget" in pkg_data:
            if not self._is_admin():
                self._append_output("⚠️ Administratorrechte erforderlich! Bitte als Admin neu starten.\n")
                return False
            cmd = [
                "winget", "install", "-e", "--id", pkg_data["winget"],
                "--accept-package-agreements", "--accept-source-agreements",
            ]
            self._append_output(f"📦 Installiere {pkg} über winget...\n")
            success = self._run_subprocess(cmd, f"Installiere {pkg}")
            if success:
                if self._is_tool_installed(pkg):
                    self._append_output(f"✅ {pkg} wurde erfolgreich installiert und gefunden.\n")
                    return True
                else:
                    self._append_output(
                        f"⚠️ {pkg} wurde installiert, aber im PATH nicht gefunden.\n"
                        "Möglicherweise müssen Sie das Programm manuell zum PATH hinzufügen.\n"
                    )
            return False
        if self.pkg_manager in pkg_data:
            cmd = self._get_package_manager_command(pkg_data[self.pkg_manager])
            if cmd:
                self._append_output(f"📦 Installiere {pkg} über {self.pkg_manager}...\n")
                success = self._run_subprocess(cmd, f"Installiere {pkg}")
                if success:
                    if self._is_tool_installed(pkg):
                        self._append_output(f"✅ {pkg} wurde erfolgreich installiert.\n")
                        return True
                    else:
                        self._append_output(f"⚠️ {pkg} wurde installiert, aber nicht im PATH gefunden.\n")
                return False
        if "pip" in pkg_data:
            self._append_output(f"🐍 Installiere {pkg} über pip...\n")
            return self._install_python_packages([pkg_data["pip"]], upgrade=True)
        if "fallback" in pkg_data:
            self._append_output(f"🔄 Verwende Fallback-Installation für {pkg}...\n")
            return self._run_fallback_install(pkg_data["fallback"])
        self._append_output(f"❌ Keine Installationsmethode für {pkg}.\n")
        return False

    def _get_package_manager_command(self, package_name: str) -> List[str]:
        manager = self.pkg_manager
        if manager == "apt":
            return ["sudo", "apt", "install", "-y", package_name]
        if manager == "dnf":
            return ["sudo", "dnf", "install", "-y", package_name]
        if manager == "yum":
            return ["sudo", "yum", "install", "-y", package_name]
        if manager == "zypper":
            return ["sudo", "zypper", "--non-interactive", "install", package_name]
        if manager == "pacman":
            return ["sudo", "pacman", "-S", "--noconfirm", package_name]
        if manager == "apk":
            return ["sudo", "apk", "add", package_name]
        if manager == "brew":
            return ["brew", "install", package_name]
        if manager == "winget":
            return [
                "winget", "install", "-e", "--id", package_name,
                "--source", "winget",
                "--accept-package-agreements", "--accept-source-agreements",
            ]
        logger.warning("_get_package_manager_command: unbekannter Paketmanager '%s'", manager)
        return []

    def _run_fallback_install(self, command: str) -> bool:
        result_container = [False]
        user_responded = threading.Event()
        def _gui_interaction() -> None:
            if not self.dialog or not self.dialog.winfo_exists():
                user_responded.set()
                return
            try:
                self.dialog.clipboard_clear()
                self.dialog.clipboard_append(command)
                copied = True
            except tk.TclError:
                copied = False
            self._append_output(
                f"\n⚠️  Aus Sicherheitsgründen wird der folgende Befehl NICHT automatisch ausgeführt.\n"
                f"Bitte führen Sie ihn manuell in einem Terminal aus.\n\n"
                f"    {command}\n\n"
                f"{'📋 Der Befehl wurde in die Zwischenablage kopiert.' if copied else ''}"
            )
            self.dialog.update_idletasks()
            if IS_WINDOWS and self.pkg_manager == "manual":
                if DarkMessageBox.askyesno(
                    "Terminal öffnen?",
                    "Möchten Sie eine Eingabeaufforderung mit dem Befehl öffnen?",
                    parent=self.dialog,
                ):
                    try:
                        subprocess.Popen(["cmd", "/K", command], creationflags=subprocess.CREATE_NEW_CONSOLE)
                    except Exception as e:
                        self._append_output(f"❌ Konnte Terminal nicht öffnen: {e}\n")
            DarkMessageBox.showinfo(
                title="Manuelle Installation erforderlich",
                message=(
                    f"Bitte öffnen Sie eine Eingabeaufforderung (cmd) und führen Sie "
                    f"den folgenden Befehl aus:\n\n"
                    f"    {command}\n\n"
                    f"Der Befehl wurde in die Zwischenablage kopiert.\n"
                    f"Klicken Sie anschließend auf OK und beantworten Sie die folgende Frage."
                ),
                parent=self.dialog, timeout=120,
            )
            self.dialog.update_idletasks()
            response = DarkMessageBox.askyesno(
                title="Installation bestätigen",
                message="Wurde der Befehl erfolgreich ausgeführt?",
                parent=self.dialog, timeout=120,
            )
            if response is True:
                result_container[0] = True
            user_responded.set()
        if self.dialog and self.dialog.winfo_exists():
            self.dialog.after_idle(_gui_interaction)
        else:
            self._append_output(f"\n⚠️  Fallback-Installation erfordert manuelle Ausführung:\n    {command}\n")
            return False
        if not user_responded.wait(timeout=130):
            self._append_output("⏰ Zeitüberschreitung – Installation nicht bestätigt.\n")
            return False
        return result_container[0]

    def _install_python_packages(self, packages: List[str], upgrade: bool = False) -> bool:
        if not packages:
            self._append_output("ℹ️ Keine Python‑Pakete angegeben – überspringe.\n")
            return True
        python_exe = sys.executable
        self._append_output("🔍 Prüfe pip…\n")
        try:
            subprocess.run([python_exe, "-m", "pip", "--version"], capture_output=True, check=True, timeout=10)
        except Exception:
            self._append_output("❌ pip ist nicht funktionsfähig. Bitte überprüfen Sie Ihre Python‑Installation.\n")
            return False
        cmd = [python_exe, "-m", "pip", "install", "--no-cache-dir", "--disable-pip-version-check"]
        if upgrade:
            cmd.append("--upgrade")
        if not self.in_venv:
            cmd.append("--user")
        cmd.extend(packages)
        env = os.environ.copy()
        env["PYTHONUNBUFFERED"] = "1"
        env["PYTHONUTF8"] = "1"
        if DEBUG_LEVEL >= 3:
            log_debug("install", f"pip install (1. Versuch): {' '.join(cmd)}")
        output = self._run_subprocess(cmd, f"pip install {' '.join(packages)}", env=env)
        success = output is not None
        if not success:
            self._append_output("⚠️ Erster Versuch fehlgeschlagen. Zweiter Versuch mit '--only-binary :all:' …\n")
            fallback_cmd = [
                python_exe, "-m", "pip", "install", "--no-cache-dir", "--disable-pip-version-check",
                "--only-binary", ":all:",
            ]
            if upgrade:
                fallback_cmd.append("--upgrade")
            if not self.in_venv:
                fallback_cmd.append("--user")
            fallback_cmd.extend(packages)
            if DEBUG_LEVEL >= 3:
                log_debug("install", f"pip install (Binary‑Fallback): {' '.join(fallback_cmd)}")
            output = self._run_subprocess(fallback_cmd, f"pip install {' '.join(packages)} (binary only)", env=env)
            success = output is not None
        if not success:
            stderr_text = getattr(self, "_last_stderr", "")
            if "externally-managed-environment" in stderr_text:
                self._append_output(
                    "\n⚠️  Ihr System schützt die systemweite Python‑Installation (PEP 668).\n"
                    "    Bitte führen Sie Dragon Whisperer in einer virtuellen Umgebung aus:\n\n"
                    "      python3 -m venv venv\n"
                    "      source venv/bin/activate\n"
                    "      pip install -r requirements.txt\n"
                    "      python dwai.py\n\n"
                    "    Alternativ können Sie die Installation mit einem risikobehafteten Flag erzwingen.\n"
                )
                if self.dialog and self.dialog.winfo_exists():
                    if DarkMessageBox.askyesno(
                        title="⚠️ Systemweite Installation erzwingen?",
                        message="Möchten Sie die Pakete trotzdem systemweit installieren?\n"
                                "Dies kann Ihre System‑Python‑Installation beschädigen!\n\n"
                                "Wir empfehlen dringend die Verwendung einer virtuellen Umgebung.",
                        parent=self.dialog,
                    ):
                        cmd_forced = cmd + ["--break-system-packages"]
                        output = self._run_subprocess(cmd_forced, "pip install (forced)", env=env)
                        success = output is not None
                        if success:
                            self._append_output("✅ Pakete trotzdem installiert.\n")
                        else:
                            self._append_output("❌ Auch die erzwungene Installation schlug fehl.\n")
                else:
                    self._append_output("ℹ️ Installation nicht erzwungen – Bitte richten Sie ein venv ein.\n")
                return success
            if "thinc" in stderr_text or "subprocess-exited-with-error" in stderr_text:
                self._append_output(
                    "\n💡 Tipp:\n"
                    "Das Paket `thinc` (oder eine andere Erweiterung) konnte nicht kompiliert werden.\n"
                    "Bitte installieren Sie einen C++ Compiler und die Python‑Entwicklungsheader:\n"
                )
                if sys.platform.startswith("linux"):
                    self._append_output(
                        "  • Debian/Ubuntu:  sudo apt install build-essential python3-dev\n"
                        "  • Fedora/RHEL:    sudo dnf install python3-devel gcc\n"
                        "  • Arch/Manjaro:   sudo pacman -S base-devel python3\n"
                        "  • openSUSE:       sudo zypper install python3-devel gcc\n"
                    )
                elif IS_WINDOWS:
                    self._append_output(
                        "  • Installieren Sie die Microsoft C++ Build Tools:\n"
                        "    https://visualstudio.microsoft.com/visual-cpp-build-tools/\n"
                    )
                else:
                    self._append_output(
                        "  • Stellen Sie sicher, dass ein C++ Compiler (gcc/clang) und python3-dev installiert sind.\n"
                    )
            elif not IS_WINDOWS:
                self._append_output(
                    "\n💡 Tipp:\n"
                    "Stellen Sie sicher, dass ein C++ Compiler (gcc/clang) und die Python‑Entwicklungsheader installiert sind:\n"
                    "  • Debian/Ubuntu:  sudo apt install build-essential python3-dev\n"
                    "  • Fedora/RHEL:    sudo dnf install python3-devel gcc\n"
                    "  • Arch/Manjaro:   sudo pacman -S base-devel python3\n"
                    "  • openSUSE:       sudo zypper install python3-devel gcc\n"
                )
            elif IS_WINDOWS:
                self._append_output(
                    "\n💡 Tipp:\n"
                    "Einige Pakete benötigen einen C++ Compiler.\n"
                    "Installieren Sie die Microsoft C++ Build Tools:\n"
                    "https://visualstudio.microsoft.com/visual-cpp-build-tools/\n"
                    "Danach das Update erneut ausführen.\n"
                )
        if success:
            try:
                for pkg in packages:
                    module = pkg.replace("-", "_")
                    try:
                        FastLazyLoader.clear_cache(module)
                    except Exception:
                        pass
                if DEBUG_LEVEL >= 3:
                    log_debug("install", "Relevante Modul‑Caches geleert")
            except Exception as e:
                logger.warning(f"Fehler beim Leeren des Modul‑Caches: {e}")
        return success

    def _download_piper_voices(self, voices: List[str]) -> bool:
        cache_dir = TTSManager.get_piper_cache_dir()
        os.makedirs(cache_dir, exist_ok=True)
        base_url = "https://huggingface.co/rhasspy/piper-voices/resolve/main"
        overall_success = True
        use_requests = importlib.util.find_spec("requests") is not None
        if not use_requests:
            self._append_output("⚠️ requests nicht installiert – verwende wget/curl (langsamer)\n")
        def download_file(remote_file: str, local_path: str, description: str) -> bool:
            url = f"{base_url}/{remote_file}"
            self._append_output(f"  ⏳ Lade {remote_file}...\n")
            max_attempts = 3
            for attempt in range(1, max_attempts + 1):
                if self._stop_event.is_set():
                    self._append_output("    ⏹️ Abgebrochen\n")
                    return False
                try:
                    if use_requests:
                        import requests as _requests
                        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
                        with _requests.get(url, headers=headers, stream=True, timeout=60) as resp:
                            if resp.status_code == 200:
                                total_size = int(resp.headers.get("content-length", 0))
                                downloaded = 0
                                self._append_output("")
                                with open(local_path, "wb") as f:
                                    for chunk in resp.iter_content(chunk_size=8192):
                                        if self._stop_event.is_set():
                                            return False
                                        f.write(chunk)
                                        downloaded += len(chunk)
                                        if total_size > 0:
                                            pct = downloaded / total_size * 100
                                            self._update_progress(
                                                pct,
                                                f"    {description}: {pct:.1f}% ({downloaded // 1024} KB / {total_size // 1024} KB)",
                                            )
                                if os.path.getsize(local_path) > 0:
                                    self._update_progress(
                                        100.0,
                                        f"    ✅ {description} abgeschlossen ({downloaded // 1024} KB)",
                                    )
                                    return True
                            else:
                                self._append_output(f"    ❌ HTTP {resp.status_code}\n")
                                return False
                    else:
                        if shutil.which("wget"):
                            cmd = ["wget", "-q", "--show-progress", "--tries=3", "--timeout=60", "-O", local_path, url]
                        elif shutil.which("curl"):
                            cmd = ["curl", "-L", "-#", "--retry", "3", "--max-time", "60", "-o", local_path, url]
                        else:
                            self._append_output("    ❌ weder wget noch curl gefunden\n")
                            return False
                        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
                        for line in proc.stdout:
                            if self._stop_event.is_set():
                                proc.kill()
                                return False
                            self._append_output(f"    {line.strip()}")
                        proc.wait()
                        if proc.returncode == 0 and os.path.getsize(local_path) > 0:
                            return True
                except Exception as e:
                    self._append_output(f"    ⚠️ Fehler: {e}\n")
                time.sleep(2 ** attempt)
            return False
        for voice in voices:
            if self._stop_event.is_set():
                self._append_output("⏹️ Download durch Benutzer abgebrochen.\n")
                overall_success = False
                break
            self._append_output(f"\n📥 Lade Stimme {voice} herunter...\n")
            model_file = f"{voice}.onnx"
            json_file = f"{voice}.onnx.json"
            model_path = os.path.join(cache_dir, model_file)
            json_path = os.path.join(cache_dir, json_file)
            parts = voice.split("-")
            if len(parts) >= 3:
                lang_full, speaker, quality = parts[0], parts[1], parts[2]
                lang_short = lang_full.split("_")[0]
                remote_dir = f"{lang_short}/{lang_full}/{speaker}/{quality}"
            else:
                remote_dir = voice
                self._append_output(f"  ⚠️ Unerwartetes Voice-Format: {voice}, versuche direkten Pfad\n")
            need_model = not os.path.exists(model_path) or os.path.getsize(model_path) == 0
            if need_model:
                if not download_file(f"{remote_dir}/{model_file}", model_path, "Modell"):
                    overall_success = False
                    continue
            else:
                self._append_output(f"  ✅ Modell {model_file} bereits vorhanden.\n")
            need_json = not os.path.exists(json_path) or os.path.getsize(json_path) == 0
            if need_json:
                if not download_file(f"{remote_dir}/{json_file}", json_path, "Konfiguration"):
                    overall_success = False
                    continue
            else:
                self._append_output(f"  ✅ Konfiguration {json_file} bereits vorhanden.\n")
            self._append_output(f"  ✅ {voice} vollständig installiert.\n")
        return overall_success

    def update_all_pip_packages(self):
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return
        self._update_running = True
        self._append_output("\n📦 ALLE PIP-PAKETE AKTUALISIEREN\n")
        self.update_status_label.config(text="🔍 Suche veraltete Pakete...")
        self.status_var.set("⏳ Paketliste wird ermittelt...")
        self._enable_ui(False)
        self.cancel_btn.config(state="normal")
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "Update aller pip‑Pakete gestartet")
        thread = threading.Thread(target=self._update_all_worker, daemon=True, name="InstallDependency-UpdateWorker")
        with self._active_threads_lock:
            self._active_threads.append(thread)
        thread.start()

    def _update_all_worker(self) -> None:
        try:
            self._append_output("\n📦 ERMITTLE VERALTETE PAKETE...\n")
            result = subprocess.run(
                [sys.executable, "-m", "pip", "list", "--outdated", "--format=json"],
                capture_output=True, text=True, timeout=30,
            )
            if result.returncode != 0:
                self._append_output(f"❌ Konnte veraltete Pakete nicht ermitteln.\n{result.stderr}\n")
                self.status_var.set("❌ Fehler bei Paketliste")
                return
            outdated = json.loads(result.stdout)
            if not outdated:
                self._append_output("✅ Alle pip-Pakete sind bereits aktuell.\n")
                self.status_var.set("✅ Alle Pakete aktuell")
                return
            packages = [pkg["name"] for pkg in outdated]
            total = len(packages)
            self._append_output(f"📦 Aktualisiere {total} Pakete einzeln...\n")
            for idx, pkg in enumerate(packages, 1):
                if pkg in self.UPDATE_BLACKLIST:
                    self._append_output(f"📦 ({idx}/{total}) ⏭️ überspringe {pkg} (systemkritisch)\n")
                    continue
                if self._stop_event.is_set():
                    self._append_output("⏹️ Abbruch durch Benutzer\n")
                    break
                self._append_output(f"📦 ({idx}/{total}) Aktualisiere {pkg}...\n")
                self._safe_after(0, lambda: self.dialog.update_idletasks())
                pkg_success = self._install_python_packages([pkg], upgrade=True)
                if not pkg_success:
                    self._append_output(f"❌ Fehler bei {pkg}\n")
                time.sleep(0.02)
            if not self._stop_event.is_set():
                self._append_output("\n✅ Alle Pakete erfolgreich aktualisiert.\n")
                self.status_var.set("✅ Aktualisierung abgeschlossen")
            else:
                self._append_output("\n⏹️ Aktualisierung abgebrochen.\n")
                self.status_var.set("⏹️ Abgebrochen")
            self._refresh_package_status()
        except subprocess.TimeoutExpired:
            self._append_output("\n❌ Timeout bei der Paketliste (30s überschritten).\n")
            self.status_var.set("❌ Timeout")
        except json.JSONDecodeError:
            self._append_output("\n❌ Konnte JSON-Ausgabe von pip nicht parsen.\n")
            self.status_var.set("❌ JSON-Fehler")
        except Exception as e:
            logger.exception("Unerwarteter Fehler in _update_all_worker")
            self._append_output(f"\n❌ Fehler: {e}\n")
            self.status_var.set("❌ Fehler bei Aktualisierung")
        finally:
            self._update_running = False
            self._restore_ui_after_update()
            current = threading.current_thread()
            with self._active_threads_lock:
                try:
                    self._active_threads.remove(current)
                except ValueError:
                    pass

    def _update_critical_worker(self) -> None:
        try:
            packages = list(self.CRITICAL_PYTHON_PACKAGES)
            if not packages:
                self._append_output("ℹ️ Keine kritischen Pakete definiert.\n")
                self.status_var.set("ℹ️ Keine kritischen Pakete")
                return
            total = len(packages)
            self._append_output(f"⚠️ Aktualisiere {total} kritische Pakete...\n")
            for pkg in packages:
                self._append_output(f"  • {pkg}\n")
            self._append_output("\n")
            for idx, pkg in enumerate(packages, 1):
                if pkg in self.UPDATE_BLACKLIST:
                    self._append_output(f"📦 ({idx}/{total}) ⏭️ überspringe {pkg} (systemkritisch)\n")
                    continue
                if self._stop_event.is_set():
                    self._append_output("⏹️ Abbruch durch Benutzer\n")
                    break
                self._append_output(f"📦 ({idx}/{total}) Aktualisiere {pkg}...\n")
                self._safe_after(0, lambda: self.dialog.update_idletasks())
                pkg_success = self._install_python_packages([pkg], upgrade=True)
                if not pkg_success:
                    self._append_output(f"❌ Fehler bei {pkg}\n")
                time.sleep(0.02)
            if not self._stop_event.is_set():
                self._append_output("\n✅ Kritische Pakete erfolgreich aktualisiert.\n")
                self.status_var.set("✅ Kritische Pakete aktualisiert")
            else:
                self._append_output("\n⏹️ Aktualisierung abgebrochen.\n")
                self.status_var.set("⏹️ Abgebrochen")
            self._refresh_package_status()
        except Exception as e:
            logger.exception("Unerwarteter Fehler in _update_critical_worker")
            self._append_output(f"\n❌ Fehler: {e}\n")
            self.status_var.set("❌ Fehler bei Aktualisierung")
        finally:
            self._update_running = False
            self._restore_ui_after_update()
            current = threading.current_thread()
            with self._active_threads_lock:
                try:
                    self._active_threads.remove(current)
                except ValueError:
                    pass

    def _restore_ui_after_update(self) -> None:
        def _gui_update():
            if self._closed or not self.dialog.winfo_exists():
                return
            try:
                self._enable_ui_gui(True)
            except Exception:
                pass
            try:
                if hasattr(self, 'update_critical_btn') and self.update_critical_btn.winfo_exists():
                    self.update_critical_btn.config(state="normal", text="⚠️ Kritische Pakete aktualisieren")
            except Exception:
                pass
            try:
                if hasattr(self, 'cancel_btn') and self.cancel_btn.winfo_exists():
                    self.cancel_btn.config(state="disabled")
            except Exception:
                pass
        self._safe_after(0, _gui_update)

    def _restart_as_admin(self) -> None:
        if not IS_WINDOWS:
            self._append_output("Unter diesem Betriebssystem nicht nötig.\n")
            return
        self._append_output("🔄 Starte das Skript mit Administratorrechten neu...\n")
        self._safe_after(500, self._perform_elevation)

    def _perform_elevation(self) -> None:
        try:
            python_exe = sys.executable
            script_path = os.path.abspath(sys.argv[0])
            ps_command = (
                f"Start-Process -FilePath '{python_exe}' "
                f"-ArgumentList '{script_path}' -Verb RunAs"
            )
            subprocess.Popen(["powershell", "-Command", ps_command], shell=False)
            self._append_output("Das Programm wird beendet. Bitte warten Sie auf das neue Fenster...\n")
            self._safe_after(500, lambda: sys.exit(0))
        except Exception as e:
            self._append_output(f"Fehler beim Neustart: {e}\n")

    # ------------------------------------------------------------------
    # ★ ROBUSTE SUBPROZESS‑AUSFÜHRUNG MIT WATCHDOG ★
    # ------------------------------------------------------------------
    def _run_subprocess(
        self, cmd: List[str], description: str = "", env: Optional[Dict] = None, timeout: int = 120
    ) -> Optional[str]:
        self._last_stderr = ""
        self._append_output(f"  🔧 {description}...\n")
        if DEBUG_LEVEL >= 3:
            log_debug("install", f"_run_subprocess: {' '.join(cmd)}")
        output_lines: List[str] = []
        stderr_lines: List[str] = []
        process_ref: List[Optional[subprocess.Popen]] = [None]
        completed = threading.Event()
        stop_flag = self._stop_event.is_set
        watchdog_timer: Optional[threading.Timer] = None
        def _watchdog():
            with self._process_lock:
                proc = process_ref[0]
            if proc is not None and proc.poll() is None:
                logger.warning("_run_subprocess: Watchdog tötet PID %d nach %ds", proc.pid, timeout)
                try:
                    PlatformUtils.terminate_process(
                        proc,
                        child_terminate_timeout=0.5, child_kill_wait=0.2,
                        parent_terminate_timeout=0.5, parent_kill_wait=0.2,
                    )
                except Exception:
                    try:
                        os.kill(proc.pid, py_signal.SIGKILL)
                    except Exception:
                        pass
            completed.set()
        watchdog_timer = threading.Timer(timeout, _watchdog)
        watchdog_timer.daemon = True
        watchdog_timer.start()
        def worker():
            proc = None
            try:
                creationflags = subprocess.CREATE_NO_WINDOW if IS_WINDOWS else 0
                proc_env = env if env is not None else os.environ.copy()
                proc = subprocess.Popen(
                    cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1,
                    env=proc_env, creationflags=creationflags,
                )
                with self._process_lock:
                    process_ref[0] = proc
                    self._current_process = proc
                for line in proc.stdout:
                    if stop_flag():
                        break
                    output_lines.append(line)
                    self._update_progress(self.progress_var.get() or 0.0, f"{description}: {line.strip()[:60]}")
                remainder = proc.stdout.read()
                if remainder:
                    output_lines.append(remainder)
                stderr_data = proc.stderr.read()
                if stderr_data:
                    encoded = stderr_data.encode("utf-8", errors="replace")[:10240]
                    stderr_lines.append(encoded.decode("utf-8", errors="ignore"))
                proc.wait()
            except Exception as e:
                logger.exception("_run_subprocess worker error")
                output_lines.append(f"\n[Exception: {e}]\n")
            finally:
                with self._process_lock:
                    if self._current_process is proc:
                        self._current_process = None
                completed.set()
        thread = threading.Thread(target=worker, daemon=True, name=f"Subprocess-{hash(tuple(cmd))}")
        thread.start()
        while not completed.is_set():
            if self._stop_event.is_set():
                with self._process_lock:
                    proc = process_ref[0]
                if proc is not None and proc.poll() is None:
                    try:
                        proc.terminate()
                        time.sleep(0.3)
                        if proc.poll() is None:
                            proc.kill()
                    except Exception:
                        pass
                completed.set()
                break
            completed.wait(0.05)
        if watchdog_timer is not None:
            watchdog_timer.cancel()
        thread.join(timeout=1.0)
        with self._process_lock:
            proc = process_ref[0]
        self._last_stderr = "".join(stderr_lines)
        stdout = "".join(output_lines).strip()
        if proc is not None and proc.returncode == 0:
            if self._last_stderr and "dependency conflict" in self._last_stderr.lower():
                self._append_output("    ℹ️ pip meldet Abhängigkeitskonflikte – Installation trotzdem ok.\n")
            return stdout
        if proc is None:
            err_msg = "Prozess konnte nicht gestartet werden."
        elif proc.returncode is None:
            err_msg = "Prozess wurde abgebrochen."
        else:
            err_msg = f"Exit-Code {proc.returncode}: {self._last_stderr[:200]}"
        if DEBUG_LEVEL >= 3:
            log_debug("install", f"_run_subprocess fehlgeschlagen: {err_msg}")
        return None

    # ------------------------------------------------------------------
    # Abbruch und Aufräumen
    # ------------------------------------------------------------------
    def cancel_installation(self) -> None:
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "cancel_installation aufgerufen")
        self._stop_event.set()
        self._terminate_current_process()
        self._append_output("\n⏹️ Abbruch durch Benutzer...\n")
        self._safe_after(0, self._perform_ui_reset)

    def _perform_ui_reset(self) -> None:
        if self._closed or not self.dialog.winfo_exists():
            return
        try:
            if self.cancel_btn.winfo_exists():
                self.cancel_btn.config(state="disabled")
        except (tk.TclError, AttributeError):
            pass
        try:
            self._enable_ui(True)
        except Exception as e:
            logger.warning("_enable_ui fehlgeschlagen: %s", e)
        try:
            self.status_var.set("⏹️ Abgebrochen")
        except (tk.TclError, AttributeError):
            pass
        if hasattr(self, "update_status_label"):
            try:
                if self.update_status_label.winfo_exists():
                    self.update_status_label.config(text="")
            except (tk.TclError, AttributeError):
                pass

    def _terminate_current_process(self) -> None:
        with self._process_lock:
            if self._current_process and self._current_process.poll() is None:
                try:
                    PlatformUtils.terminate_process(
                        self._current_process,
                        child_terminate_timeout=1.0, child_kill_wait=0.5,
                        parent_terminate_timeout=2.0, parent_kill_wait=1.0,
                        fallback_terminate_timeout=1.0, fallback_kill_wait=0.5,
                    )
                    if DEBUG_LEVEL >= 3:
                        log_debug("install_dlg", "Subprozess beendet")
                except Exception as e:
                    self._append_output(f"Fehler beim Abbrechen: {e}\n")
                self._current_process = None

    def close(self) -> None:
        """
        Schließt den Dialog ohne den GUI‑Thread zu blockieren.

        - Der modale Grab wird **sofort** freigegeben, damit nachfolgende
          Dialoge nicht blockiert werden.
        - Das Fenster wird sofort ausgeblendet.
        - Laufende Worker‑Threads werden im Hintergrund beendet und die
          endgültige Zerstörung des Fensters erfolgt asynchron.
        """
        if self._closed:
            return
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "close() aufgerufen – fahre herunter")
        self._closed = True
        self._stop_event.set()
        self._terminate_current_process()
        # ★★★ sofortiger Grab-Release ★★★
        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.grab_release()
        except tk.TclError:
            pass
        # Fenster sofort ausblenden
        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.withdraw()
        except tk.TclError:
            pass
        # Asynchrone Bereinigung
        def _finalize_close():
            with self._active_threads_lock:
                threads_snapshot = list(self._active_threads)
            for t in threads_snapshot:
                if t.is_alive():
                    try:
                        t.join(timeout=1.0)
                    except RuntimeError:
                        pass
            with self._active_threads_lock:
                self._active_threads.clear()
            self._safe_after(0, lambda: super().close())
        threading.Thread(target=_finalize_close, daemon=True, name="InstallDlg-CloseWorker").start()


