    class RateLimiter:
        """
        Begrenzt die Häufigkeit von GUI‑Updates pro Sekunde, um die
        Oberfläche vor Überlastung durch zu viele schnelle Aufrufe zu
        schützen, **ohne** dabei wichtige Meldungen zu verwerfen.
        """

        def __init__(
            self,
            max_updates_per_second: int = 120,
            important_types: Optional[Set[str]] = None,
            enabled: bool = True,
        ) -> None:
            """
            Args:
                max_updates_per_second: Maximal erlaubte Updates pro
                    Sekunde (muss > 0 sein).  Standard 120.
                important_types: Menge von Typ‑Strings, die **nie**
                    gedrosselt werden.  Wird ``None`` übergeben, wird
                    eine leere Menge verwendet (der Aufrufer kann später
                    Typen hinzufügen).
                enabled: Wenn ``False``, ist der RateLimiter deaktiviert
                    und ``can_update()`` gibt stets ``True`` zurück.
            """
            if max_updates_per_second <= 0:
                raise ValueError("max_updates_per_second must be > 0")

            self.max_updates_per_second = max_updates_per_second
            self.min_interval = 1.0 / max_updates_per_second
            self.enabled = enabled

            # Interne Daten – thread‑sicher geschützt
            self.last_calls: Dict[str, float] = {}
            self._lock = threading.RLock()
            self._cleanup_counter = 0

            # Block‑Statistik
            self._blocked_counts: Dict[str, int] = defaultdict(int)
            self._last_block_warning: float = 0.0
            self._stats_lock = threading.RLock()

            # Whitelist: diese Typen werden NIE gedrosselt
            self.important_types: Set[str] = important_types or set()

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "RateLimiter initialisiert: max=%d/s, interval=%.2fms, "
                    "important=%s, enabled=%s",
                    max_updates_per_second,
                    self.min_interval * 1000,
                    list(self.important_types),
                    enabled,
                )

        def set_max_updates_per_second(self, max_updates: int) -> None:
            """
            Ändert das Rate‑Limit zur Laufzeit.
            Negative oder Nullwerte werden ignoriert.
            """
            if max_updates <= 0:
                logger.warning(
                    "Ungültiges Rate‑Limit: %d, ignoriert", max_updates
                )
                return

            with self._lock:
                old = self.max_updates_per_second
                self.max_updates_per_second = max_updates
                self.min_interval = 1.0 / max_updates

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "Limit geändert: %d -> %d/s, interval=%.2fms",
                    old,
                    max_updates,
                    self.min_interval * 1000,
                )

        def set_enabled(self, enabled: bool) -> None:
            """Aktiviert oder deaktiviert die Drosselung vollständig."""
            with self._lock:
                self.enabled = enabled
            if DEBUG_LEVEL >= 3:
                log_debug("ratelimit", "RateLimiter enabled=%s", enabled)

        def add_important_type(self, update_type: str) -> None:
            """Fügt einen Nachrichtentyp zur Whitelist hinzu."""
            with self._lock:
                self.important_types.add(update_type)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit", "Typ '%s' zur Whitelist hinzugefügt", update_type
                )

        def remove_important_type(self, update_type: str) -> None:
            """Entfernt einen Nachrichtentyp aus der Whitelist."""
            with self._lock:
                self.important_types.discard(update_type)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "Typ '%s' aus Whitelist entfernt",
                    update_type,
                )

        def can_update(
            self,
            update_type: str = "default",
            force: bool = False,
        ) -> bool:
            """
            Prüft, ob ein Update des angegebenen Typs jetzt durchgeführt
            werden darf.

            Args:
                update_type: Ein beliebiger String zur Identifikation der
                    Update‑Art (z. B. ``"transcript"``, ``"status"``).
                force: Wenn ``True``, wird das Update **immer** erlaubt.

            Returns:
                ``True`` wenn das Update erlaubt ist, sonst ``False``.
            """
            # Erzwungene Freigabe (höchste Priorität)
            if force:
                return True

            with self._lock:
                # Wenn der Limiter insgesamt deaktiviert ist, alles durchlassen
                if not self.enabled:
                    return True

                # Whitelist‑Typen immer durchlassen, ohne Rate‑Limit
                if update_type in self.important_types:
                    # ── NEU: Debug‑Log für wichtige Updates ────────────
                    if DEBUG_LEVEL >= 4 and "ratelimit" in DEBUG_COMPONENTS:
                        log_debug(
                            "ratelimit",
                            "Important update ALLOWED: type='%s', force=%s",
                            update_type, force,
                        )
                    return True

                now = time.monotonic()
                last = self.last_calls.get(update_type, 0.0)

                if now - last >= self.min_interval:
                    self.last_calls[update_type] = now
                    if DEBUG_LEVEL >= 4:
                        delta_ms = (now - last) * 1000.0 if last != 0.0 else 0.0
                        log_debug(
                            "ratelimit",
                            "Update allowed: type='%s', delta=%.2fms",
                            update_type,
                            delta_ms,
                        )
                    self._cleanup_counter += 1
                    if self._cleanup_counter % 1000 == 0:
                        self._cleanup_stale_entries(now)
                    return True

                # Zu schnell – blockieren und Statistik führen
                if DEBUG_LEVEL >= 4:
                    delta_ms = (now - last) * 1000.0
                    log_debug(
                        "ratelimit",
                        "Update blocked: type='%s', delta=%.2fms < %.2fms",
                        update_type,
                        delta_ms,
                        self.min_interval * 1000,
                    )

                # Block‑Zähler erhöhen (threadsicher)
                with self._stats_lock:
                    self._blocked_counts[update_type] += 1

                with self._stats_lock:
                    total_blocks = sum(self._blocked_counts.values())
                    if total_blocks >= 60:
                        if now - self._last_block_warning >= 60.0:
                            logger.warning(
                                "RateLimiter: %d blockierte Updates in der "
                                "letzten Minute. Häufigste Typen: %s",
                                total_blocks,
                                sorted(
                                    self._blocked_counts.items(),
                                    key=lambda x: x[1],
                                    reverse=True,
                                )[:5],
                            )
                            self._blocked_counts.clear()
                            self._last_block_warning = now

                return False

        def get_block_stats(self) -> Dict[str, Any]:
            """
            Gibt die aktuellen Block‑Statistiken als Dictionary zurück.
            Die Zähler werden **nicht** zurückgesetzt.
            """
            with self._stats_lock:
                copy = dict(self._blocked_counts)
            return {
                "total_blocks": sum(copy.values()),
                "per_type": copy,
            }

        def get_stats(self) -> Dict[str, Any]:
            """Gibt aktuelle Statistiken als Dictionary zurück."""
            with self._lock:
                return {
                    "max_updates_per_second": self.max_updates_per_second,
                    "min_interval_ms": round(self.min_interval * 1000, 2),
                    "enabled": self.enabled,
                    "active_types": len(self.last_calls),
                    "type_list": list(self.last_calls.keys()),
                    "important_types": list(self.important_types),
                }

        def reset(self, update_type: Optional[str] = None) -> None:
            """
            Setzt den internen Zähler zurück.

            Args:
                update_type: Nur diesen Typ zurücksetzen.  Wenn ``None``,
                    werden **alle** Typen zurückgesetzt.
            """
            with self._lock:
                if update_type is None:
                    count = len(self.last_calls)
                    self.last_calls.clear()
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ratelimit", "Alle %d Einträge zurückgesetzt", count
                        )
                else:
                    if update_type in self.last_calls:
                        del self.last_calls[update_type]
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ratelimit", "Typ '%s' zurückgesetzt", update_type
                            )
                    else:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ratelimit",
                                "Typ '%s' nicht gefunden – ignoriert",
                                update_type,
                            )

        def _cleanup_stale_entries(self, now: float) -> None:
            """
            Entfernt Einträge, die länger als das 10‑fache des minimalen
            Intervalls nicht mehr verwendet wurden.
            """
            threshold = now - (self.min_interval * 10)
            stale = [
                key
                for key, last_time in self.last_calls.items()
                if last_time < threshold
            ]
            for key in stale:
                del self.last_calls[key]

            if stale and DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "%d veraltete Einträge bereinigt",
                    len(stale),
                )

        def __repr__(self) -> str:
            with self._lock:
                return (
                    f"<RateLimiter max={self.max_updates_per_second}/s, "
                    f"enabled={self.enabled}, "
                    f"active={len(self.last_calls)}, "
                    f"important={list(self.important_types)}>"
                )

    @staticmethod
    def gui_error_handler(func: Callable) -> Callable:
        """Dekorator für GUI‑Methoden: fängt Exceptions ab und zeigt sie an."""

        @wraps(func)
        def wrapper(self, *args, **kwargs):
            try:
                return func(self, *args, **kwargs)
            except Exception as e:
                logger.exception(f"Fehler in {func.__name__}: {e}")
                self.update_status(f"❌ Interner Fehler: {str(e)[:50]}")

        return wrapper

    def __init__(self) -> None:
        """Initialisiert die DragonWhispererGUI – das Hauptfenster der Anwendung.

        Sammelt während der Initialisierung alle nicht‑fatalen Fehler in
        ``self._init_errors`` und zeigt sie nach dem Aufbau der GUI in einem
        Dialog an, sodass der Benutzer immer erfährt, wenn optionale
        Komponenten nicht geladen werden konnten.
        """
        # -- Fehlersammlung für nicht‑kritische Initialisierungsprobleme --
        self._init_errors: List[str] = []

        # -- RateLimiter mit erhöhter Obergrenze und Whitelist für wichtige Nachrichten --
        self._gui_update_limiter = self.RateLimiter(
            max_updates_per_second=120,
            important_types={
                "status",
                "info",
                "error",
                "controller_state",
                "transcription",
                "translation",
                "gui_callback",
            },
        )
        self._shutting_down = False
        self._shutdown_lock = threading.RLock()
        self._exit_dialog_active = False
        self._cleanup_done = False
        self._shutdown_completed = False
        self._dependency_issue = False
        self._install_dialog_open = False
        if DEBUG_LEVEL >= 3:
            log_debug("gui", "RateLimiter und Shutdown-Flags initialisiert")

        # ══════════════════════════════════════════════════════════════
        # Attribute, die VOR _init_managers / _init_engines benötigt werden
        # (u.a. update_status() im Demo-Modus)
        # ══════════════════════════════════════════════════════════════
        self._status_lock = threading.RLock()
        self._last_status_message = ""
        self._last_low_conf_warning_time = 0.0
        self._last_valid_language = None

        self._vram_idle_timer: Optional[str] = None
        self._save_settings_timer: Optional[str] = None
        self._tts_timer: Optional[str] = None

        # ------------------------------------------------------------------
        # 1. Benutzereinstellungen laden (mit Fallback)
        # ------------------------------------------------------------------
        try:
            self.settings = AppSettings.load_from_file()
        except Exception as e:
            self._init_errors.append(f"Einstellungen konnten nicht geladen werden: {e}")
            self.settings = AppSettings()

        # ------------------------------------------------------------------
        # 2. Erweiterte Einstellungen laden und Verzeichnis‑Whitelist setzen
        # ------------------------------------------------------------------
        try:
            self.advanced_settings = get_advanced_settings()
            PlatformUtils.set_allowed_dirs(self.advanced_settings.allowed_dirs)
        except Exception as e:
            self._init_errors.append(f"Erweiterte Einstellungen konnten nicht geladen werden: {e}")
            self.advanced_settings = AdvancedSettings()

        # ------------------------------------------------------------------
        # 3. TTS‑Manager – kann fehlschlagen, wenn piper / espeak fehlen
        # ------------------------------------------------------------------
        try:
            self.tts_manager: Optional[TTSManager] = TTSManager(self.advanced_settings)
        except Exception as e:
            self._init_errors.append(f"TTS‑Manager konnte nicht gestartet werden: {e}")
            self.tts_manager = None

        # ------------------------------------------------------------------
        # 4. Einstellungen reparieren, falls nötig
        # ------------------------------------------------------------------
        try:
            self.advanced_settings.repair()
        except Exception:
            pass

        if DEBUG_LEVEL >= 3:
            log_debug("gui", "Einstellungen erfolgreich geladen")

        self._show_cookie_notice = (
            not self.settings.cookies_notice_shown
            and self.settings.use_browser_cookies
        )

        # ------------------------------------------------------------------
        # 5. App‑Kontext, Event‑Bus, Theme
        # ------------------------------------------------------------------
        try:
            self.app_context = AppContext()
            self.event_bus = self.app_context.event_bus
            self.current_theme = self.app_context.theme
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "AppContext und Event-Bus initialisiert")
        except Exception as e:
            self._init_errors.append(f"AppContext konnte nicht initialisiert werden: {e}")
            raise RuntimeError(f"AppContext konnte nicht initialisiert werden: {e}") from e

        # ------------------------------------------------------------------
        # 6. Grundlegende GUI‑Attribute
        # ------------------------------------------------------------------
        self.demo_mode = not WHISPER_AVAILABLE
        self.layout_mode = getattr(self.settings, "layout_mode", "vertical")
        self.target_language = self.advanced_settings.target_language
        self.current_language = self.target_language
        target_lang_name = SUPPORTED_LANGUAGES.get(self.target_language, "Deutsch")
        self._last_valid_language = target_lang_name
        self.is_processing = False
        self.subtitle_mode = False
        self._translate_active: bool = True
        self._translate_lock: threading.RLock = threading.RLock()
        self.exit_confirmed = False
        self.current_stream_info: Optional[StreamInfo] = None
        self.last_completed_stream_info: Optional[StreamInfo] = None
        self.last_stream_title: str = ""
        self.current_video_language: Optional[str] = None
        self._progress_bar_started = False
        self.translate_active = True

        # ------------------------------------------------------------------
        # 7. Nebenläufige Verarbeitung (Translation Executor)
        # ------------------------------------------------------------------
        try:
            self.translation_executor: Optional[ThreadPoolExecutor] = ThreadPoolExecutor(
                max_workers=1, thread_name_prefix="Translation"
            )
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "Translation Executor gestartet")
        except Exception as e:
            self._init_errors.append(f"Translation‑Executor konnte nicht gestartet werden: {e}")
            self.translation_executor = None

        # ------------------------------------------------------------------
        # 8. Historien‑ und Duplikats‑Locks
        # ------------------------------------------------------------------
        self._history_lock = threading.RLock()
        self._duplicate_lock = threading.RLock()
        self._last_transcription_text = ""
        self._last_translation_text = ""
        self._last_output_translation = ""
        self.transcript_history: Deque[TranscriptionResult] = deque(maxlen=1000)
        self.translation_history: Deque[TranslationResult] = deque(maxlen=500)
        self._open_dialogs: List[tk.Toplevel] = []
        self._tts_active = False
        self._tts_lock = threading.RLock()
        self._pending_tts_transcript = ""
        self._pending_tts_translation = ""
        self._stopping_done = False
        self._current_layout: Optional[str] = None
        self._subscriptions_lock = threading.RLock()
        self._event_subscriptions: List[Tuple[str, Callable]] = []

        self._register_event_bus_subscriptions()
        self.event_bus.subscribe("gpu_status_changed", self._on_gpu_status_changed)

        # Einmalige, typisierte Initialisierung aller später mehrfach verwendeten Attribute
        self._already_flushed_texts: Set[str] = set()
        self._last_tts_texts: Deque[str] = deque(maxlen=5)
        self._install_dialog: Optional[Any] = None
        self._subtitle_anim_id: Optional[str] = None
        self._live_mode_toggle_time: float = 0.0
        self._blacklist_regex_cache: Dict[str, Any] = {}

        if DEBUG_LEVEL >= 3:
            log_debug("gui", "_already_flushed_texts initialisiert")

        # ------------------------------------------------------------------
        # 9. Controller und zentrale Verarbeitungsobjekte
        # ------------------------------------------------------------------
        try:
            self.controller = WhisperController(gui_ref=self, event_bus=self.event_bus)
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "WhisperController erstellt")
        except Exception as e:
            self._init_errors.append(f"Controller Fehler: {e}")
            raise RuntimeError(f"Controller Fehler: {e}") from e

        self._init_managers()
        self._init_engines()

        # ------------------------------------------------------------------
        # 10. Automatische Modellauswahl (falls noch nicht gesetzt)
        # ------------------------------------------------------------------
        try:
            if self.settings.default_model is None:
                free_vram = self._get_free_vram_gb()
                if free_vram is not None:
                    if free_vram < 1.5:
                        default = "tiny"
                    elif free_vram < 2.5:
                        default = "base"
                    elif free_vram < 4.0:
                        default = "small"
                    elif free_vram < 7.0:
                        default = "medium"
                    else:
                        default = "large-v3-turbo"
                    reason: str = f"freier VRAM: {free_vram:.1f} GB"
                    logger.info(f"✅ Automatische Modellauswahl (GPU): '{default}' ({reason})")
                    self.update_status(f"🤖 Modell '{default}' gewählt ({reason})")
                else:
                    try:
                        import psutil
                        ram_gb = psutil.virtual_memory().total / (1024**3)
                        if ram_gb < 4.0:
                            default = "tiny"
                        elif ram_gb < 8.0:
                            default = "base"
                        elif ram_gb < 16.0:
                            default = "small"
                        elif ram_gb < 32.0:
                            default = "medium"
                        else:
                            default = "large-v3-turbo"
                        reason = f"RAM: {ram_gb:.1f} GB"
                        logger.info(f"✅ Automatische Modellauswahl (CPU): '{default}' ({reason})")
                        self.update_status(f"🤖 Modell '{default}' gewählt ({reason})")
                    except ImportError:
                        default = "base"
                        reason = "psutil nicht verfügbar – Fallback"
                        logger.warning(f"⚠️ psutil fehlt – verwende Standardmodell '{default}'")
                        self.update_status(f"⚠️ Modell '{default}' (RAM unbekannt)")
                    except Exception as e:
                        default = "base"
                        reason = f"Fehler bei RAM‑Ermittlung: {e}"
                        logger.error(f"❌ RAM‑Ermittlung fehlgeschlagen: {e}")
                        self.update_status(f"⚠️ Modell '{default}' (RAM‑Fehler)")

                self.settings.default_model = default
                try:
                    self.settings.save_to_file()
                except Exception:
                    pass
                if hasattr(self, "model_var") and self.model_var is not None:
                    self.model_var.set(default)
        except Exception as e:
            logger.error(f"Fehler bei automatischer Modellauswahl: {e}")
            self.settings.default_model = "base"
            try:
                self.settings.save_to_file()
            except Exception:
                pass
            if hasattr(self, "model_var") and self.model_var is not None:
                self.model_var.set("base")

        # ------------------------------------------------------------------
        # 11. Precision / High-Accuracy Overrides
        # ------------------------------------------------------------------
        self._apply_precision_optimizations()
        self._last_low_conf_warning_time = 0.0
        self._volume_popup: Optional[tk.Toplevel] = None
        self._last_transcription_time = time.time()

        # ------------------------------------------------------------------
        # 12. Tkinter‑Root erzeugen
        # ------------------------------------------------------------------
        try:
            self.root = tk.Tk()
            self.root.withdraw()
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "Tkinter Root erstellt")
        except (tk.TclError, RuntimeError) as e:
            raise RuntimeError(f"Tkinter Fehler: {e}") from e

        # ------------------------------------------------------------------
        # 13. Tkinter‑Exception‑Handler im Hauptthread
        # ------------------------------------------------------------------
        def _tk_exception_handler(
            exc_type: type, exc_val: BaseException, exc_tb: Any
        ) -> None:
            import traceback
            tb_lines = traceback.format_exception(exc_type, exc_val, exc_tb)
            full_tb = "".join(tb_lines)
            logger.error("Tkinter callback error:\n%s", full_tb)

            now = time.monotonic()
            last_time = getattr(self, "_last_tk_error_time", 0.0)
            if now - last_time < 60.0:
                if DEBUG_LEVEL >= 4:
                    log_debug("gui", "Unterdrücke wiederholte GUI‑Fehlermeldung")
                return
            self._last_tk_error_time = now

            short_msg = f"{exc_type.__name__}: {exc_val}"
            if len(short_msg) > 500:
                short_msg = short_msg[:497] + "..."
            detail_msg = (
                f"Ein unbehandelter Fehler ist in der GUI aufgetreten:\n\n"
                f"{short_msg}\n\n"
                f"Der vollständige Traceback wurde in die Log‑Datei geschrieben.\n"
                f"Sie können den Fehler mit Strg+C in die Zwischenablage kopieren."
            )
            try:
                DarkMessageBox.showerror("GUI‑Fehler", detail_msg, parent=self.root)
                if hasattr(self, "root") and self.root.winfo_exists():
                    self.root.clipboard_clear()
                    self.root.clipboard_append(full_tb)
            except Exception:
                logger.exception("Konnte GUI‑Fehlerdialog nicht anzeigen")

        self.root.report_callback_exception = _tk_exception_handler

        # ------------------------------------------------------------------
        # 14. Event‑Bus an GUI‑Thread binden
        # ------------------------------------------------------------------
        self.event_bus.set_scheduler(
            lambda delay, cb, *args: self.root.after(delay, cb, *args)
        )

        # ------------------------------------------------------------------
        # 15. Auto‑TTS Variablen (Thread‑sicher)
        # ------------------------------------------------------------------
        self.auto_tts_transcript_var = tk.BooleanVar(
            value=self.advanced_settings.auto_tts_transcript
        )
        self.auto_tts_translation_var = tk.BooleanVar(
            value=self.advanced_settings.auto_tts_translation
        )

        # ------------------------------------------------------------------
        # 16. Fenstertitel und Queues
        # ------------------------------------------------------------------
        self.root.title(
            "🐉 Dragon Whisperer" if not self.demo_mode else "🐉 Dragon Whisperer (DEMO MODE)"
        )

        try:
            self.gui_queue: queue.Queue = queue.Queue(maxsize=200)
        except Exception as e:
            logger.warning(f"GUI-Queue konnte nicht erstellt werden: {e}, verwende DummyQueue")
            self.gui_queue = DummyQueue(maxsize=200)

        try:
            self._text_update_queue: queue.Queue = queue.Queue(maxsize=150)
        except Exception as e:
            logger.warning(f"Text-Queue konnte nicht erstellt werden: {e}, verwende DummyQueue")
            self._text_update_queue = DummyQueue(maxsize=150)

        self.performance_monitor = SimplePerformanceTracker()
        self._last_text_queue_size = 0
        self.stream_info_extractor = StreamInfoExtractor()
        self.stream_info_extractor.use_browser_cookies = self.settings.use_browser_cookies

        # ------------------------------------------------------------------
        # 17. Layout und Queue‑Manager (GUI‑Setup)
        # ------------------------------------------------------------------
        self.layout = WhisperLayoutManager(gui_ref=self)
        self.queue_manager = QueueManager(self)

        try:
            self._adaptive_window_size()
            self.layout.setup_gui()
            if hasattr(self, "model_var") and self.model_var:
                self.model_var.set(self.settings.default_model)
            self._setup_callbacks()
            self.vad_fallback_enabled = tk.BooleanVar(
                value=self.advanced_settings.vad_fallback_enabled
            )
            self.status_bar = StatusBar(self.root, self, demo_mode=self.demo_mode)
            self.status_bar.frame.grid(row=4, column=0, sticky="ew", pady=(2, 0))
            self._update_vad_fallback_button()
            self._update_live_mode_button()
            self._start_gui_updaters()
            self._set_initial_url()
            self.root.update_idletasks()
            self.root.resizable(True, True)
            self.root.deiconify()
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "GUI erfolgreich aufgebaut und angezeigt")
        except Exception as e:
            self._init_errors.append(f"GUI Setup Fehler: {e}")
            logger.exception(f"❌ GUI Setup Fehler: {e}")
            try:
                self.root.deiconify()
            except Exception:
                pass

        # ------------------------------------------------------------------
        # 18. Signal‑Handler für sauberes Beenden (defensiv)
        # ------------------------------------------------------------------
        if hasattr(self, '_register_signal_handlers'):
            self._register_signal_handlers()
        else:
            logger.warning(
                "DragonWhispererGUI._register_signal_handlers is missing – "
                "signal handlers will not be installed."
            )

        # ------------------------------------------------------------------
        # 19. Cookie‑Notice, Tastenkürzel und Systemüberwachung
        # ------------------------------------------------------------------
        if self._show_cookie_notice and not self._dependency_issue:
            self._safe_after(500, self._show_cookie_notice_dialog)

        if hasattr(self, '_bind_shortcuts'):
            self._bind_shortcuts()
        else:
            logger.warning(
                "DragonWhispererGUI._bind_shortcuts is missing – "
                "keyboard shortcuts will not be available."
            )

        self._safe_after(1000, self._start_system_monitoring)
        self._safe_after(2000, self._final_initialization_check)
        self._schedule_gui_health_check()
        atexit.register(self._atexit_cleanup)
        self._schedule_vram_idle_check()

        # ------------------------------------------------------------------
        # 20. Fehlende kritische Abhängigkeiten → Installations‑Dialog anbieten
        # ------------------------------------------------------------------
        missing_ffmpeg = not shutil.which("ffmpeg")
        missing_ytdlp = not shutil.which("yt-dlp")
        missing_numpy = not NUMPY_AVAILABLE
        if missing_ffmpeg or missing_ytdlp or missing_numpy:
            self._dependency_issue = True

            def _open_installer() -> None:
                if not self.is_shutting_down() and hasattr(self, "show_install_dialog"):
                    self.show_install_dialog()

            self._safe_after(1500, _open_installer)

        # ------------------------------------------------------------------
        # 21. Gesammelte Initialisierungsfehler anzeigen
        # ------------------------------------------------------------------
        if self._init_errors:
            error_text = "Die folgenden Probleme wurden beim Start festgestellt:\n\n"
            error_text += "\n".join(f"• {err}" for err in self._init_errors)
            error_text += "\n\nEinige Funktionen sind möglicherweise eingeschränkt."

            def _show_init_errors() -> None:
                try:
                    DarkMessageBox.showwarning(
                        "Start‑Warnungen",
                        error_text,
                        parent=self.root,
                    )
                except Exception:
                    logger.warning("Konnte Start‑Warnungen nicht anzeigen: %s", error_text)

            self._safe_after(800, _show_init_errors)

        # ------------------------------------------------------------------
        # 22. Automatisches Laden des Standardmodells (asynchron) mit Events
        # ------------------------------------------------------------------
        if not self.demo_mode and self.settings.default_model:
            default_model = self.settings.default_model
            if default_model in Config.WHISPER_MODELS:
                self.update_status(f"🤖 Lade Modell {default_model}...")

                # ★ Event senden, um den Start-Button zu deaktivieren
                self.event_bus.emit("model_load_started", {"model": default_model})

                def _load_model_async() -> None:
                    try:
                        self.transcription_engine.load_model(default_model, set_active=True)
                        current = self.transcription_engine.get_current_model()
                        if current == default_model:
                            def _success() -> None:
                                self.update_status(f"✅ Modell {default_model} geladen")
                            self.root.after(0, _success)
                        else:
                            def _fail() -> None:
                                self.update_status(f"⚠️ Modell {default_model} konnte nicht geladen werden")
                            self.root.after(0, _fail)
                    except Exception as e:
                        logger.exception(f"Fehler beim automatischen Laden von {default_model}: %s", e)
                        def _error() -> None:
                            self.update_status(f"❌ Fehler beim Laden von {default_model}")
                        self.root.after(0, _error)
                    finally:
                        # ★ Event senden, um den Start-Button wieder zu aktivieren
                        self.event_bus.emit("model_load_finished", None)

                threading.Thread(target=_load_model_async, daemon=True, name="AutoLoadModel").start()
            else:
                logger.warning(f"Standardmodell '{default_model}' unbekannt – kein Auto‑Load.")

        if DEBUG_LEVEL >= 2:
            log_debug("gui", "DragonWhispererGUI.__init__ erfolgreich abgeschlossen")

    # ------------------------------------------------------------------
    # Thread‑sichere Properties für Duplikaterkennung
    # ------------------------------------------------------------------
    @property
    def last_transcription_text(self) -> str:
        """Gibt den letzten transkribierten Text thread‑sicher zurück."""
        with self._duplicate_lock:
            return self._last_transcription_text

    @last_transcription_text.setter
    def last_transcription_text(self, value: str) -> None:
        """Setzt den letzten transkribierten Text thread‑sicher."""
        with self._duplicate_lock:
            self._last_transcription_text = value

    @property
    def last_translation_text(self) -> str:
        """Gibt den letzten übersetzten Text thread‑sicher zurück."""
        with self._duplicate_lock:
            return self._last_translation_text

    @last_translation_text.setter
    def last_translation_text(self, value: str) -> None:
        """Setzt den letzten übersetzten Text thread‑sicher."""
        with self._duplicate_lock:
            self._last_translation_text = value

    def _set_initial_url(self) -> None:
        """Setzt die initiale URL im Eingabefeld, falls vorhanden."""
        if hasattr(self, "url_entry") and self.url_entry.winfo_exists():
            self.url_entry.delete(0, "end")
            self.url_entry.insert(0, self.settings.last_url)
        else:
            self._safe_after(200, self._set_initial_url)

    def _register_event_bus_subscriptions(self) -> None:
        """Registriert alle Event‑Bus‑Abonnements."""
        subs = [
            ("transcription", self.handle_transcription),
            ("translation", self.handle_translation),
            ("info", self.handle_info),
            ("error", self.handle_error),
            ("controller_state", self._on_controller_state),
            ("stream_info", self.update_stream_info),
            ("file_finished", self._on_file_finished),
            ("processing_finished", self._on_processing_finished),
            ("processing_state_changed", self._on_processing_state_changed),
            ("update_url", self._on_update_url),
            ("translation_language_changed", self._on_translation_language_changed),
            ("reset_gui", self._on_reset_gui),
            ("progress", self.update_progress),
            ("model_changed", self._on_model_changed),
            ("translation_quality_warning", self._on_translation_quality_warning),
            ("audio_processor_idle", lambda _: self._on_processing_finished()),
            ("music_detected", self._on_music_detected),
            ("silence_detected", self._on_silence_detected),
            ("speech_detected", self._on_speech_detected),
            # ── Neue Events für Button‑Sperre während Modell‑Ladung ──
            ("model_load_started",  lambda _: self._set_start_button_loading_state(True)),
            ("model_load_finished", lambda _: self._set_start_button_loading_state(False)),
        ]
        with self._subscriptions_lock:
            for event, callback in subs:
                self.event_bus.subscribe(event, callback)
                self._event_subscriptions.append((event, callback))
        log_debug("gui", f"Event handlers registered: {[e for e, _ in subs]}")

    def _init_managers(self) -> None:
        """Initialisiert die verschiedenen Manager (Stream, FFmpeg, Export, Memory)."""
        self.resource_manager = ResourceManager()
        self.stream_manager = StreamManager(
            enable_debug=(DEBUG_LEVEL >= 1),
            use_browser_cookies=self.settings.use_browser_cookies,
            proxy=self.advanced_settings.proxy_url,
            proxy_enabled=self.advanced_settings.proxy_enabled,
        )
        self.ffmpeg_manager = FFmpegManager(
            self.advanced_settings.config,
            self.stream_manager,
            self.advanced_settings,
            resource_manager=self.resource_manager,
        )
        self.export_manager = ExportManager()
        self.memory_manager = MemoryManager()
        if IS_LINUX:
            self.performance_optimizer = LinuxPerformanceOptimizer(gui_ref=self)

    def _init_engines(self) -> None:
        """
        Initialisiert die Transkriptions‑, Übersetzungs‑ und Audio‑Engines
        mit maximaler Robustheit und detaillierten Debug‑Informationen.
        """
        if DEBUG_LEVEL >= 2:
            log_debug("init", "Creating transcription engine...")

        engine_created = False
        if WHISPER_AVAILABLE:
            try:
                self.transcription_engine = TranscriptionEngine(
                    self.advanced_settings,
                    cache_manager=self.app_context.cache_manager,
                    event_bus=self.event_bus,
                )
                engine_created = True
                if DEBUG_LEVEL >= 2:
                    log_debug("init", "TranscriptionEngine successfully created.")
            except Exception as e:
                logger.exception(
                    "❌ TranscriptionEngine creation failed: %s\n"
                    "   This can happen if PyTorch or its dependencies "
                    "(e.g. Microsoft Visual C++ Redistributable) are missing "
                    "or corrupted. The application will continue in Demo mode.",
                    e,
                )
        else:
            logger.warning(
                "No Whisper backend available – will use DummyTranscriptionEngine."
            )

        if not engine_created:
            self.transcription_engine = DummyTranscriptionEngine(
                self.advanced_settings, cache_manager=self.app_context.cache_manager
            )
            if not self.demo_mode:
                self.demo_mode = True
                logger.info(
                    "🔄 Switched to Demo mode because transcription engine could not be loaded."
                )
        try:
            self.language_detector = LanguageDetector(self.transcription_engine)
            if DEBUG_LEVEL >= 2:
                log_debug("init", "LanguageDetector created.")
        except Exception as e:
            logger.exception("Failed to create LanguageDetector: %s", e)
            self.language_detector = None
        if DEBUG_LEVEL >= 2:
            log_debug("init", "Creating translation engine...")

        # ------------------------------------------------------------------
        # Optimierte, defensive Übersetzungs‑Engine‑Erstellung
        # ------------------------------------------------------------------
        # Statt eines harten 'AttributeError' wird geprüft, ob die Methode
        # existiert.  Falls nicht, wird sofort auf DummyTranslationEngine
        # zurückgegriffen, OHNE dass eine Exception im Log erscheint.
        try:
            if hasattr(self, '_create_translation_engine'):
                self.translation_engine = self._create_translation_engine()
            else:
                # Fehlende Methode – weiche auf Dummy aus und warne einmalig
                logger.warning(
                    "DragonWhispererGUI._create_translation_engine nicht gefunden – "
                    "verwende DummyTranslationEngine."
                )
                self.translation_engine = DummyTranslationEngine(
                    target_lang=self.current_language,
                    settings=self.advanced_settings,
                    cache_manager=self.app_context.cache_manager,
                )
        except Exception as e:
            logger.exception(
                "❌ Translation engine creation failed: %s\n"
                "   Using DummyTranslationEngine instead.",
                e,
            )
            self.translation_engine = DummyTranslationEngine(
                target_lang=self.current_language,
                settings=self.advanced_settings,
                cache_manager=self.app_context.cache_manager,
            )
        if DEBUG_LEVEL >= 2:
            log_debug("init", "Creating AudioProcessor...")

        # ── Verbesserung: Fallback‑Engine wird NICHT mehr sofort erstellt ──
        # Die Erstellung der Fallback‑Engine (z. B. OllamaTranslationEngine)
        # ist in den AudioProcessor verschoben und erfolgt nur bei Bedarf,
        # d. h. wenn die primäre Engine ausfällt und der AudioProcessor die
        # Methode `_lazy_create_fallback_engine()` aufruft.
        # Dadurch entfällt der unnötige Verbindungsaufbau während des Starts.
        fallback_translation_engine = None

        try:
            self.audio_processor = AudioProcessor(
                controller_ref=self.controller,
                ffmpeg_manager=self.ffmpeg_manager,
                settings=self.advanced_settings,
                stream_manager=self.stream_manager,
            )
            self.audio_processor.set_engines(
                transcription_engine=self.transcription_engine,
                translation_engine=self.translation_engine,
                fallback_translation_engine=fallback_translation_engine,
            )
            if DEBUG_LEVEL >= 2:
                log_debug("init", "AudioProcessor created and engines configured.")
        except Exception as e:
            logger.exception("Failed to create AudioProcessor: %s", e)
            raise

        if self.demo_mode:
            if hasattr(self, "model_combo") and self.model_combo.winfo_exists():
                self.model_combo.config(state="disabled")
                self.model_var.set("dummy (Demo)")
            self.update_status(
                "⚠️ Demo-Modus: Whisper nicht verfügbar – verwende Dummy-Transkriptionen"
            )
            if DEBUG_LEVEL >= 2:
                log_debug("init", "Demo mode GUI adjustments applied.")
        else:
            if hasattr(self, "model_combo") and self.model_combo.winfo_exists():
                self.model_combo.config(state="readonly")
                self.model_var.set(self.settings.default_model)

        if DEBUG_LEVEL >= 2:
            log_debug("init", "Engine initialization complete.")

    def _setup_callbacks(self) -> None:
        """Platzhalter für zusätzliche Callbacks (z.B. für Plugins)."""
        pass

    def _apply_precision_optimizations(self) -> None:
        """
        Wendet Optimierungen für hohe Präzision an, jedoch NUR, wenn der
        Precision‑Modus in den erweiterten Einstellungen explizit aktiviert ist.
        """
        if not getattr(self.advanced_settings, "precision_mode", False):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "Precision mode deaktiviert – keine Precision‑Optimierungen",
                )
            return

        # ── Zentralen Override‑Mechanismus verwenden ─────────────────
        #     Dieser setzt alle vom Precision‑Mode verlangten Werte
        #     atomar und sichert die Originaleinstellungen.
        self.advanced_settings._apply_mode_overrides()
        self.advanced_settings.vad_filter = False
        self.advanced_settings.duplicate_similarity_threshold = 0.98
        # ------------------------------------------------------------------

        logger.info(
            "Präzisionsoptimierungen angewendet "
            "(VAD deaktiviert, Chunk-Dauer 20s, Duplikat-Schwellwert 0.98, "
            "via _apply_mode_overrides)"
        )

    def _apply_theme(self, theme_name: str) -> None:
        """        Wendet das ausgewählte Theme auf die gesamte GUI an.        """
        theme_map = {
            "dark": DarkTheme,
            "light": LightTheme,
            "pastel": PastelTheme,
            "highcontrast": HighContrastTheme,
            "dracula": DraculaTheme,
            "nord": NordTheme,
            "solarized": SolarizedDarkTheme,
            "gruvbox": GruvboxDarkTheme,
            "onedark": OneDarkTheme,
            "monokai": MonokaiTheme,
            "a11y-dark": A11yDarkTheme,
            "catppuccin": CatppuccinMochaTheme,
            "tokyonight": TokyoNightTheme,
        }
        theme_class = theme_map.get(theme_name, DarkTheme)
        self.current_theme = theme_class()
        global CURRENT_THEME
        CURRENT_THEME = self.current_theme

        if DEBUG_LEVEL >= 2:
            log_debug("gui", f"Theme gewechselt zu: {theme_name}")

        try:
            if self.root and self.root.winfo_exists():
                self.root.configure(bg=self.current_theme.BG_PRIMARY)
        except tk.TclError as e:
            logger.warning(f"Fehler beim Setzen des root-Hintergrunds: {e}")

        self._update_ttk_styles()

        try:
            if self.root and self.root.winfo_exists():
                PlatformUtils.apply_theme_to_widget_tree(self.root, self.current_theme)
        except Exception as e:
            logger.warning(f"Fehler beim Aktualisieren des Widget-Baums: {e}")
            if DEBUG_LEVEL >= 3:
                log_debug("gui", f"Theme-Update-Fehler: {e}")

        if hasattr(self, "layout") and hasattr(self.layout, "apply_theme"):
            try:
                self.layout.apply_theme()
            except Exception as e:
                logger.warning(f"Fehler in layout.apply_theme(): {e}")

        self._update_special_widgets()

        logger.info(f"🎨 Theme erfolgreich gewechselt zu: {theme_name}")

    def _update_special_widgets(self) -> None:
        """
        Aktualisiert Widgets, die nicht im normalen Widget‑Baum erfasst werden
        oder eine spezielle Behandlung benötigen (z. B. Statusleiste).
        """
        special_widgets = []
        for name in self.SPECIAL_WIDGET_NAMES:
            widget = getattr(self, name, None)
            if widget is not None:
                try:
                    if widget.winfo_exists():
                        special_widgets.append((widget, name))
                except tk.TclError:
                    pass

        for widget, name in special_widgets:
            updates = self._get_special_updates(name)
            if updates:
                try:
                    widget.configure(**updates)
                except tk.TclError:
                    pass

    def _update_ttk_styles(self) -> None:
        """Aktualisiert die ttk‑Styles (Combobox, Progressbar) nach einem Theme‑Wechsel."""
        style = ttk.Style()
        style.theme_use("clam")
        style.configure(
            "Dark.TCombobox",
            fieldbackground=self.current_theme.COMBO_BG,
            background=self.current_theme.COMBO_BG,
            foreground=self.current_theme.COMBO_FG,
            selectbackground=self.current_theme.COMBO_SELECTION,
            selectforeground=self.current_theme.TEXT_PRIMARY,
            insertcolor=self.current_theme.TEXT_PRIMARY,
            borderwidth=1,
            relief="flat",
            arrowsize=12,
            padding=5,
        )
        style.map(
            "Dark.TCombobox",
            fieldbackground=[
                ("readonly", self.current_theme.COMBO_BG),
                ("active", self.current_theme.BG_HOVER),
            ],
            background=[
                ("readonly", self.current_theme.COMBO_BG),
                ("active", self.current_theme.BG_HOVER),
            ],
            foreground=[
                ("readonly", self.current_theme.COMBO_FG),
                ("active", self.current_theme.TEXT_PRIMARY),
            ],
        )
        style.configure(
            "Dark.Horizontal.TProgressbar",
            background=self.current_theme.SUCCESS,
            troughcolor=self.current_theme.BG_TERTIARY,
            bordercolor=self.current_theme.BORDER,
        )

    def _get_special_updates(self, widget_name: str) -> Dict[str, Any]:
        """Liefert dynamische Theme‑Updates für spezielle Widgets."""
        updates: Dict[str, Any] = {}
        if widget_name == "start_button":
            updates = {"bg": self.current_theme.SUCCESS}
        elif widget_name == "stop_button":
            updates = {"bg": self.current_theme.ERROR}
        elif widget_name == "translate_btn":
            updates = {
                "bg": self.current_theme.SUCCESS
                if self.translate_active
                else self.current_theme.BG_TERTIARY
            }
        elif widget_name == "subtitle_btn":
            updates = {
                "bg": self.current_theme.SUBTITLE_ACTIVE
                if self.subtitle_mode
                else self.current_theme.SUBTITLE_INACTIVE
            }
        elif widget_name == "status_label":
            updates = {
                "bg": self.current_theme.BG_PRIMARY,
                "fg": self.current_theme.TEXT_SECONDARY,
            }
        elif widget_name in ("system_info_label", "progress_label"):
            updates = {
                "bg": self.current_theme.BG_SECONDARY,
                "fg": self.current_theme.TEXT_SECONDARY,
            }
        elif widget_name in ("stream_info_frame", "status_bar_frame"):
            updates = {"bg": self.current_theme.BG_SECONDARY}
        elif widget_name == "stream_title_label":
            updates = {
                "bg": self.current_theme.BG_SECONDARY,
                "fg": self.current_theme.TEXT_ACCENT,
            }
        elif widget_name == "stream_details_label":
            updates = {
                "bg": self.current_theme.BG_SECONDARY,
                "fg": self.current_theme.TEXT_SECONDARY,
            }
        elif widget_name in ("tts_btn", "vad_fallback_btn", "live_mode_btn"):
            updates = {
                "bg": self.current_theme.BG_TERTIARY,
                "fg": self.current_theme.TEXT_PRIMARY,
            }
        return updates

    def is_shutting_down(self) -> bool:
        """Gibt zurück, ob ein Shutdown im Gange ist."""
        with self._shutdown_lock:
            return self._shutting_down

    def _safe_gui_update(self, callback: Callable, important: bool = False) -> None:
        """
        Führt ein GUI-Update threadsicher aus.

        Diese Methode stellt sicher, dass der übergebene Callback immer im
        Hauptthread der GUI ausgeführt wird, um die Thread-Sicherheit von Tkinter
        zu gewährleisten. Wichtige Updates (important=True) werden bevorzugt
        behandelt und können bei Verfügbarkeit direkt über after_idle in den
        Hauptthread eingereiht werden. Normale Updates werden über den
        QueueManager abgewickelt, der eine geordnete und überlaufgeschützte
        Verarbeitung ermöglicht.

        Args:
            callback: Die auszuführende Funktion (ohne Argumente).
            important: Flag, das die Priorität des Updates festlegt. Wenn True,
                       wird das Update bevorzugt behandelt, jedoch nur dann
                       direkt über after_idle ausgeführt, wenn der Aufruf bereits
                       im Hauptthread erfolgt. Andernfalls wird es ebenfalls an
                       den QueueManager übergeben, um Blockaden zu vermeiden.
        """
        # Prüfen, ob das Programm gerade herunterfährt – in diesem Fall
        # keine GUI-Updates mehr durchführen, um Ressourcenkonflikte zu vermeiden.
        if self.is_shutting_down():
            return

        # Hilfsfunktion für den direkten Aufruf im Hauptthread
        def _direct_call() -> None:
            try:
                callback()
            except Exception as e:
                logger.error(f"Fehler in direktem GUI-Update-Callback: {e}")

        # Wichtige Updates werden bevorzugt behandelt
        if important:
            # Prüfen, ob der aktuelle Thread der Hauptthread ist
            if threading.current_thread() is threading.main_thread():
                try:
                    # after_idle führt den Callback aus, sobald die GUI-Ereignisschleife
                    # wieder bereit ist. Dies ist die beste Methode für GUI-Updates
                    # aus dem Hauptthread selbst.
                    if hasattr(self, "root") and self.root.winfo_exists():
                        self.root.after_idle(_direct_call)
                    else:
                        logger.warning(
                            "Wichtiges GUI-Update (important=True) konnte nicht "
                            "ausgeführt werden – root-Fenster existiert nicht mehr."
                        )
                except tk.TclError as e:
                    logger.error(f"TclError beim Planen eines wichtigen GUI-Updates: {e}")
                return
            else:
                # Nicht im Hauptthread -> über QueueManager abwickeln
                if hasattr(self, "queue_manager") and self.queue_manager:
                    self.queue_manager.safe_put(
                        self.QUEUE_TYPE_GUI,
                        ("callback", callback, important)
                    )
                else:
                    logger.warning(
                        "Wichtiges GUI-Update (important=True) aus Nicht-Hauptthread "
                        "und kein QueueManager verfügbar – Update wird verworfen."
                    )
                return

        # Normale Updates: immer über den QueueManager
        if hasattr(self, "queue_manager") and self.queue_manager:
            self.queue_manager.safe_put(
                self.QUEUE_TYPE_GUI,
                ("callback", callback, important)
            )
        else:
            # Fallback, falls der QueueManager nicht verfügbar ist – direkter Aufruf,
            # aber nur im Hauptthread, um Tkinter-Abstürze zu vermeiden.
            if threading.current_thread() is threading.main_thread():
                self.root.after_idle(_direct_call)
            else:
                logger.warning(
                    "QueueManager nicht verfügbar und nicht im Hauptthread – "
                    "GUI-Update wird verworfen."
                )

    def _safe_widget_config(self, widget_name: str, **kwargs) -> None:
        """Konfiguriert ein Widget sicher, falls es existiert."""
        widget = getattr(self, widget_name, None)
        if widget is not None and widget.winfo_exists():
            try:
                widget.config(**kwargs)
            except tk.TclError:
                pass

    def _safe_after(
        self, delay: int, callback: Callable, *args, **kwargs
    ) -> Optional[str]:
        """Sicherer `after`‑Aufruf, der beim Shutdown abbricht."""
        if self.is_shutting_down():
            return None
        try:
            if not hasattr(self, "root") or not self.root.winfo_exists():
                return None
            return self.root.after(delay, callback, *args, **kwargs)
        except tk.TclError:
            return None

    def update_status(self, message: str) -> None:
        """
        Aktualisiert die Statusleiste der GUI mit der angegebenen Nachricht.

        Die Methode unterdrückt identische aufeinanderfolgende Meldungen,
        um störendes Flackern zu vermeiden.  Sollte eine Statusmeldung
        zweimal hintereinander mit unterschiedlichem Zwischenstatus
        erscheinen, wird sie ignoriert.  Dieses Verhalten ist beabsichtigt
        und hat in der Praxis keine negativen Auswirkungen.
        """
        if self.is_shutting_down():
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "update_status: Shutdown aktiv – ignoriert")
            return
        if not message or not message.strip():
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "update_status: Leere Nachricht – ignoriert")
            return
        short_msg = message.strip()[:100]
        with self._status_lock:
            if self._last_status_message == short_msg:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui", f"update_status: Duplikat '{short_msg}' – ignoriert"
                    )
                return
            self._last_status_message = short_msg

        def update() -> None:
            """Wird im Hauptthread ausgeführt."""
            try:
                if not hasattr(self, "status_label") or self.status_label is None:
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "update_status: status_label existiert nicht")
                    return
                if not self.status_label.winfo_exists():
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "update_status: status_label wurde zerstört")
                    return
                self.status_label.config(text=short_msg)
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"update_status: '{short_msg}'")
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"update_status TclError: {e}")
            except Exception as e:
                logger.error(
                    f"Unerwarteter Fehler in update_status: {e}", exc_info=True
                )

        if hasattr(self, "queue_manager") and self.queue_manager is not None:
            self.queue_manager.safe_put(
                self.QUEUE_TYPE_GUI,
                ("callback", update, True),
            )
        else:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "update_status: QueueManager nicht verfügbar, verwende after_idle",
                )
            try:
                if hasattr(self, "root") and self.root.winfo_exists():
                    self.root.after_idle(update)
            except tk.TclError:
                pass

    @gui_error_handler
    def handle_transcription(self, result: TranscriptionResult) -> None:
        """
        Verarbeitet ein eingehendes Transkriptionsergebnis und zeigt es
        **in einheitlicher Formatierung** im GUI‑Textfeld an.

        Die Methode ist vollständig thread‑sicher und kann auch von
        Hintergrund‑Workern aufgerufen werden – die eigentliche
        Widget‑Aktualisierung erfolgt über den zentralen
        ``QueueManager``.

        Verbesserungen gegenüber der Vorversion
        ---------------------------------------
        * Jeder Satz wird **immer** mit einem Zeilenumbruch (``\\n``)
          abgeschlossen, unabhängig vom Vorhandensein eines Satzendzeichens
          oder der Sprache.  Dadurch erscheinen alle Sätze sauber unter-
          einander, und das frühere Problem der scheinbaren Einrückung
          ist beseitigt.
        * Die bisherige Unterscheidung zwischen asiatischen und
          nicht‑asiatischen Sprachen für das Anhängen eines Leerzeichens
          entfällt – das Verhalten ist jetzt global einheitlich.
        * Jeder kritische Verarbeitungsschritt (Blacklist, Validierung,
          TTS‑Planung) ist in einen eigenen ``try/except``‑Block gehüllt,
          sodass eine Ausnahme in einem Schritt niemals den gesamten
          Ablauf unterbricht.
        * Erweiterte Debug‑Ausgaben zeigen exakt den gewählten Zeitstempel,
          das endgültige Format und die gewählte Sprache an.
        * Der Zugriff auf optionale Attribute (``transcription_engine``,
          ``advanced_settings``) erfolgt ausschließlich über ``getattr``
          mit sicheren Standardwerten.
        * Die Duplikaterkennung verwendet zusätzlich eine Längenprüfung,
          um sehr kurze, inhaltsgleiche Segmente zuverlässig zu erkennen.
        * **NEU**: Die Sprache aus `result.language` wird direkt verwendet
          (die Engine liefert bereits die korrekte Anzeigesprache, auch
          bei aktivem Sprach‑Fallback).
        """
        # ------------------------------------------------------------------
        # 0. Vorabprüfungen
        # ------------------------------------------------------------------
        if not result or not result.text:
            return

        raw_text = result.text.strip()
        if not raw_text:
            return

        # Sprache und Konfidenz möglichst sicher auslesen
        lang = getattr(result, "language", "unknown") or "unknown"
        confidence = getattr(result, "confidence", 0.0) or 0.0

        # ------------------------------------------------------------------
        # 1. Duplikaterkennung (exakter Text)
        # ------------------------------------------------------------------
        try:
            with self._duplicate_lock:
                if raw_text == self._last_transcription_text:
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "transcription_gui",
                            "handle_transcription: duplicate text ignored – '%s…'",
                            raw_text[:60],
                        )
                    return
        except Exception as e:
            # Sollte niemals passieren, aber wir sind vorsichtig
            logger.warning("handle_transcription: duplicate lock error: %s", e)

        # ------------------------------------------------------------------
        # 2. Blacklist‑Filter
        # ------------------------------------------------------------------
        try:
            filtered_text = self._filter_blacklist_text(raw_text, lang)
            if filtered_text is None:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcription_gui",
                        "handle_transcription: segment fully removed by blacklist '%s…'",
                        raw_text[:80],
                    )
                return
            if filtered_text != raw_text:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcription_gui",
                        "Blacklist applied: '%s' -> '%s'",
                        raw_text[:50],
                        filtered_text[:50],
                    )
                raw_text = filtered_text
        except Exception as e:
            logger.warning("handle_transcription: blacklist filter failed: %s", e)
            # Im Zweifel den Originaltext verwenden, aber weitermachen

        # ------------------------------------------------------------------
        # 3. Validierung (benötigt ggf. die Transkriptions‑Engine)
        # ------------------------------------------------------------------
        try:
            engine_available = (
                hasattr(self, "transcription_engine")
                and self.transcription_engine is not None
            )
            if engine_available:
                if not self.transcription_engine.is_valid_segment(raw_text, confidence):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "transcription_gui",
                            "Segment rejected by is_valid_segment: '%s…'",
                            raw_text[:50],
                        )
                    return
            else:
                # Fallback‑Validierung, wenn keine Engine vorhanden ist
                if len(raw_text) < 2:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "transcription_gui",
                            "Segment rejected by fallback validation: '%s'",
                            raw_text,
                        )
                    return
        except Exception as e:
            logger.warning("handle_transcription: validation error: %s", e)
            # Wenn die Validierung selbst einen Fehler wirft, brechen wir ab,
            # um keine ungültigen Daten anzuzeigen.
            return

        # ------------------------------------------------------------------
        # 4. Automatische Sprachausgabe (TTS) einplanen
        # ------------------------------------------------------------------
        auto_tts_enabled = False
        try:
            auto_tts_enabled = getattr(
                getattr(self, "advanced_settings", None),
                "auto_tts_transcript",
                False,
            )
        except Exception:
            pass

        if auto_tts_enabled and not self.is_shutting_down():
            try:
                self._schedule_tts(raw_text, "transcript")
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcription_gui",
                        "TTS scheduled for transcript: '%s…'",
                        raw_text[:50],
                    )
            except Exception as e:
                logger.warning("handle_transcription: TTS scheduling failed: %s", e)
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "transcription_gui",
                        "TTS scheduling exception",
                        e,
                        level="debug",
                    )

        # ------------------------------------------------------------------
        # 5. Statistik und Historie
        # ------------------------------------------------------------------
        try:
            self._last_transcription_time = time.time()
            if hasattr(self, "performance_monitor"):
                self.performance_monitor.log_transcription()
            with self._history_lock:
                self.transcript_history.append(result)
        except Exception as e:
            logger.warning("handle_transcription: history/statistics error: %s", e)

        # ------------------------------------------------------------------
        # 6. Einheitliche Formatierung
        #     - Subtitle‑Modus: Video‑Zeitstempel, wenn vorhanden,
        #       sonst aktuelle Uhrzeit.
        #     - Normaler Modus: immer aktuelle Uhrzeit.
        #     - Nach jedem Satz wird ein Zeilenumbruch (\\n) angehängt.
        # ------------------------------------------------------------------
        subtitle_mode = self.subtitle_mode  # threadsicher via Property
        try:
            if subtitle_mode:
                video_ts = getattr(result, "start", None)
                if video_ts is not None:
                    time_str = self._format_timestamp(video_ts)
                else:
                    time_str = datetime.now().strftime("%H:%M:%S")
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "transcription_gui",
                        "Subtitle mode: using video timestamp (start=%s)",
                        video_ts,
                    )
            else:
                time_str = datetime.now().strftime("%H:%M:%S")
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "transcription_gui",
                        "Normal mode: using absolute timestamp %s",
                        time_str,
                    )
        except Exception as e:
            logger.warning("handle_transcription: timestamp formatting error: %s", e)
            time_str = datetime.now().strftime("%H:%M:%S")

        # Sprachkürzel (verwende die korrekte Sprache aus result)
        lang_display = LANGUAGE_SHORT_CODES.get(lang, lang[:3].upper())

        # Immer einen Zeilenumbruch am Ende anhängen – so erscheint jeder
        # Satz in einer eigenen Zeile und es gibt keine falschen Einrückungen.
        formatted = f"[{time_str}] [{lang_display}] {raw_text}\n"

        # ------------------------------------------------------------------
        # 7. Duplikat‑Speicher aktualisieren
        # ------------------------------------------------------------------
        try:
            with self._duplicate_lock:
                self._last_transcription_text = raw_text
        except Exception as e:
            logger.warning("handle_transcription: duplicate storage error: %s", e)

        # ------------------------------------------------------------------
        # 8. Zentrale Ausgabe + Markierung (verhindert finalen Doppel‑Flush)
        # ------------------------------------------------------------------
        try:
            self._output_and_mark_transcription(formatted, raw_text)
        except Exception as e:
            logger.error("handle_transcription: output/mark error: %s", e)
            # Fallback: direkte Einfügung, falls QueueManager etc. versagen
            self._safe_transcription_insert(formatted)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "transcription_gui",
                "handle_transcription (%s): '%s…'",
                "subtitle" if subtitle_mode else "normal",
                formatted[:120] if len(formatted) > 120 else formatted,
            )

    def _mark_text_as_flushed(self, clean_text: str) -> None:
        """
        Fügt *clean_text* threadsicher in das ``_already_flushed_texts``‑Set
        ein und begrenzt das Set auf 50 000 Einträge, um Speicherlecks bei
        sehr langen Livestreams zu verhindern.

        Das Set muss bereits in ``__init__`` als ``set()`` initialisiert worden sein –
        es darf an **keiner** anderen Stelle neu zugewiesen werden.

        Diese Methode wird ausschließlich für Transkriptionstexte verwendet,
        um doppelte Ausgaben über den finalen Flush hinaus zu verhindern.
        Sie ist thread‑sicher durch die Verwendung des zentralen
        ``_duplicate_lock``.

        Args:
            clean_text: Der bereinigte, bereits ausgegebene Text.
        """
        # Defensiver Guard: Falls das Set noch nicht existiert (sollte nicht vorkommen)
        if not hasattr(self, "_already_flushed_texts"):
            with self._duplicate_lock:
                if not hasattr(self, "_already_flushed_texts"):
                    self._already_flushed_texts = set()
                    log_debug(
                        "gui",
                        "_mark_text_as_flushed: _already_flushed_texts lazy‑initialisiert",
                    )

        with self._duplicate_lock:
            self._already_flushed_texts.add(clean_text)

            # Speicherleck verhindern – nach 50 k Einträgen leeren.
            if len(self._already_flushed_texts) > 50_000:
                self._already_flushed_texts.clear()
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "gui",
                        "_already_flushed_texts cleared (size limit 50 000 reached).",
                    )

    def _check_and_mark_text_as_flushed(self, clean_text: str) -> bool:
        """
        Thread‑sicher prüfen, ob *clean_text* bereits im
        ``_already_flushed_texts``‑Set enthalten ist, und den Text
        andernfalls hinzufügen.

        Der Zugriff erfolgt **ausschließlich** unter dem zentralen
        ``_duplicate_lock``, sodass konkurrierende Threads (insbesondere
        aus dem AudioProcessor) den Zustand des Sets nicht korrumpieren
        können.

        Rückgabewert:
            ``True``  → Text war noch **nicht** im Set und wurde eingefügt.
            ``False`` → Text war bereits vorhanden (Duplikat).
        """
        with self._duplicate_lock:
            # Defensive Initialisierung (falls das Set noch nicht existiert)
            if not hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts: Set[str] = set()
            if clean_text in self._already_flushed_texts:
                return False
            self._already_flushed_texts.add(clean_text)
            # Speicherleck verhindern – nach 100 k Einträgen leeren
            if len(self._already_flushed_texts) > 100_000:
                self._already_flushed_texts.clear()
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "gui",
                        "Cleared _already_flushed_texts (size limit reached)",
                    )
            return True

    # ------------------------------------------------------------------
    # Zentrale Ausgabemethode – muss in derselben Klasse existieren
    # ------------------------------------------------------------------
    def _output_and_mark_transcription(self, formatted: str, clean_text: str) -> None:
        """
        Fügt den formatierten Transkriptionstext in das Widget ein und
        markiert den bereinigten Text im ``_already_flushed_texts``‑Set,
        um spätere Doppelausgaben durch den finalen Flush zu verhindern.

        Die Markierung erfolgt jetzt **threadsicher** über die dedizierte
        Methode :meth:`_mark_text_as_flushed`, die unter dem
        ``_duplicate_lock`` arbeitet und das Set bei Bedarf verkleinert.
        """
        self._mark_text_as_flushed(clean_text)
        self._safe_transcription_insert(formatted)
        if DEBUG_LEVEL >= 4:
            log_debug(
                "gui",
                "Marked and inserted: '%s…'",
                clean_text[:50],
            )

    def _flush_pending_transcript_segment(self) -> None:
        """
        Verarbeitet alle in ``_pending_transcript_segments`` verbliebenen
        Transkriptionsfragmente und gibt sie **in einheitlicher Formatierung**
        im Transkript‑Widget aus.

        - Im **Subtitle‑Modus** wird, wenn vorhanden, der originale
          Video‑Zeitstempel des Segments verwendet, sonst die aktuelle Uhrzeit.
        - Im **normalen Modus** wird **immer** die aktuelle Uhrzeit genutzt,
          um ein einheitliches Erscheinungsbild zu gewährleisten.

        Bereits über ``_output_and_mark_transcription`` ausgegebene Texte
        werden anhand des ``_already_flushed_texts``‑Sets erkannt und
        **nicht** doppelt eingefügt.

        Der Zugriff auf das Set erfolgt **ausschließlich threadsicher**
        über :meth:`_check_and_mark_text_as_flushed`.
        """
        # 1. Lazy-Initialisierung der benötigten Datenstrukturen
        if not hasattr(self, "_pending_transcript_segments"):
            self._pending_transcript_segments: List[Tuple[str, Optional[float], str]] = []
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_pending_transcript_segments lazy initialised")
        if not hasattr(self, "_pending_transcript_lock"):
            self._pending_transcript_lock = threading.Lock()
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_pending_transcript_lock lazy initialised")
        if not hasattr(self, "_already_flushed_texts"):
            self._already_flushed_texts: Set[str] = set()

        # 2. Unter Lock die Liste kopieren und sofort leeren
        with self._pending_transcript_lock:
            if not self._pending_transcript_segments:
                return
            snapshot = list(self._pending_transcript_segments)
            self._pending_transcript_segments.clear()

        # 3. Widget-Verfügbarkeit prüfen
        widget = getattr(self, "transcript_text", None)
        if widget is None or not widget.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "transcript_text widget not available – cannot flush")
            return

        scroll_var = getattr(self, "transcript_scroll_var", None)
        flushed = 0
        skipped_duplicate = 0

        for text, timestamp, lang in snapshot:
            clean = text.strip()
            if not clean:
                continue

            # Doppelte Ausgabe vermeiden – jetzt threadsicher
            if not self._check_and_mark_text_as_flushed(clean):
                skipped_duplicate += 1
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        f"  Segment already flushed, skipping: '{clean[:50]}...'",
                    )
                continue

            # Zeitstempel einheitlich wählen
            if self.subtitle_mode:
                if timestamp is not None:
                    time_str = self._format_timestamp(timestamp)
                else:
                    time_str = datetime.now().strftime("%H:%M:%S")
            else:
                time_str = datetime.now().strftime("%H:%M:%S")

            lang_disp = LANGUAGE_SHORT_CODES.get(lang, lang[:3].upper()) if lang else "??"
            formatted = f"[{time_str}] [{lang_disp}] {clean}\n"

            try:
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True

                widget.insert("end", formatted)

                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")

                flushed += 1
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        "Flushed pending: lang=%s, len=%d, timestamp=%s",
                        lang,
                        len(clean),
                        "video" if self.subtitle_mode and timestamp else "absolute",
                    )
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError in pending flush: {e}")
                break
            except Exception as e:
                logger.warning("Fehler beim Einfügen eines pending Segments: %s", e)
                break

        if DEBUG_LEVEL >= 2 and (flushed > 0 or skipped_duplicate > 0):
            log_debug(
                "gui",
                f"_flush_pending_transcript_segment: {flushed} inserted, "
                f"{skipped_duplicate} duplicates skipped, "
                f"total pending in snapshot={len(snapshot)}",
            )

    def _clear_pending_buffers(
        self,
        segments_list: Optional[List[Tuple[str, Optional[float], str]]],
        single_segment: Optional[Tuple[str, Optional[float], str]],
    ) -> None:
        """Hilfsmethode, um die beiden Puffer zu leeren."""
        if segments_list is not None:
            self._pending_transcript_segments.clear()
        self._pending_transcript_segment = None
        if DEBUG_LEVEL >= 4:
            log_debug("gui", "Pending transcript buffers cleared.")

    def _safe_transcription_insert(self, formatted: str) -> None:
        """        Fügt den formatierten Transkriptionstext in die GUI ein.
        Bevorzugt den QueueManager; falls dieser nicht verfügbar ist oder
        ein Fehler auftritt, wird der Text direkt per root.after in das
        Transkriptions‑Widget geschrieben.        """
        if self.is_shutting_down():
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_safe_transcription_insert: Shutdown aktiv – Fallback")
            self._fallback_transcription_insert(formatted)
            return

        if not hasattr(self, 'queue_manager') or self.queue_manager is None:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_safe_transcription_insert: Kein QueueManager – Fallback")
            self._fallback_transcription_insert(formatted)
            return

        try:
            success = self.queue_manager.safe_put(
                self.QUEUE_TYPE_TEXT, (self.UPDATE_TYPE_TRANSCRIPT, formatted)
            )
            if not success:
                logger.warning("QueueManager safe_put schlug fehl – verwende Fallback")
                self._fallback_transcription_insert(formatted)
        except Exception as e:
            logger.warning(
                "Fehler in QueueManager.safe_put: %s – verwende Fallback", e
            )
            self._fallback_transcription_insert(formatted)

    def _fallback_transcription_insert(self, formatted: str) -> None:
        """
        Fallback: Fügt den Transkriptionstext direkt per root.after in das
        Text‑Widget ein, ohne den QueueManager zu verwenden.
        """
        if not hasattr(self, 'root') or not self.root.winfo_exists():
            return

        def insert():
            try:
                widget = getattr(self, 'transcript_text', None)
                if widget is None or not widget.winfo_exists():
                    return
                scroll_var = getattr(self, 'transcript_scroll_var', None)
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True
                widget.insert("end", formatted)
                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError in Fallback-Insert: {e}")
            except Exception as e:
                logger.warning(f"Unerwarteter Fehler im Fallback-Insert: {e}")

        self.root.after(0, insert)

    def _is_new_sentence_context(self) -> bool:
        """        Gibt zurück, ob der zuletzt ausgegebene Text mit einem Satzendzeichen endete.
        Dies wird verwendet, um zu entscheiden, ob ein neuer Zeitstempel angezeigt werden soll.        """
        with self._duplicate_lock:
            last = self._last_transcription_text
            if not last:
                return True
            return last[-1] in ".!?。！？"

    def _apply_blacklist_filter(self, text: str, lang: str) -> bool:
        """        Wendet die konfigurierte Blacklist auf einen Text an.        """
        blacklist = getattr(self.advanced_settings, "blacklist", [])
        if not blacklist:
            return False
        if not text or not text.strip():
            return False
        mode = getattr(self.advanced_settings, "blacklist_mode", "word")
        asian_langs = {"zh", "ja", "ko", "th", "vi", "tl", "yue", "lo", "km", "my"}
        if lang in asian_langs:
            effective_mode = "substring"
        else:
            effective_mode = mode
        if not hasattr(self, "_blacklist_regex_cache"):
            self._blacklist_regex_cache = {}
            self._blacklist_last_modified = 0
        cache_key = (tuple(sorted(blacklist)), effective_mode)
        if cache_key in self._blacklist_regex_cache:
            regex = self._blacklist_regex_cache[cache_key]
        else:
            if effective_mode == "word":
                escaped_phrases = [re.escape(phrase) for phrase in blacklist if phrase]
                if not escaped_phrases:
                    return False
                pattern = r"\b(" + "|".join(escaped_phrases) + r")\b"
            else:
                escaped_phrases = [re.escape(phrase) for phrase in blacklist if phrase]
                if not escaped_phrases:
                    return False
                pattern = "(" + "|".join(escaped_phrases) + ")"
            try:
                regex = re.compile(pattern, re.IGNORECASE)
            except re.error as e:
                logger.warning(f"Ungültiges Blacklist-Pattern: {e}")
                return False
            self._blacklist_regex_cache[cache_key] = regex
            if len(self._blacklist_regex_cache) > 10:
                oldest = next(iter(self._blacklist_regex_cache))
                del self._blacklist_regex_cache[oldest]
        try:
            match = regex.search(text)
            if match:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "blacklist",
                        f"Filtered '{text[:100]}' (lang={lang}, mode={effective_mode}) – matched: '{match.group(0)}'"
                    )
                return True
        except Exception as e:
            logger.warning(f"Blacklist regex search error: {e}")
            return False
        return False

    def _filter_blacklist_text(self, text: str, lang: str) -> Optional[str]:
        """
        Entfernt alle konfigurierten Blacklist‑Phrasen aus *text* und gibt den
        bereinigten Text zurück.  Ist das Ergebnis leer oder besteht es nur aus
        Whitespace, wird ``None`` zurückgegeben.
        """
        blacklist = getattr(self.advanced_settings, "blacklist", [])
        if not blacklist or not text:
            return text
        mode = getattr(self.advanced_settings, "blacklist_mode", "word")
        asian_langs = {"zh", "ja", "ko", "th", "vi", "tl", "yue", "lo", "km", "my"}
        effective_mode = mode if lang not in asian_langs else "substring"
        if not hasattr(self, "_blacklist_regex_cache"):
            self._blacklist_regex_cache = {}
        if not hasattr(self, "_blacklist_cache_lock"):
            self._blacklist_cache_lock = threading.RLock()
        cache_key = (tuple(sorted(blacklist)), effective_mode)
        with self._blacklist_cache_lock:
            regex = self._blacklist_regex_cache.get(cache_key)
            if regex is None:
                if effective_mode == "word":
                    pattern = (
                        r"\b("
                        + "|".join(re.escape(p) for p in blacklist if p)
                        + r")\b"
                    )
                else:
                    pattern = (
                        "("
                        + "|".join(re.escape(p) for p in blacklist if p)
                        + ")"
                    )
                try:
                    regex = re.compile(pattern, re.IGNORECASE)
                except re.error as e:
                    logger.warning(
                        "Ungültiges Blacklist‑Pattern: %s. "
                        "Blacklist wird für diese Anfrage ignoriert.", e
                    )
                    return text
                self._blacklist_regex_cache[cache_key] = regex
                if len(self._blacklist_regex_cache) > 10:
                    oldest_key = next(iter(self._blacklist_regex_cache))
                    del self._blacklist_regex_cache[oldest_key]
        cleaned = regex.sub("", text)
        cleaned = re.sub(r"\s+", " ", cleaned)
        cleaned = re.sub(r"\s([.,!?;:])", r"\1", cleaned)
        cleaned = cleaned.strip()
        if not cleaned:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "blacklist",
                    f"Text komplett durch Blacklist entfernt: '{text[:100]}'",
                )
            return None
        if DEBUG_LEVEL >= 4:
            log_debug(
                "blacklist",
                f"Blacklist-Filter: '{text[:80]}' → '{cleaned[:80]}'",
            )
        return cleaned

    def _format_timestamp(self, start: Optional[float]) -> str:
        """Formatiert einen Zeitstempel für die Anzeige."""
        if (
            start is not None
            and hasattr(self, "export_manager")
            and self.export_manager
        ):
            return self.export_manager._format_timestamp_srt(start)
        return datetime.now().strftime("%H:%M:%S")

    @gui_error_handler
    def handle_translation(self, result: TranslationResult) -> None:
        """
        Verarbeitet ein Übersetzungsergebnis und fügt es formatiert in die
        GUI ein.  Jede Übersetzung wird **immer** mit einem Zeilenumbruch
        abgeschlossen, sodass aufeinanderfolgende Einträge in separaten
        Zeilen erscheinen.

        Verbesserungen:
        - Detaillierte Debug‑Logs für jeden Schritt.
        - Robuste Fehlerbehandlung mit Fallback bei fehlgeschlagenem QueueManager.
        - Korrekte Behandlung von `result.start` für Zeitstempel im Subtitle‑Modus.
        - Duplikaterkennung mit Lock.
        - Automatische Größenbegrenzung des Duplikat‑Sets.
        """
        # ── 0. Vorabprüfungen – None, leere Texte früh abfangen ──────
        if result is None:
            if DEBUG_LEVEL >= 4:
                log_debug("translate_gui", "handle_translation: result is None")
            return
        if not result.translated:
            if DEBUG_LEVEL >= 4:
                log_debug("translate_gui", "handle_translation: result.translated is empty")
            return

        current_text = result.translated.strip()
        if not current_text:
            if DEBUG_LEVEL >= 4:
                log_debug("translate_gui", "handle_translation: text empty after stripping")
            return

        # Zielsprache für Blacklist und Anzeige ermitteln (Fallback 'de')
        target_lang = getattr(result, "target_lang", "de")

        # Startzeitstempel für Debug‑Log
        start_ts = getattr(result, "start", None)
        start_float = start_ts if start_ts is not None else -1.0

        # Debug‑Log für Eintritt (hilft bei der Fehlersuche)
        if DEBUG_LEVEL >= 3:
            log_debug(
                "translate_gui",
                "handle_translation ENTER: text='%.50s...', len=%d, start=%.2f",
                current_text, len(current_text), start_float,
            )

        # ── 1. Duplikaterkennung – exakte Wiederholungen sofort verwerfen ──
        try:
            with self._duplicate_lock:
                if current_text == self._last_translation_text:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "translate_gui",
                            "Duplicate text ignored: '%.50s...'",
                            current_text[:50],
                        )
                    return
        except Exception as e:
            logger.warning("handle_translation: duplicate check failed: %s", e)
            if DEBUG_LEVEL >= 3:
                log_debug("translate_gui", "Duplicate lock problem, continuing anyway")

        # ── 2. Blacklist‑Filter – unerwünschte Phrasen entfernen ────────
        try:
            if self._apply_blacklist_filter(current_text, target_lang):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "translate_gui",
                        "Blocked by blacklist (lang=%s, text='%.50s...')",
                        target_lang, current_text[:50],
                    )
                return
        except Exception as e:
            logger.warning("handle_translation: blacklist filter failed: %s", e)
            if DEBUG_LEVEL >= 3:
                log_debug("translate_gui", "Blacklist error, treating as not blocked")

        # ── 3. Automatische Sprachausgabe (TTS) einplanen ────────────────
        auto_tts_enabled = False
        try:
            ap = getattr(self, "audio_processor", None)
            if ap is not None and hasattr(ap, "settings") and ap.settings is not None:
                auto_tts_enabled = bool(getattr(ap.settings, "auto_tts_translation", False))
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "translate_gui",
                        "auto_tts_translation from AudioProcessor: %s",
                        auto_tts_enabled,
                    )
            else:
                auto_tts_enabled = bool(getattr(self.advanced_settings, "auto_tts_translation", False))
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "translate_gui",
                        "auto_tts_translation from advanced_settings: %s",
                        auto_tts_enabled,
                    )
        except Exception as e:
            logger.warning("handle_translation: Fehler beim Ermitteln der Auto‑TTS‑Einstellung: %s", e)
            auto_tts_enabled = False

        if auto_tts_enabled and not self.is_shutting_down():
            if hasattr(self, "tts_manager") and self.tts_manager is not None:
                try:
                    self._schedule_tts(current_text, "translation")
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "translate_gui",
                            "TTS scheduled for translation: '%.50s...'",
                            current_text[:50],
                        )
                except Exception as e:
                    logger.warning("handle_translation: TTS scheduling failed: %s", e)
                    if DEBUG_LEVEL >= 3:
                        log_exception(
                            "translate_gui",
                            "TTS scheduling exception",
                            e,
                            level="debug",
                        )
            else:
                if DEBUG_LEVEL >= 4:
                    log_debug("translate_gui", "TTS manager not available – skip TTS")
        else:
            if DEBUG_LEVEL >= 4:
                if not auto_tts_enabled:
                    log_debug("translate_gui", "auto-TTS translation disabled – skip")
                elif self.is_shutting_down():
                    log_debug("translate_gui", "shutdown active – skip TTS")

        # ── 4. Statistik und Historie ─────────────────────────────────────
        try:
            self.performance_monitor.log_translation()
        except Exception as e:
            logger.warning("handle_translation: performance logger failed: %s", e)

        try:
            with self._history_lock:
                self.translation_history.append(result)
        except Exception as e:
            logger.warning("handle_translation: history save failed: %s", e)

        # ── 5. Video‑Zeitstempel ermitteln (falls vorhanden, sonst None) ──
        video_timestamp = getattr(result, "start", None)

        # ── 6. Formatierung: IMMER mit Zeilenumbruch abschließen ───────
        try:
            if self.subtitle_mode:
                timestamp = (
                    self._format_timestamp(video_timestamp)
                    if video_timestamp is not None
                    else ""
                )
                lang_code = LANGUAGE_SHORT_CODES.get(target_lang, target_lang[:3].upper())
                formatted = f"[{timestamp}] [{lang_code}] {current_text}\n"
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "translate_gui",
                        "Subtitle mode: timestamp='%s', lang=%s",
                        timestamp, lang_code,
                    )
            else:
                now = datetime.now().strftime("%H:%M:%S")
                lang_code = LANGUAGE_SHORT_CODES.get(target_lang, target_lang[:3].upper())
                formatted = f"[{now}] [{lang_code}] {current_text}\n"
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "translate_gui",
                        "Normal mode: timestamp='%s', lang=%s",
                        now, lang_code,
                    )
        except Exception as e:
            logger.error("handle_translation: formatting failed: %s", e)
            # Fallback: reiner Text mit Zeilenumbruch
            formatted = current_text + "\n"

        # ── 7. Duplikat‑Speicher aktualisieren ────────────────────────────
        try:
            with self._duplicate_lock:
                self._last_translation_text = current_text
        except Exception as e:
            logger.warning("handle_translation: duplicate storage failed: %s", e)

        # ── 8. Text in das GUI‑Widget einfügen (mehrstufiger Fallback) ────
        self._insert_translation_text(formatted, important=True)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "translate_gui",
                "handle_translation EXIT (%s): '%.80s...'",
                "subtitle" if self.subtitle_mode else "normal",
                formatted[:120] if len(formatted) > 120 else formatted,
            )

    def _insert_translation_text(
        self,
        formatted: str,
        force_direct: bool = False,
        important: bool = False,
    ) -> None:
        """
        Fügt den formatierten Übersetzungstext in die GUI ein.
        Bevorzugt den QueueManager; falls dieser nicht verfügbar ist oder
        ein Fehler auftritt, wird der Text direkt per root.after in das
        Übersetzungs‑Widget geschrieben.
        Der Parameter `important` steuert, ob das Update priorisiert wird
        und nicht dem Rate‑Limiter zum Opfer fällt.

        Args:
            formatted: Der formatierte Text (inkl. Zeitstempel und Zeilenumbruch).
            force_direct: Wenn True, wird der QueueManager umgangen.
            important: Wenn True, wird das Update als wichtig markiert
                       (nur relevant bei Nutzung des QueueManager).
        """
        if not formatted or not formatted.strip():
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "_insert_translation_text: leerer Text – ignoriert")
            return

        # Debug‑Log für den Aufruf
        if DEBUG_LEVEL >= 3:
            log_debug(
                "gui",
                "_insert_translation_text: text_len=%d, force_direct=%s, important=%s, queue_manager_available=%s",
                len(formatted),
                force_direct,
                important,
                hasattr(self, "queue_manager") and self.queue_manager is not None,
            )

        # ── 1. Direkter Einfügeversuch, wenn gewünscht oder QueueManager nicht verfügbar ──
        qm_available = (
            hasattr(self, "queue_manager")
            and self.queue_manager is not None
            and not force_direct
            and not self.is_shutting_down()
        )

        if qm_available:
            try:
                success = self.queue_manager.safe_put(
                    self.QUEUE_TYPE_TEXT,
                    (self.UPDATE_TYPE_TRANSLATION, formatted),
                    important=important,
                )
                if success:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "gui",
                            "safe_put via QueueManager: success=True, queue_size=%d",
                            self.queue_manager.text_queue.qsize()
                            if hasattr(self.queue_manager, "text_queue")
                            else -1,
                        )
                    return
                else:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "gui",
                            "safe_put via QueueManager: success=False – falling back to direct insert",
                        )
            except Exception as e:
                logger.warning(
                    "Fehler in QueueManager.safe_put für Übersetzung: %s – verwende Fallback",
                    e,
                )
                if DEBUG_LEVEL >= 3:
                    log_exception("gui", "QueueManager safe_put failed", e, level="debug")

        # ── 2. Fallback: Direktes Einfügen im Hauptthread ──────────────
        if not hasattr(self, "root") or not self.root.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "root window not available – cannot insert translation")
            return

        def direct_insert() -> None:
            """Hilfsfunktion, die im Hauptthread ausgeführt wird."""
            try:
                widget = getattr(self, "translation_text", None)
                if widget is None:
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "translation_text widget not found")
                    return
                if not widget.winfo_exists():
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "translation_text widget destroyed")
                    return

                # Scroll-Verhalten beibehalten
                scroll_var = getattr(self, "translation_scroll_var", None)
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True

                widget.insert("end", formatted)

                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")

                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        "Direct translation insert succeeded, text_len=%d",
                        len(formatted),
                    )
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"Direct insert TclError: {e}")
            except Exception as e:
                logger.error("Direct insert unexpected error: %s", e)

        # Mit `after_idle` in die Event‑Schleife einreihen, um die GUI nicht zu blockieren
        try:
            self.root.after_idle(direct_insert)
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "Direct insert scheduled via after_idle")
        except tk.TclError as e:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", f"after_idle scheduling failed: {e}")
            # Letzter Notfall: sofort ausführen (kann GUI kurz blockieren)
            direct_insert()

    def _adaptive_window_size(self) -> None:
        """Passt die Fenstergröße an die Bildschirmauflösung an (mind. 800×600)."""
        try:
            screen_w = self.root.winfo_screenwidth()
            screen_h = self.root.winfo_screenheight()
            usable_w = int(screen_w * 0.85)
            usable_h = int(screen_h * 0.80)
            width = min(950, usable_w)
            height = min(700, usable_h)
            self.root.geometry(f"{width}x{height}")
            self.root.minsize(800, 600)
        except Exception as e:
            logger.warning(f"Could not adapt window size: {e}")

    @gui_error_handler
    def handle_info(self, info_msg: str) -> None:
        self._safe_gui_update(
            lambda: self.update_status(f"ℹ️ {info_msg}"), important=True
        )

    @gui_error_handler
    def handle_error(self, error_msg: str) -> None:
        if self.controller.state in (
            WhisperController.State.STOPPING,
            WhisperController.State.IDLE,
        ):
            return
        self._safe_gui_update(lambda: self._handle_error_gui(error_msg), important=True)

    @gui_error_handler
    def _handle_error_gui(self, error_msg: str) -> None:
        """Display an error message and safely request the controller to stop.

        The method is defensive against the rare case where ``self.controller``
        has not yet been set or has already been disposed.  A missing or
        ``None`` controller is silently tolerated; no secondary exception is
        raised.
        """
        self.update_status(f"❌ {error_msg}")

        if hasattr(self, "controller") and self.controller is not None:
            try:
                self.controller.stop_processing()
            except Exception:
                # Any exception from the controller (e.g., already stopped,
                # shutdown in progress) must not break the error handler.
                pass

    @gui_error_handler
    def _on_controller_state(self, state_name: str) -> None:
        def update():
            if state_name == "PROCESSING":
                self._safe_widget_config("start_button", state="disabled")
                self._safe_widget_config("stop_button", state="normal")
            elif state_name in ("IDLE", "ERROR"):
                self._safe_widget_config("start_button", state="normal")
                self._safe_widget_config("stop_button", state="disabled")

        self._safe_gui_update(update, important=True)

    @gui_error_handler
    def _on_model_changed(self, data: dict) -> None:
        """        Wird aufgerufen, wenn die TranscriptionEngine das aktive Modell wechselt.
        Aktualisiert die GUI-ComboBox, die Statusleiste und den VRAM-Button.        """
        actual = data.get("actual")
        requested = data.get("requested")
        fallback = data.get("fallback_occurred", False)
        if not actual:
            return

        def update_gui():
            if hasattr(self, "model_var") and self.model_var.get() != actual:
                self.model_var.set(actual)
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"Modell-ComboBox aktualisiert auf {actual}")
            if hasattr(self, "vram_unload_btn") and self.vram_unload_btn.winfo_exists():
                self.vram_unload_btn.config(state="normal")
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "VRAM-Button aktiviert")
            if fallback and requested != actual:
                self.update_status(f"⚠️ {requested} nicht verfügbar – verwende {actual}")
                logger.warning(f"Modell-Fallback in GUI: {requested} → {actual}")
            else:
                # Erfolgreich geladen ohne Fallback – Benutzer an Start erinnern
                self.update_status("✅ Modell bereit – START drücken zum Transkribieren")
            self._start_system_monitoring()
        self._safe_gui_update(update_gui, important=True)

    @gui_error_handler
    def _on_processing_state_changed(self, is_processing: bool) -> None:
        self.is_processing = is_processing

        def update():
            self._safe_widget_config(
                "start_button", state="disabled" if is_processing else "normal"
            )
            self._safe_widget_config(
                "stop_button", state="normal" if is_processing else "disabled"
            )
            if not is_processing:
                self.update_status("✅ READY")
        self._safe_gui_update(update, important=True)

    @gui_error_handler
    def _on_file_finished(self, _=None) -> None:
        """Callback for the normal end of a file (e.g., YouTube VOD).

        Guarantees that the progress bar is reset **even if** an exception
        occurs while flushing pending transcript segments.  This prevents the
        GUI from showing a stale progress state after a file has already
        finished processing.
        """
        logger.info("📁 File processing finished normally")

        # 1. Safety checks – GUI must be alive
        if not hasattr(self, "root") or not self.root.winfo_exists():
            logger.warning(
                "⚠️ GUI nicht verfügbar – File-Finished-Callback abgebrochen"
            )
            return

        # 2. Ensure we are in the main thread
        if threading.current_thread() is not threading.main_thread():
            logger.error(
                "_on_file_finished außerhalb des GUI‑Threads aufgerufen – ignoriert"
            )
            return

        # 3. Flush remaining transcript segments and reset progress
        #    The ``try / finally`` guarantees that _reset_progress() is called
        #    even when the flush fails (e.g. because the transcript widget was
        #    destroyed during shutdown).
        try:
            self._flush_pending_transcript_segment()

            # Clear the duplicate protection set so that the next stream starts
            # with a clean slate.
            if hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts.clear()
                if DEBUG_LEVEL >= 4:
                    log_debug("gui", "_already_flushed_texts cleared after file finished")
        finally:
            self._reset_progress()
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_on_file_finished: progress bar reset in finally block")

        # 4. Do not trigger auto‑save during shutdown
        if getattr(self, "_shutting_down", False):
            logger.info("GUI im Shutdown – Auto-Save wird nicht ausgeführt")
            return

        # 5. Auto‑save if enabled and transcript history is available
        if self.settings.auto_save_on_completion:
            if not (hasattr(self, "transcript_history") and self.transcript_history):
                logger.info(
                    "Auto-Save übersprungen – keine Transkriptionen vorhanden"
                )
                self.update_status("✅ Dateiende – keine Transkription zum Speichern")
                return

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_on_file_finished: scheduling auto-save via after_idle",
                )

            def do_auto_save() -> None:
                """Perform the actual auto-save in the main thread."""
                try:
                    if hasattr(self, "save_transcript"):
                        self.save_transcript()
                        if DEBUG_LEVEL >= 3:
                            log_debug("gui", "Auto-save triggered successfully")
                    else:
                        logger.warning(
                            "save_transcript nicht verfügbar – Auto-Save fehlgeschlagen"
                        )
                except Exception as e:
                    logger.error(f"❌ Auto-save failed: {e}", exc_info=True)
                    self.update_status("❌ Auto-Save fehlgeschlagen")

            self.root.after_idle(do_auto_save)
        else:
            self.update_status("✅ Dateiende – zum Speichern 💾 klicken (Strg+S)")
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_on_file_finished: manual save reminder displayed",
                )

        if DEBUG_LEVEL >= 4:
            total_chunks = 0
            if hasattr(self, "audio_processor") and self.audio_processor is not None:
                total_chunks = getattr(self.audio_processor, "_chunk_counter", 0)
            log_debug(
                "gui",
                f"_on_file_finished: total chunks processed = {total_chunks}",
            )

    @gui_error_handler
    def _on_processing_finished(self, _=None) -> None:
        """
        Callback für das Ende der Audioverarbeitung (normal, Fehler oder Abbruch).
        """
        logger.info("Processing finished – GUI entering idle state")
        self._reset_progress()

        if (
            IS_LINUX
            and hasattr(self, "performance_optimizer")
            and self.performance_optimizer is not None
        ):
            try:
                if (
                    self.performance_optimizer.is_processing
                    or self.performance_optimizer._optimization_active
                ):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "gui",
                            "_on_processing_finished: deactivating Linux optimizer",
                        )
                    self.performance_optimizer.restore_normal_mode()
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "Linux optimizer deactivated successfully")
                else:
                    if DEBUG_LEVEL >= 4:
                        log_debug("gui", "Linux optimizer already inactive – skipping")
            except Exception as e:
                logger.warning(f"Failed to deactivate Linux optimizer: {e}")
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "gui", "Linux optimizer deactivation failed", e, level="debug"
                    )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "gui", "_on_processing_finished: progress bar reset, GUI now idle"
            )

