    @gui_operation_decorator
    def update_progress(self, data: dict) -> None:
        processed = data.get("processed", 0)
        total = data.get("total", None)
        chunks = data.get("chunks", 0)
        self._safe_gui_update(
            lambda: self._update_progress_gui(processed, total, chunks)
        )

    def _update_progress_gui(
        self, processed: int, total: Optional[int], chunks: int
    ) -> None:
        if not hasattr(self, "progress_bar") or not self.progress_bar.winfo_exists():
            return
        if total is not None and total > 0:
            percent = (processed / total) * 100
            self.progress_bar.config(mode="determinate", value=percent)
            mb = processed // (1024 * 1024)
            tb = total // (1024 * 1024)
            remaining_text = self._get_remaining_time_text()
            self.progress_label.config(text=f"{mb}MB/{tb}MB{remaining_text}")
        elif chunks > 0:
            self.progress_bar.config(mode="indeterminate")
            self.progress_bar.start(10)
            self.progress_label.config(
                text=f"Chunks: {chunks}  |  Daten: {processed // 1024} KB"
            )
        else:
            self.progress_bar.stop()
            self.progress_label.config(text="")

    def _get_remaining_time_text(self) -> str:
        try:
            if hasattr(self, "audio_processor") and self.audio_processor:
                expected = self.audio_processor._expected_duration
                if expected is not None:
                    processed_secs = self.audio_processor.get_processed_seconds()
                    remaining = max(0, expected - processed_secs)
                    return f" | ⏳ {int(remaining // 60):02d}:{int(remaining % 60):02d} verbleibend"
        except Exception:
            pass
        return ""

    @gui_operation_decorator
    def update_stream_info(self, info: Optional[StreamInfo]) -> None:
        """
        Aktualisiert die Stream‑Info‑Anzeige in der GUI.
        """
        if info is not None:
            self.last_completed_stream_info = info
            self.last_stream_title = info.title
            self.current_stream_info = info
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    f"update_stream_info: persisted stream info - title='{info.title[:50]}...'",
                )
        else:
            self.current_stream_info = None
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui", "update_stream_info: stream ended, persistent info retained"
                )

        def update_gui() -> None:
            """Aktualisiert die Widgets im Hauptthread."""
            try:
                if info is None:
                    if (
                        hasattr(self, "stream_title_label")
                        and self.stream_title_label is not None
                    ):
                        if self.stream_title_label.winfo_exists():
                            self.stream_title_label.config(
                                text="📡 Kein aktiver Stream"
                            )
                    if (
                        hasattr(self, "stream_details_label")
                        and self.stream_details_label is not None
                    ):
                        if self.stream_details_label.winfo_exists():
                            self.stream_details_label.config(
                                text="Bereit für neue Verbindung"
                            )
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "Stream info GUI reset to 'No active stream'")
                    return

                title = info.title
                if len(title) > 80:
                    title = title[:77] + "..."
                if (
                    hasattr(self, "stream_title_label")
                    and self.stream_title_label is not None
                ):
                    if self.stream_title_label.winfo_exists():
                        self.stream_title_label.config(text=f"📡 {title}")

                details_parts = [f"👤 {info.uploader}"]
                if info.duration and info.duration != "Live":
                    details_parts.append(f"⏱️ {info.duration}")
                if info.platform and info.platform != "unknown":
                    details_parts.append(f"🎬 {info.platform}")
                details_text = " | ".join(details_parts)

                if (
                    hasattr(self, "stream_details_label")
                    and self.stream_details_label is not None
                ):
                    if self.stream_details_label.winfo_exists():
                        self.stream_details_label.config(text=details_text)

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui",
                        f"Stream info GUI updated: title='{title}', details='{details_text}'",
                    )

            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError in update_stream_info GUI: {e}")
            except Exception as e:
                logger.warning(f"⚠️ Fehler in update_stream_info GUI: {e}")
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "gui", "update_stream_info GUI exception", e, level="warning"
                    )

        self._safe_gui_update(update_gui, important=True)

    @gui_operation_decorator
    def select_file_dark(self) -> None:
        filename = filedialog.askopenfilename(
            title="🎬 Select Audio/Video File - Dragon Whisperer",
            filetypes=[
                ("Media files", "*.mp3 *.wav *.m4a *.mp4 *.avi *.mkv *.mov *.flac"),
                ("All files", "*.*"),
            ],
        )
        if not filename:
            return
        file_url = f"file://{filename}"
        self.url_entry.delete(0, "end")
        self.url_entry.insert(0, file_url)
        self.update_status(f"📁 File selected: {os.path.basename(filename)}")
        self._start_async_language_detection(filename)
        info = self.stream_info_extractor.extract_stream_info(file_url)
        self.update_stream_info(info)

    def _start_async_language_detection(self, file_path: str) -> None:
        def worker():
            try:
                self.analyze_video_language(file_path)
            except Exception as e:
                logger.debug(f"Fehler in async_language_detection: {e}")

        threading.Thread(
            target=worker, daemon=True, name="AsyncLanguageDetection"
        ).start()

    @gui_operation_decorator
    def paste_url(self) -> None:
        try:
            clipboard = self.root.clipboard_get().strip()
            if not clipboard:
                self.update_status("❌ Zwischenablage ist leer")
                return
            cleaned = self.clean_and_validate_url(clipboard)
            self.url_entry.delete(0, "end")
            self.url_entry.insert(0, cleaned)
            self.update_status("📋 URL eingefügt")
            if cleaned.startswith("file://"):
                self._start_async_language_detection(cleaned[7:])
        except ValueError as e:
            self.update_status(f"❌ Ungültige URL: {e}")
        except tk.TclError:
            self.update_status("❌ Konnte nicht auf Zwischenablage zugreifen")

    def clean_and_validate_url(self, url: str) -> str:
        if not url:
            raise ValueError("URL cannot be empty")
        url = url.strip()
        if not url:
            raise ValueError("URL is empty after stripping")
        if url.startswith("file://"):
            return url
        if " " in url:
            raise ValueError("URL cannot contain spaces")
        if not url.startswith(("http://", "https://")):
            url = "https://" + url
        if len(url) < 10:
            raise ValueError("URL too short")
        parsed = urllib.parse.urlparse(url)
        if not parsed.netloc:
            raise ValueError("Invalid URL format")
        return url

    def analyze_video_language(self, file_path: str) -> None:
        if hasattr(self, "language_info_label"):
            self._safe_gui_update(
                lambda: self.language_info_label.config(text="🔍 Analyzing...")
            )

        def worker():
            try:
                result = self.language_detector.detect_video_language(file_path)
                self._safe_gui_update(lambda: self._update_language_label(result))
            except Exception as e:
                logger.exception(f"Language detection exception: {e}")
                self._safe_gui_update(
                    lambda: self.language_info_label.config(text="❌ Analysis failed")
                )

        threading.Thread(target=worker, daemon=True).start()

    def _update_language_label(self, result: Dict[str, Any]) -> None:
        if "error" in result:
            self.language_info_label.config(text=f"❌ {result['error']}")
        elif "info" in result:
            self.language_info_label.config(text=f"ℹ️ {result['info']}")
        else:
            self.current_video_language = result["detected_language"]
            icon = {"zh": "㊗️", "ja": "🗾", "ko": "₩", "th": "🇹🇭", "vi": "🇻🇳"}.get(
                self.current_video_language, "✅"
            )
            self.language_info_label.config(
                text=f"{icon} {result['language_name']} ({result['confidence']:.0%})"
            )

    def force_unload_model(self) -> None:
        if not hasattr(self, "transcription_engine") or not self.transcription_engine:
            self.update_status("ℹ️ Keine Transkriptions-Engine verfügbar")
            return
        if self.transcription_engine.model is None:
            self.update_status("ℹ️ Kein Modell geladen")
            return
        if self.is_processing:
            self.update_status(
                "⚠️ Modell kann während der Transkription nicht entladen werden"
            )
            return
        logger.info("🧠 Manuelles Entladen des Whisper-Modells aus dem VRAM")
        self.transcription_engine._force_model_cleanup()
        self._last_transcription_time = 0
        self.update_status("🧠 Whisper-Modell manuell aus VRAM entladen")
        if hasattr(self, "vram_unload_btn") and self.vram_unload_btn.winfo_exists():
            self.vram_unload_btn.config(state="disabled")

    def on_url_change(self, event: Optional[tk.Event] = None) -> None:
        url = self.url_entry.get().strip()
        if url.startswith("file://"):
            file_path = url[7:]
            if os.path.exists(file_path):
                self._start_async_language_detection(file_path)
            else:
                self._safe_gui_update(
                    lambda: self.language_info_label.config(text="❌ File not found")
                )
        else:
            self._safe_gui_update(lambda: self.language_info_label.config(text=""))
            self.current_video_language = None

    def on_language_change(self, event: Optional[tk.Event] = None) -> None:
        selected_name = self.lang_var.get()
        lang_code = DISPLAY_NAME_TO_CODE.get(selected_name)
        if not lang_code or lang_code == self.target_language:
            return
        logger.info(f"🌐 Target language changes to {lang_code} ({selected_name})")
        self.target_language = lang_code
        self.current_language = lang_code
        self.advanced_settings.target_language = lang_code
        self._schedule_settings_save()
        if hasattr(self, "translation_engine"):
            self.translation_engine.set_target_language(lang_code)
            self.translation_engine._cache_manager.translation_cache.clear()
        if hasattr(self, "audio_processor") and self.audio_processor:
            self.audio_processor.update_target_language(lang_code)
        lang_display = LANGUAGE_SHORT_CODES.get(lang_code, lang_code)
        self._safe_gui_update(
            lambda: self.translation_header.config(
                text=f"🌐 Übersetzung ({lang_display})"
            )
        )
        self.update_status(f"🌍 Target language: {selected_name}")

    def _on_language_selected(self, event) -> None:
        selected = self.lang_var.get()
        if selected.startswith("---"):
            self.lang_var.set(self._last_valid_language)
        else:
            self._last_valid_language = selected
            self.on_language_change(event)

    def on_model_change(self, event: Optional[tk.Event] = None) -> None:
        """Wird aufgerufen, wenn der Benutzer ein neues Modell in der ComboBox auswählt."""
        new_model = self.model_var.get()
        logger.info(f"🔄 on_model_change: Benutzer wählt Modell {new_model}")

        if new_model not in Config.WHISPER_MODELS:
            current = self.transcription_engine.get_current_model()
            logger.warning(
                f"Unbekanntes Modell {new_model}, setze zurück auf {current}"
            )
            self.model_var.set(current)
            return
        if new_model == self.transcription_engine.get_current_model():
            logger.debug(f"Modell {new_model} bereits aktiv – nichts zu tun")
            return
        if self.transcription_engine.is_model_loading():
            logger.warning("Modell wird bereits geladen – warte...")
            return
        logger.info(f"🔄 Wechsle zu Modell {new_model}")
        self._start_progress_for_model_switch()
        if self.transcription_engine.reload_model(new_model):
            self.update_status(f"🔄 Switching to {new_model}...")
            self._check_model_loading_complete(new_model)
            self.settings.default_model = new_model
            self.settings.save_to_file()
            logger.info(f"✅ Modell {new_model} gespeichert und geladen")
        else:
            logger.error(f"❌ Modellwechsel zu {new_model} fehlgeschlagen")
            self.model_var.set(self.transcription_engine.get_current_model())
            self._stop_progress_for_model_switch()

    def _start_progress_for_model_switch(self) -> None:
        if hasattr(self, "progress_bar") and self.progress_bar.winfo_exists():
            self.progress_bar.config(mode="indeterminate")
            self.progress_bar.start(10)
        if hasattr(self, "progress_label"):
            self.progress_label.config(text="Modell wird geladen...")

    def _stop_progress_for_model_switch(self) -> None:
        if hasattr(self, "progress_bar") and self.progress_bar.winfo_exists():
            self.progress_bar.stop()
            self.progress_bar.config(mode="determinate", value=0)
        if hasattr(self, "progress_label"):
            self.progress_label.config(text="")

    def _check_model_loading_complete(self, target_model: str) -> None:
        if self.transcription_engine.is_model_loading():
            self._safe_after(200, lambda: self._check_model_loading_complete(target_model))
        else:
            self._stop_progress_for_model_switch()
            current = self.transcription_engine.get_current_model()
            if current == target_model:
                self.update_status(f"✅ Model switched to {target_model}")
            else:
                self.update_status(f"❌ Model switch failed (current: {current})")
                self.model_var.set(current)

    @gui_operation_decorator
    def toggle_translation(self) -> None:
        """
        Schaltet die Übersetzung ein oder aus und synchronisiert den
        zugehörigen AudioProcessor sowie die GUI‑Darstellung thread‑sicher.
        """
        # Lazy-Initialisierung eines Sperr-Objekts, falls noch nicht vorhanden
        if not hasattr(self, '_translate_lock'):
            self._translate_lock = threading.RLock()

        # Atomarer Zustandswechsel und AudioProcessor-Konfiguration unter Schutz
        with self._translate_lock:
            self._translate_active = not self._translate_active
            new_state = self._translate_active

            if hasattr(self, 'audio_processor') and self.audio_processor is not None:
                try:
                    if new_state:
                        self.audio_processor._translation_enabled.set()
                    else:
                        self.audio_processor._translation_enabled.clear()
                except Exception as exc:
                    logger.error(
                        "Fehler beim Setzen des Übersetzungsstatus im AudioProcessor: %s",
                        exc,
                    )

        # GUI‑Aktualisierungen werden außerhalb des Locks durchgeführt,
        # um Blockaden zu vermeiden.
        if hasattr(self, 'translate_btn') and self.translate_btn is not None:
            try:
                if self.translate_btn.winfo_exists():
                    self.translate_btn.config(
                        text="🌐 ON" if new_state else "🌐 OFF",
                        bg=(
                            self.current_theme.SUCCESS
                            if new_state
                            else self.current_theme.BG_TERTIARY
                        ),
                    )
            except tk.TclError:
                pass

        status_msg = (
            "✅ Translation active" if new_state else "❌ Translation inactive"
        )
        self.update_status(status_msg)

    def toggle_subtitle_mode(self) -> None:
        """
        Magischer Untertitel‑Schalter – der Drache spuckt Zeitstempel! 🔥🐉

        Im aktiven Zustand pulsiert der Button in feurigen Orange‑Tönen,
        zeigt wechselnde Drachen‑Icons und einen ausführlichen Tooltip.
        """
        if getattr(self, "_toggling_subtitle", False):
            return
        self._toggling_subtitle = True

        new_mode = not self.subtitle_mode
        ap = getattr(self, "audio_processor", None)
        if ap is not None:
            try:
                ap.enable_subtitle_mode(new_mode)
            except Exception as exc:
                logger.error("Subtitle-Mode Fehler im AudioProcessor: %s", exc)
                self.update_status("❌ Untertitel‑Modus konnte nicht aktiviert werden")
                self._toggling_subtitle = False
                return

        self.subtitle_mode = new_mode
        btn = getattr(self, "subtitle_btn", None)
        if btn is None or not btn.winfo_exists():
            self._toggling_subtitle = False
            return

        theme = self.current_theme
        active_color   = "#f97316"   # kräftiges Orange
        glow_color     = "#f59e0b"   # goldener Schimmer
        inactive_color = getattr(theme, "SUBTITLE_INACTIVE", "#30363d")

        # Alte Animation abbrechen
        if hasattr(self, "_subtitle_anim_id"):
            try:
                self.root.after_cancel(self._subtitle_anim_id)
            except (ValueError, tk.TclError):
                pass
            self._subtitle_anim_id = None

        if new_mode:
            # ── AKTIV: Mehrstufige Feuer‑Animation ─────────────────
            # Schritt‑Sequenz (delay_ms, Text, Schriftgröße, Farbe)
            steps = [
                (0,   "🐉🔥",     14, active_color),
                (120, "🐉🔥",     16, glow_color),
                (240, "🎬 SUB ON", 14, glow_color),
                (360, "🎬 SUB ON", 10, active_color),
            ]
            for delay, text, size, color in steps:
                self.root.after(
                    delay,
                    lambda t=text, s=size, c=color: self._animate_button(btn, t, s, c),
                )

            # Nach der Startsequenz die pulsierende Dauerschleife starten
            self.root.after(500, self._start_subtitle_pulse, btn, active_color, glow_color)

            # Tooltip aktualisieren
            try:
                if hasattr(btn, "tooltip") and btn.tooltip is not None:
                    btn.tooltip.text = (
                        "🐉 Drachenatem AKTIV!\n"
                        "Zeitstempel werden ausgegeben – der Drache spuckt Feuer!"
                    )
            except Exception:
                pass

            self.update_status("🔥 Untertitel AKTIV – der Drache spuckt Zeitstempel!")

        else:
            # ── INAKTIV: zurück zum dezenten Design ─────────────────
            try:
                btn.config(
                    text="🎬 SUB",
                    bg=inactive_color,
                    fg=theme.TEXT_PRIMARY,
                    font=("Segoe UI", 9),
                )
            except tk.TclError:
                pass

            # Tooltip zurücksetzen
            try:
                if hasattr(btn, "tooltip") and btn.tooltip is not None:
                    btn.tooltip.text = (
                        "Untertitel‑Modus aktivieren – für lückenlose, "
                        "chronologische Transkription mit Zeitstempeln."
                    )
            except Exception:
                pass

            self.update_status("📝 Normaler Modus – fortlaufender Text")

        if self.event_bus is not None:
            try:
                self.event_bus.emit("subtitle_mode_changed", new_mode)
            except Exception:
                pass

        if DEBUG_LEVEL >= 2:
            log_debug("gui", "toggle_subtitle_mode: jetzt %s", new_mode)

        self.root.after(600, lambda: setattr(self, "_toggling_subtitle", False))

    def _animate_button(self, btn: tk.Button, text: str, font_size: int, color: str) -> None:
        """Setzt Text, Schriftgröße und Farbe – fängt TclError bei Shutdown ab."""
        try:
            btn.config(text=text, font=("Segoe UI", font_size, "bold"), bg=color)
        except tk.TclError:
            pass

    def _start_subtitle_pulse(self, btn: tk.Button, color1: str, color2: str) -> None:
        """Startet die pulsierende Farbanimation, solange der Subtitle‑Modus aktiv ist."""
        if not self.subtitle_mode:
            return
        self._subtitle_anim_colors = [color1, color2]
        self._subtitle_anim_index = 0

        def pulse():
            if not self.subtitle_mode:
                return
            try:
                if btn.winfo_exists():
                    color = self._subtitle_anim_colors[self._subtitle_anim_index % 2]
                    btn.config(bg=color)
                    self._subtitle_anim_index += 1
                    self._subtitle_anim_id = self.root.after(800, pulse)
            except tk.TclError:
                pass

        pulse()

    def _on_start_click(self) -> None:
        """Behandelt den Klick auf den START‑Button.

        Diese Methode ist **vollständig defensiv** und garantiert, dass
        die GUI auch bei Ausnahmen in einen konsistenten Zustand
        zurückfällt.  Sie führt eine kurze Vorabprüfung durch und
        delegiert dann an ``start_processing``.

        .. versionchanged:: 4.1.3
            Delegiert jetzt an ``start_processing``, enthält selbst
            nur noch das absolute Minimum an GUI‑Logik.
        """
        # ── 1. Bereits aktiv? ────────────────────────────────────────
        if self.is_processing:
            self.update_status("⚠️ Bereits aktiv – warte auf Abschluss")
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_on_start_click: already processing, ignoring")
            return

        # ── 2. Referenz auf die Start‑Methode holen ──────────────────
        start_func = getattr(self, "start_processing", None)
        if not callable(start_func):
            logger.error(
                "start_processing ist nicht aufrufbar – kann nicht starten"
            )
            self.update_status("❌ Interner Fehler: Start‑Methode fehlt")
            return

        # ── 3. Buttons vorbereiten ───────────────────────────────────
        start_btn = getattr(self, "start_button", None)
        stop_btn = getattr(self, "stop_button", None)
        try:
            if start_btn is not None and start_btn.winfo_exists():
                start_btn.config(state="disabled")
        except tk.TclError:
            pass
        try:
            if stop_btn is not None and stop_btn.winfo_exists():
                stop_btn.config(state="normal")
        except tk.TclError:
            pass

        # ── 4. Start ausführen ───────────────────────────────────────
        try:
            start_func()
        except Exception as exc:
            logger.exception("Fehler in start_processing: %s", exc)
            self.update_status("❌ Interner Fehler beim Start")
            # Buttons zurücksetzen
            try:
                if start_btn is not None and start_btn.winfo_exists():
                    start_btn.config(state="normal")
            except tk.TclError:
                pass
            try:
                if stop_btn is not None and stop_btn.winfo_exists():
                    stop_btn.config(state="disabled")
            except tk.TclError:
                pass

    def start_processing(self) -> None:
        """
        Vorbereitung und Start der Audio‑Verarbeitung aus der GUI heraus.
        """
        # ═══════════════════════════════════════════════════════════════
        # 1. Bereits aktiv?
        # ═══════════════════════════════════════════════════════════════
        if self.is_processing:
            self.update_status("⚠️ Bereits aktiv – warte auf Abschluss")
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "start_processing: already processing, ignoring")
            return

        # ═══════════════════════════════════════════════════════════════
        # 2. URL aus dem Eingabefeld holen und bereinigen
        # ═══════════════════════════════════════════════════════════════
        url = ""
        try:
            if hasattr(self, "url_entry") and self.url_entry.winfo_exists():
                url = self.url_entry.get().strip()
        except tk.TclError as exc:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "start_processing: TclError reading URL: %s", exc)
            self.update_status("❌ Fehler beim Lesen des URL‑Feldes")
            return
        except Exception as exc:
            logger.error("Unerwarteter Fehler beim Lesen der URL: %s", exc)
            self.update_status("❌ Interner Fehler")
            return

        if not url:
            self.update_status("❌ Bitte eine URL eingeben")
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "start_processing: empty URL")
            return        

        # Lokale Datei – Existenz und Lesbarkeit prüfen
        if url.startswith("file://"):
            file_path = url[7:]
            if not os.path.exists(file_path):
                self.update_status("❌ Datei nicht gefunden")
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "start_processing: file not found: %s", file_path)
                return
            if not os.access(file_path, os.R_OK):
                self.update_status("❌ Keine Leserechte für die Datei")
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "start_processing: no read permission: %s", file_path)
                return

        # ═══════════════════════════════════════════════════════════════
        # 3. Sicherstellen, dass ein Whisper‑Modell geladen ist
        # ═══════════════════════════════════════════════════════════════
        if hasattr(self, "transcription_engine") and self.transcription_engine is not None:
            current_model = self.transcription_engine.get_current_model()
            if current_model in (None, "None", "not loaded", "dummy (Demo)"):
                self.update_status("❌ Kein KI‑Modell geladen – wähle ein Modell aus der Liste")
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "start_processing: no model loaded (%s)", current_model)
                return
        else:
            self.update_status("❌ Transkriptions‑Engine nicht verfügbar")
            return

        # ═══════════════════════════════════════════════════════════════
        # 4. Einstellungen aus AdvancedSettings in die GUI‑Variablen
        #    übernehmen und mit dem AudioProcessor synchronisieren
        # ═══════════════════════════════════════════════════════════════
        try:
            adv = self.advanced_settings
            if hasattr(self, "auto_tts_transcript_var"):
                self.auto_tts_transcript_var.set(adv.auto_tts_transcript)
            if hasattr(self, "auto_tts_translation_var"):
                self.auto_tts_translation_var.set(adv.auto_tts_translation)

            # Auto‑TTS‑Flags in den AudioProcessor propagieren
            sync_func = getattr(self, "_sync_auto_tts_to_processor", None)
            if sync_func is not None:
                try:
                    sync_func()
                except Exception as sync_exc:
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "TTS sync failed: %s", sync_exc)
        except Exception as exc:
            logger.warning("Konnte Auto‑TTS‑Einstellungen nicht synchronisieren: %s", exc)

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            # Thread‑sichere Abfrage des Übersetzungsstatus
            if not hasattr(self, '_translate_lock'):
                self._translate_lock = threading.RLock()
            with self._translate_lock:
                translation_active = self._translate_active
            if translation_active:
                self.audio_processor._translation_enabled.set()
                log_debug("gui", "Translation enabled (GUI → AudioProcessor)")
            else:
                self.audio_processor._translation_enabled.clear()
                log_debug("gui", "Translation disabled (GUI → AudioProcessor)")

        # ═══════════════════════════════════════════════════════════════
        # 5. UI‑Elemente für den Start vorbereiten
        # ═══════════════════════════════════════════════════════════════
        # Letzte URL für den nächsten Programmstart speichern
        try:    
            self.settings.last_url = url
            self._schedule_settings_save()
        except Exception as exc:
            logger.debug("Konnte last_url nicht speichern: %s", exc)

        # Fortschrittsbalken zurücksetzen, bevor der Controller losläuft
        self._reset_progress()

        start_btn = getattr(self, "start_button", None)
        stop_btn  = getattr(self, "stop_button", None)

        if start_btn is not None and start_btn.winfo_exists():
            start_btn.config(state="disabled")
        if stop_btn is not None and stop_btn.winfo_exists():
            stop_btn.config(state="normal")

        self.update_status("🚀 Starte Verarbeitung …")
        if DEBUG_LEVEL >= 3:
            log_debug("gui", "start_processing: GUI updated, calling controller")

        # ═══════════════════════════════════════════════════════════════
        # 6. Verarbeitung an den Controller delegieren
        # ═══════════════════════════════════════════════════════════════
        try:
            self.controller.start_processing()
        except Exception as exc:
            logger.exception("Fehler beim Start des Controllers: %s", exc)
            self.update_status("❌ Interner Fehler beim Start")
            # GUI zurücksetzen, damit der Benutzer es erneut versuchen kann
            if start_btn is not None and start_btn.winfo_exists():
                start_btn.config(state="normal")
            if stop_btn is not None and stop_btn.winfo_exists():
                stop_btn.config(state="disabled")

    def toggle_layout(self) -> None:
        """Schaltet das Layout zwischen vertikal und horizontal um, ohne Datenverlust.

        Die Methode ist defensiv: falls der Layout-Manager nicht verfügbar ist
        oder der Wiederaufbau der Textbereiche fehlschlägt, wird der alte Zustand
        beibehalten und eine entsprechende Statusmeldung ausgegeben.
        """
        # 1. Layout-Manager prüfen
        if not hasattr(self, 'layout') or self.layout is None:
            self.update_status("❌ Layout-Manager nicht verfügbar")
            return

        # 2. Aktuelle Inhalte sichern (Transkription und Übersetzung)
        old_transcript = ""
        old_translation = ""
        try:
            old_transcript = self._get_text_widget_content("transcript_text")
        except Exception as e:
            log_debug("layout", f"Konnte Transkriptionstext nicht lesen: {e}")
        try:
            old_translation = self._get_text_widget_content("translation_text")
        except Exception as e:
            log_debug("layout", f"Konnte Übersetzungstext nicht lesen: {e}")

        # 3. Modus wechseln
        old_mode = self.layout_mode
        self.layout_mode = (
            "horizontal" if self.layout_mode == "vertical" else "vertical"
        )
        new_mode = self.layout_mode

        # 4. Einstellung persistent speichern
        self.settings.layout_mode = self.layout_mode
        try:
            self.settings.save_to_file()
        except Exception as e:
            logger.warning(f"Konnte Layout-Modus nicht speichern: {e}")

        # 5. Ziel-Layout aufbauen – erzeugt neue Text-Widgets
        new_transcript = None
        new_translation = None
        try:
            new_transcript, new_translation = self.layout.create_text_areas()
        except Exception as e:
            logger.exception(f"Fehler beim Layout-Wechsel: {e}")
            self.update_status("❌ Layout-Wechsel fehlgeschlagen")
            # Zurückwechseln zum alten Modus, um Konsistenz zu wahren
            self.layout_mode = old_mode
            # Widgets könnten zerstört sein; versuche trotzdem alten Stand wiederherzustellen
            try:
                self.layout.create_text_areas()
            except Exception:
                pass
            return

        # 6. Gesicherten Text in die neuen Widgets übertragen
        if new_transcript and old_transcript:
            try:
                new_transcript.insert("1.0", old_transcript)
            except tk.TclError as e:
                log_debug("layout", f"Fehler beim Einfügen des Transkriptionstextes: {e}")
        if new_translation and old_translation:
            try:
                new_translation.insert("1.0", old_translation)
            except tk.TclError as e:
                log_debug("layout", f"Fehler beim Einfügen des Übersetzungstextes: {e}")

        # 7. GUI-Rückmeldung
        mode_display = "Horizontal" if new_mode == "horizontal" else "Vertical"
        self.update_status(f"✅ {mode_display} Layout aktiv")

    def _get_text_widget_content(self, attr: str) -> str:
        widget = getattr(self, attr, None)
        if widget and widget.winfo_exists():
            try:
                return widget.get("1.0", "end-1c")
            except tk.TclError:
                pass
        return ""

    def _bind_shortcuts(self) -> None:
        """
        Bindet alle Tastaturkürzel an das Hauptfenster.

        Verwendet die plattformspezifische Modifikatortaste (Cmd auf macOS, Strg sonst).
        Jede Bindung ist defensiv durch ``try/except`` geschützt, sodass ein
        eventuell fehlendes Attribut nicht zum Abbruch führt.
        """
        mod = "Command" if IS_MACOS else "Control"

        # ── Datei / URL ──────────────────────────────────────────
        try:
            self.root.bind(f"<{mod}-o>", lambda e: self.select_file_dark())
        except Exception:
            pass
        try:
            self.root.bind(f"<{mod}-v>", lambda e: self.paste_url())
        except Exception:
            pass

        # ── Verarbeitung starten / stoppen ───────────────────────
        try:
            self.root.bind(f"<{mod}-Return>", lambda e: self._on_start_click())
        except Exception:
            pass
        try:
            self.root.bind(
                "<Control-Shift-X>",
                lambda e: (
                    self.controller.stop_processing()
                    if hasattr(self, "controller") and self.controller is not None
                    else None
                ),
            )
        except Exception:
            pass

        # ── Programm beenden ─────────────────────────────────────
        try:
            self.root.bind(f"<{mod}-q>", lambda e: self._safe_exit_dialog())
        except Exception:
            pass

        # ── Speichern / Exportieren ──────────────────────────────
        try:
            self.root.bind(f"<{mod}-s>", lambda e: self.save_transcript())
        except Exception:
            pass
        try:
            self.root.bind(f"<{mod}-e>", lambda e: self.export_subtitles())
        except Exception:
            pass

        # ── Layout & Modi umschalten ─────────────────────────────
        try:
            self.root.bind(f"<{mod}-l>", lambda e: self.toggle_layout())
        except Exception:
            pass
        try:
            self.root.bind(f"<{mod}-t>", lambda e: self.toggle_translation())
        except Exception:
            pass
        try:
            self.root.bind(f"<{mod}-u>", lambda e: self.toggle_subtitle_mode())
        except Exception:
            pass

        # ── Alles löschen ────────────────────────────────────────
        try:
            self.root.bind(f"<{mod}-Shift-c>", lambda e: self.clear_all())
        except Exception:
            pass

        # ── Hilfe ────────────────────────────────────────────────
        try:
            self.root.bind(f"<{mod}-h>", lambda e: self.show_shortcuts_help())
        except Exception:
            pass
        try:
            self.root.bind("<F1>", lambda e: self.show_shortcuts_help())
        except Exception:
            pass

        # ── URL‑Eingabefeld: Einfügen unterbinden, damit Strg+V
        #     an die GUI weitergeleitet werden kann ───────────────
        url_entry = getattr(self, "url_entry", None)
        if url_entry is not None:
            try:
                url_entry.bind(f"<{mod}-v>", lambda e: "break")
            except Exception:
                pass

    def clear_all(self) -> None:
        for attr in ("transcript_text", "translation_text"):
            widget = getattr(self, attr, None)
            if widget and widget.winfo_exists():
                self._safe_gui_update(lambda w=widget: w.delete("1.0", "end"))
        with self._history_lock:
            self.transcript_history.clear()
            self.translation_history.clear()
        if hasattr(self, "memory_manager"):
            self.memory_manager.clear_component("transcript")
            self.memory_manager.clear_component("translation")
        self._last_transcription_text = ""
        self._last_translation_text = ""
        self.update_status("🗑️ Cleared & optimizations reset")

    @gui_operation_decorator
    def save_transcript(self) -> None:
        if not self.transcript_history:
            DarkMessageBox.showinfo(
                "WARNING", "No transcriptions available to save.", self.root
            )
            return
        base_name = self._get_safe_filename()
        suggested = f"{base_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        filename = filedialog.asksaveasfilename(
            defaultextension=".txt",
            initialfile=suggested,
            filetypes=[
                ("Text files", "*.txt"),
                ("SRT subtitles", "*.srt"),
                ("WebVTT", "*.vtt"),
                ("JSON", "*.json"),
                ("Word document", "*.docx"),
            ],
        )
        if not filename:
            return
        ext = Path(filename).suffix.lower()
        if ext == ".srt":
            success = self.export_manager.export_subtitles(
                list(self.transcript_history), None, "srt", filename
            )
        elif ext == ".vtt":
            success = self.export_manager.export_subtitles(
                list(self.transcript_history), None, "vtt", filename
            )
        elif ext == ".json":
            success = self.export_manager.export_json(
                list(self.transcript_history), list(self.translation_history), filename
            )
        elif ext == ".docx":
            success = self.export_manager.export_docx(
                list(self.transcript_history), filename
            )
        else:
            success = self._save_as_text(filename)
        self.update_status(
            f"💾 Saved: {os.path.basename(filename)}" if success else "❌ Export failed"
        )

    def _get_safe_filename(self) -> str:
        if self.current_stream_info and self.current_stream_info.title:
            return (
                re.sub(r"[^\w\-_\. ]", "", self.current_stream_info.title)
                .strip()
                .replace(" ", "_")[:50]
            )
        return "transcript"

    def _save_as_text(self, filename: str) -> bool:
        try:
            with open(filename, "w", encoding="utf-8") as f:
                if self.current_stream_info:
                    f.write("=== STREAM INFORMATION ===\n")
                    f.write(f"Title: {self.current_stream_info.title}\n")
                    f.write(f"Uploader: {self.current_stream_info.uploader}\n")
                    f.write(f"Duration: {self.current_stream_info.duration}\n")
                    f.write(f"Platform: {self.current_stream_info.platform}\n")
                    f.write(
                        f"Saved at: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
                    )
                f.write("=== TRANSCRIPT ===\n")
                f.write(self._get_text_widget_content("transcript_text"))
                f.write("\n\n=== TRANSLATION ===\n")
                f.write(self._get_text_widget_content("translation_text"))
            return True
        except Exception:
            return False

    def export_subtitles(self) -> None:
        if (
            not hasattr(self, "audio_processor")
            or not self.audio_processor._timed_transcriptions
        ):
            DarkMessageBox.showinfo(
                "WARNING",
                "No subtitle data available.\nActivate '🎬 Subtitle mode' first.",
                self.root,
            )
            return
        filename = filedialog.asksaveasfilename(
            defaultextension=".srt",
            filetypes=[("SRT subtitles", "*.srt"), ("VTT subtitles", "*.vtt")],
        )
        if not filename:
            return
        ext = Path(filename).suffix.lower()
        fmt = "srt" if ext == ".srt" else "vtt"
        with self.audio_processor._subtitle_lock:
            timed_trans = list(self.audio_processor._timed_transcriptions)
            timed_transl = list(self.audio_processor._timed_translations)
        if self.export_manager.export_subtitles(
            timed_trans, timed_transl, format=fmt, filename=filename
        ):
            self.update_status(
                f"📝 {fmt.upper()} exported: {os.path.basename(filename)}"
            )
            DarkMessageBox.showinfo(
                "Success",
                f"Subtitles exported!\nSegments: {len(timed_trans)}\nTranslations: {len(timed_transl)}",
                self.root,
            )
        else:
            self.update_status("❌ Subtitle export failed")

    @gui_operation_decorator
    def show_simple_stats(self) -> None:
        perf_stats = self.performance_monitor.get_basic_stats()
        audio_status = (
            self.audio_processor.get_status()
            if hasattr(self, "audio_processor")
            else {}
        )
        memory_stats = (
            self.memory_manager.get_memory_stats()
            if hasattr(self, "memory_manager")
            else {}
        )
        cache_stats = (
            self.app_context.cache_manager.get_stats() if self.app_context else {}
        )
        system_info = self._get_system_info()
        gpu_text = self._get_gpu_text()
        model_info = self._get_model_info()
        config_info = self._get_config_info()
        stats_text = self._build_stats_text(
            perf_stats,
            audio_status,
            memory_stats,
            cache_stats,
            system_info,
            gpu_text,
            model_info,
            config_info,
        )
        StatisticsDialog(self.root, stats_text)

    def _get_system_info(self) -> Dict[str, Any]:
        try:
            import psutil
            cpu = psutil.cpu_percent(interval=0.5)
            mem = psutil.virtual_memory()
            return {
                "cpu": cpu,
                "mem_used": mem.used // (1024**2),
                "mem_total": mem.total // (1024**2),
                "mem_percent": mem.percent,
            }
        except ImportError:
            return {"cpu": 0, "mem_used": 0, "mem_total": 0, "mem_percent": 0}

    def _get_gpu_text(self) -> str:
        if not TORCH_AVAILABLE:
            return "PyTorch not available"
        try:
            import torch
            if torch.cuda.is_available():
                props = torch.cuda.get_device_properties(0)
                allocated = torch.cuda.memory_allocated(0) / (1024**3)
                reserved = torch.cuda.memory_reserved(0) / (1024**3)
                total = props.total_memory / (1024**3)
                return f"{props.name} | VRAM: {allocated:.2f}/{total:.2f}GB (reserved {reserved:.2f}GB)"
            return "No CUDA device"
        except Exception as e:
            return f"GPU error: {e}"

    def _get_model_info(self) -> Dict[str, Any]:
        if not hasattr(self, "transcription_engine"):
            return {
                "name": "unknown",
                "device": "unknown",
                "compute_type": "unknown",
                "backend": "unknown",
                "estimated_gb": None,
            }
        engine = self.transcription_engine
        name = engine.get_current_model()
        if name == "None":
            name = "not loaded"
        info = {
            "name": name,
            "device": getattr(engine, "device", "unknown"),
            "compute_type": getattr(engine, "compute_type", "unknown"),
            "backend": getattr(engine, "whisper_backend", "unknown"),
        }
        info["estimated_gb"] = (
            engine._estimate_model_memory(name) if name != "not loaded" else None
        )
        return info

    def _get_config_info(self) -> List[str]:
        adv = self.advanced_settings
        lines = [
            f"Chunk duration: {adv.chunk_duration:.1f}s",
            f"VAD filter: {'ON' if adv.vad_filter else 'OFF'}",
            f"Beam size: {adv.beam_size}",
            f"Temperature: {adv.temperature:.1f}",
            f"GPU acceleration: {'ON' if adv.gpu_acceleration else 'OFF'}",
            f"Translation engine: {adv.translation_engine}",
        ]
        if adv.translation_engine == "ollama":
            lines.append(f"  Ollama model: {adv.ollama_model}")
        lines.append(f"Audio profile: {adv.audio_profile}")
        lines.append(f"Adaptive chunk: {'ON' if adv.adaptive_chunk else 'OFF'}")
        return lines

    def _build_stats_text(
        self,
        perf_stats,
        audio_status,
        memory_stats,
        cache_stats,
        system_info,
        gpu_text,
        model_info,
        config_info,
    ) -> str:
        """
        Erstellt einen detaillierten Statistik-String für den Performance-Dialog.
        Nutzt die Hardware-Diagnosedaten der TranscriptionEngine und erweiterte Audio-Metriken.
        """
        lines = ["🐉 DRAGON WHISPERER STATISTICS", "=" * 70, ""]

        lines.append("📊 SESSION OVERVIEW")
        lines.append(f"   Runtime: {perf_stats['uptime_minutes']:.1f} minutes")
        lines.append(f"   Platform: {SYSTEM} {'ARM' if IS_ARM else 'x86'}")
        lines.append(
            f"   Subtitle mode: {'ACTIVE' if self.subtitle_mode else 'inactive'}"
        )
        lines.append(f"   Translation: {'ON' if self.translate_active else 'OFF'}")
        lines.append("")

        hw = None
        if (
            hasattr(self, "transcription_engine")
            and self.transcription_engine is not None
        ):
            try:
                hw = self.transcription_engine.get_hardware_diagnostics()
            except Exception as e:
                logger.debug(f"Konnte Hardware-Diagnose nicht abrufen: {e}")

        lines.append("🖥️ HARDWARE DETAILS")
        if hw is not None:
            lines.append(
                f"   Device: {hw.get('device', 'unknown').upper()} (Compute-Type: {hw.get('compute_type', 'unknown')})"
            )

            if hw.get("device") == "cuda":
                lines.append(
                    f"   GPU: {hw.get('gpu_name', 'Unknown')} (CC {hw.get('compute_capability', 'N/A')})"
                )
                vram_free = hw.get("vram_free_gb")
                vram_req = hw.get("vram_required_gb")
                if vram_free is not None and vram_req is not None:
                    status = "✅ Ausreichend" if vram_free >= vram_req else "⚠️ Knapp"
                    lines.append(
                        f"   VRAM: {vram_free:.1f} GB frei / benötigt ~{vram_req:.1f} GB ({status})"
                    )
                lines.append(
                    f"   CUDA: {hw.get('cuda_version', 'N/A')} (PyTorch {hw.get('pytorch_version', 'N/A')})"
                )
            elif hw.get("device") == "cpu":
                cpu_feat = hw.get("cpu_features", {})
                lines.append(f"   CPU Cores: {hw.get('cpu_count', 'N/A')}")
                lines.append(
                    f"   AVX2: {'✅ Ja' if cpu_feat.get('avx2') else '❌ Nein (langsamer)'}"
                )
                lines.append(
                    f"   AVX512: {'✅ Ja' if cpu_feat.get('avx512') else '❌ Nein'}"
                )
            elif hw.get("device") == "mps":
                lines.append(
                    f"   Apple Silicon (MPS) – Compute-Type: {hw.get('compute_type')}"
                )
            elif hw.get("device") == "xpu":
                lines.append(
                    f"   Intel GPU (oneAPI) – Compute-Type: {hw.get('compute_type')}"
                )

            lines.append(
                f"   GPU Acceleration: {'✅ Aktiv' if hw.get('gpu_acceleration_enabled') else '❌ Deaktiviert'}"
            )
            lines.append(
                f"   OOM aufgetreten: {'⚠️ Ja' if hw.get('last_oom') else '✅ Nein'}"
            )
        else:
            lines.append("   Keine Hardware-Diagnosedaten verfügbar.")
        lines.append("")
        lines.append("🤖 MODEL INFORMATION")
        lines.append(f"   Active model: {model_info.get('name', 'unknown')}")
        lines.append(f"   Backend: {model_info.get('backend', 'unknown')}")
        lines.append(
            f"   Device: {model_info.get('device', 'unknown')} ({model_info.get('compute_type', 'unknown')})"
        )
        if model_info.get("estimated_gb"):
            lines.append(
                f"   Estimated model size: {model_info['estimated_gb']:.1f} GB"
            )
        if hw is not None:
            lines.append(f"   Forced language: {hw.get('forced_language') or 'auto'}")
            lines.append(
                f"   Last detected: {hw.get('last_detected_language') or 'unknown'}"
            )
        lines.append("")
        lines.append("🎙️ TRANSCRIPTION & TRANSLATION")
        lines.append(f"   Transcriptions: {perf_stats['transcriptions']}")
        lines.append(f"   Translations: {perf_stats['translations']}")
        lines.append(f"   Cache hit rate: {perf_stats['cache_hit_rate']}")
        lines.append("")

        if audio_status:
            lines.append("🌊 STREAM STABILITY")
            lines.append(
                f"   Chunks processed: {audio_status.get('chunks_processed', 0)}"
            )
            lines.append(f"   Queue drops: {audio_status.get('queue_dropped', 0)}")
            lines.append(
                f"   Consecutive timeouts: {audio_status.get('consecutive_timeouts', 0)}"
            )
            lines.append(
                f"   Consecutive errors: {audio_status.get('consecutive_errors', 0)}"
            )
            lines.append(
                f"   Low confidence chunks: {audio_status.get('low_conf_counter', 0)}"
            )
            rt_factor = audio_status.get("last_realtime_factor", 0)
            if rt_factor > 0:
                status = (
                    "✅ Echtzeit" if rt_factor <= 1.0 else f"⚠️ Faktor {rt_factor:.2f}"
                )
                lines.append(f"   Realtime factor: {status}")
            lines.append("")
        stream_diag = None
        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            try:
                if (
                    hasattr(self.audio_processor, "_stream_handler")
                    and self.audio_processor._stream_handler is not None
                ):
                    stream_diag = self.audio_processor._stream_handler.get_diagnosis()
            except Exception as e:
                logger.debug(f"Konnte Stream-Diagnose nicht abrufen: {e}")
        if stream_diag:
            lines.append("🔄 RECONNECT STATISTICS")
            lines.append(
                f"   Total reconnects: {stream_diag.get('total_reconnects', 0)}"
            )
            lines.append(
                f"   Slow read events: {stream_diag.get('slow_read_events', 0)}"
            )
            lines.append(f"   Platform: {stream_diag.get('platform', 'unknown')}")
            lines.append("")

        lines.append("💻 SYSTEM RESOURCES")
        lines.append(f"   CPU usage: {system_info['cpu']:.1f}%")
        lines.append(
            f"   RAM: {system_info['mem_used']}/{system_info['mem_total']} MB ({system_info['mem_percent']:.1f}%)"
        )
        lines.append(f"   GPU: {gpu_text}")
        lines.append("")

        lines.append("⚙️ CONFIGURATION")
        lines.extend(config_info)
        lines.append("")

        lines.append("💾 CACHE STATISTICS")
        trans_cache = cache_stats.get("transcription_cache", {})
        transl_cache = cache_stats.get("translation_cache", {})
        audio_cache = cache_stats.get("audio_cache", {})
        lines.append(
            f"   Transcription cache: {trans_cache.get('size', 0)}/{trans_cache.get('maxsize', 0)}"
        )
        lines.append(
            f"   Translation cache: {transl_cache.get('size', 0)}/{transl_cache.get('maxsize', 0)}"
        )
        lines.append(
            f"   Audio cache: {audio_cache.get('size', 0)}/{audio_cache.get('maxsize', 0)}"
        )
        lines.append("")

        lines.append("=" * 70)
        lines.append(
            f"✅ Data collected at: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        )
        return "\n".join(lines)

    @gui_operation_decorator
    def _reset_progress(self) -> None:
        """
        Setzt den Fortschrittsbalken und das zugehörige Label in der GUI zurück.        """
        if not hasattr(self, "progress_bar") or self.progress_bar is None:
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "_reset_progress: progress_bar nicht vorhanden")
            return
        if not hasattr(self, "progress_label") or self.progress_label is None:
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "_reset_progress: progress_label nicht vorhanden")
            pass
        try:
            if self.progress_bar.winfo_exists():
                self.progress_bar.stop()
                self.progress_bar.config(mode="determinate", value=0)
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "Progress bar reset to 0")
            else:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", "Progress bar widget does not exist")
        except tk.TclError as e:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", f"TclError resetting progress bar: {e}")
        except Exception as e:
            logger.warning(f"⚠️ Failed to reset progress bar: {e}", exc_info=True)

        if hasattr(self, "progress_label") and self.progress_label is not None:
            try:
                if self.progress_label.winfo_exists():
                    self.progress_label.config(text="")
                    if DEBUG_LEVEL >= 4:
                        log_debug("gui", "Progress label cleared")
                else:
                    if DEBUG_LEVEL >= 4:
                        log_debug("gui", "Progress label widget does not exist")
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError resetting progress label: {e}")
            except Exception as e:
                logger.warning(f"⚠️ Failed to reset progress label: {e}")
        if hasattr(self, "_progress_bar_started"):
            self._progress_bar_started = False
        if DEBUG_LEVEL >= 3:
            log_debug("gui", "_reset_progress: completed successfully")

    @gui_operation_decorator
    def speak_current_text(self) -> None:
        """        Optimierte Methode zum Vorlesen des aktuell ausgewählten Textes
        (oder des gesamten fokussierten Textfeldes) mit der konfigurierten TTS-Engine.        """
        if self.is_shutting_down():
            if DEBUG_LEVEL >= 3:
                log_debug("tts_gui", "speak_current_text: Shutdown aktiv – Abbruch")
            return

        if not hasattr(self, "tts_manager") or self.tts_manager is None:
            self.update_status("❌ TTS-Manager nicht verfügbar")
            if DEBUG_LEVEL >= 3:
                log_debug("tts_gui", "speak_current_text: TTS-Manager fehlt")
            return

        with self._tts_lock:
            if self._tts_active:
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: TTS bereits aktiv – stoppe vorherige Wiedergabe")
                self.tts_manager.stop()
                if hasattr(self, 'audio_processor') and self.audio_processor is not None:
                    try:
                        self.audio_processor._resume_transcription_after_tts()
                        if DEBUG_LEVEL >= 3:
                            log_debug("tts_gui", "Transkriptions-Drosselung nach Stop aufgehoben")
                    except Exception as e:
                        logger.warning("Fehler beim Aufheben der Drosselung nach Stop: %s", e)
                self._tts_active = False
                self._update_tts_button_state()
                self.update_status("⏹️ Sprachausgabe gestoppt")
                time.sleep(0.1)

        # Fokussiertes Widget ermitteln
        try:
            focused = self.root.focus_get()
        except Exception as e:
            logger.warning("speak_current_text: Konnte fokussiertes Widget nicht ermitteln: %s", e)
            self.update_status("❌ Kein Textfeld fokussiert")
            return

        if focused is None:
            self.update_status("❌ Kein Textfeld fokussiert")
            return

        # Text aus dem fokussierten Widget extrahieren
        text = ""
        source_description = ""
        if focused == getattr(self, "transcript_text", None):
            widget = self.transcript_text
            source_description = "Transkription"
        elif focused == getattr(self, "translation_text", None):
            widget = self.translation_text
            source_description = "Übersetzung"
        else:
            self.update_status(
                "❌ Bitte Transkriptions- oder Übersetzungsfeld fokussieren"
            )
            return

        if not widget.winfo_exists():
            self.update_status("❌ Textfeld existiert nicht mehr")
            return

        try:
            if widget.tag_ranges(tk.SEL):
                text = widget.get(tk.SEL_FIRST, tk.SEL_LAST)
                source_description += " (Auswahl)"
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: Auswahl in %s, %d Zeichen",
                               source_description, len(text))
            else:
                text = widget.get("1.0", "end-1c")
                source_description += " (alles)"
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: Gesamter Text in %s, %d Zeichen",
                               source_description, len(text))
        except tk.TclError as e:
            logger.warning("speak_current_text: TclError beim Auslesen des Textes: %s", e)
            self.update_status("❌ Fehler beim Auslesen des Textes")
            return

        if not text or not text.strip():
            self.update_status("❌ Kein Text zum Vorlesen")
            if DEBUG_LEVEL >= 3:
                log_debug("tts_gui", "speak_current_text: Text ist leer")
            return
        original_length = len(text)
        cleaned_text = self._clean_tts_text(text)
        if not cleaned_text:
            self.update_status("❌ Nach Entfernen der Zeitstempel kein Text übrig")
            if DEBUG_LEVEL >= 3:
                log_debug("tts_gui", "speak_current_text: Bereinigter Text ist leer")
            return

        if DEBUG_LEVEL >= 3:
            log_debug("tts_gui", "speak_current_text: Text bereinigt (%d → %d Zeichen)",
                       original_length, len(cleaned_text))
            if DEBUG_LEVEL >= 4:
                preview = cleaned_text[:100] + "..." if len(cleaned_text) > 100 else cleaned_text
                log_debug("tts_gui", f"  Vorschau: {preview}")
        engine_name = self.advanced_settings.tts_engine
        if not self.tts_manager.is_available(engine_name):
            fallback_engine = None
            for fallback in ("piper", "pyttsx3", "espeak"):
                if self.tts_manager.is_available(fallback):
                    fallback_engine = fallback
                    break
            if fallback_engine is None:
                self.update_status("❌ Keine TTS-Engine verfügbar")
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: Alle TTS-Engines fehlen")
                return
            logger.info("Gewählte Engine '%s' nicht verfügbar, verwende Fallback '%s'", engine_name, fallback_engine)
            self.tts_manager.set_engine(fallback_engine)
            self.update_status(f"⚠️ Engine '{engine_name}' nicht verfügbar, nutze '{fallback_engine}'")
        if hasattr(self, 'audio_processor') and self.audio_processor is not None:
            try:
                self.audio_processor._pause_transcription_for_tts()
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "Transkriptions-Drosselung aktiviert")
            except Exception as e:
                logger.warning("Konnte Transkriptionen nicht drosseln: %s", e)

        # Status setzen
        self._tts_active = True
        self._update_tts_button_state()
        self.update_status(f"🔊 Lese {source_description} vor...")

        # Callback, der nach Ende/Fehler der TTS aufgerufen wird
        def on_tts_finished(success: bool, message: str) -> None:
            """Garantiert, dass die Drosselung immer aufgehoben wird."""
            self._tts_active = False
            if hasattr(self, 'audio_processor') and self.audio_processor is not None:
                try:
                    self.audio_processor._resume_transcription_after_tts()
                    if DEBUG_LEVEL >= 3:
                        log_debug("tts_gui", "Transkriptions-Drosselung aufgehoben (callback)")
                except Exception as e:
                    logger.warning("Fehler beim Aufheben der Drosselung im Callback: %s", e)
            self._safe_gui_update(self._update_tts_button_state)
            if success:
                self.update_status("✅ Sprachausgabe beendet")
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: Sprachausgabe erfolgreich beendet")
            else:
                self.update_status(f"❌ TTS-Fehler: {message[:50]}")
                if DEBUG_LEVEL >= 3:
                    log_debug("tts_gui", "speak_current_text: TTS-Fehler – %s", message)

        try:
            self.tts_manager.speak(cleaned_text, callback=on_tts_finished)
        except Exception as e:
            # Bei Fehlern im Start sicherstellen, dass die Drosselung aufgehoben wird
            self._tts_active = False
            self._update_tts_button_state()
            if hasattr(self, 'audio_processor') and self.audio_processor is not None:
                try:
                    self.audio_processor._resume_transcription_after_tts()
                except Exception:
                    pass
            logger.error("speak_current_text: Ausnahme beim Starten der TTS: %s", e, exc_info=True)
            self.update_status(f"❌ TTS-Start fehlgeschlagen: {str(e)[:50]}")

    def _get_text_for_tts(self) -> Tuple[str, str]:
        focused = self.root.focus_get()
        if focused == self.transcript_text:
            if self.transcript_text.tag_ranges(tk.SEL):
                return self.transcript_text.get(
                    tk.SEL_FIRST, tk.SEL_LAST
                ), "Selection (Transcript)"
            return self.transcript_text.get("1.0", "end-1c"), "Full transcript"
        elif focused == self.translation_text:
            if self.translation_text.tag_ranges(tk.SEL):
                return self.translation_text.get(
                    tk.SEL_FIRST, tk.SEL_LAST
                ), "Selection (Translation)"
            return self.translation_text.get("1.0", "end-1c"), "Full translation"
        return "", ""

    def _clean_tts_text(self, text: str) -> str:
        """        Bereinigt einen Text für die Sprachausgabe, indem führende
        Zeitstempel und Sprachkürzel entfernt werden.        """
        if not text:
            if DEBUG_LEVEL >= 4:
                log_debug("tts", "_clean_tts_text: Leerer Text – nichts zu bereinigen")
            return ""
        if not isinstance(text, str):
            logger.warning(
                f"_clean_tts_text: Erwartet str, erhielt {type(text).__name__} – konvertiere"
            )
            text = str(text)
        original = text
        original_len = len(original)
        text = re.sub(
            r"^\[\d{2}:\d{2}:\d{2}(?:\.\d{3})?\]\s*\[[A-Za-z]{2,3}\]\s*",
            "",
            text,
            flags=re.MULTILINE,
        )
        text = re.sub(
            r"^\[\d{2}:\d{2}:\d{2}(?:\.\d{3})?\]\s*", "", text, flags=re.MULTILINE
        )
        text = re.sub(r"\s+", " ", text)
        cleaned = text.strip()
        cleaned_len = len(cleaned)
        changed_significantly = abs(original_len - cleaned_len) / max(original_len, 1) > 0.05
        ends_with_punct = cleaned[-1] in ".!?。！？" if cleaned else False
        if DEBUG_LEVEL >= 3 and original != cleaned:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "tts",
                    f"_clean_tts_text: Text bereinigt\n"
                    f"  Länge: {original_len} → {cleaned_len} Zeichen\n"
                    f"  Satzende: {'ja' if ends_with_punct else 'nein'}\n"
                    f"  Signifikant: {'ja' if changed_significantly else 'nein'}\n"
                    f"  Vorher: {original}\n"
                    f"  Nachher: {cleaned}",
                )
            else:
                preview_orig = original[:150] + "…" if original_len > 150 else original
                preview_clean = cleaned[:150] + "…" if cleaned_len > 150 else cleaned
                log_debug(
                    "tts",
                    f"_clean_tts_text: Text bereinigt ({original_len} → {cleaned_len} Zeichen)"
                    f" [signifikant={'ja' if changed_significantly else 'nein'},"
                    f" Satzende={'ja' if ends_with_punct else 'nein'}]\n"
                    f"  Vorher: {preview_orig}\n"
                    f"  Nachher: {preview_clean}",
                )
        elif DEBUG_LEVEL >= 4 and original == cleaned:
            log_debug(
                "tts",
                f"_clean_tts_text: Keine Änderungen ({cleaned_len} Zeichen)\n"
                f"  Text: {cleaned[:200]}{'…' if cleaned_len > 200 else ''}",
            )
        return cleaned

    def _on_tts_finished(self, success: bool, message: str) -> None:
        self._tts_active = False
        self._safe_gui_update(self._update_tts_button_state)
        self.update_status(
            "✅ Speech output finished."
            if success
            else f"❌ Speech output error: {message}"
        )

    def open_volume_popup(self) -> None:
        if self._volume_popup and self._volume_popup.winfo_exists():
            self._volume_popup.lift()
            return
        popup = tk.Toplevel(self.root)
        popup.title("Lautstärke")
        popup.geometry("60x180")
        popup.configure(bg=self.current_theme.BG_PRIMARY)
        popup.transient(self.root)
        popup.grab_set()
        vol_var = tk.DoubleVar(value=self.tts_manager._volume * 100)
        scale = tk.Scale(
            popup,
            from_=100,
            to=0,
            orient=tk.VERTICAL,
            variable=vol_var,
            length=120,
            width=20,
            bg=self.current_theme.BG_PRIMARY,
            fg=self.current_theme.TEXT_PRIMARY,
            troughcolor=self.current_theme.BG_TERTIARY,
        )
        scale.pack(pady=10)
        label = tk.Label(
            popup,
            text=f"{int(vol_var.get())}%",
            bg=self.current_theme.BG_PRIMARY,
            fg=self.current_theme.TEXT_PRIMARY,
        )
        label.pack()

        def update_volume(*args):
            vol = vol_var.get() / 100.0
            self.tts_manager.set_volume(vol)
            label.config(text=f"{int(vol * 100)}%")
            icon = (
                "🔇"
                if vol <= 0.05
                else "🔈"
                if vol <= 0.33
                else "🔉"
                if vol <= 0.66
                else "🔊"
            )
            self.volume_btn.config(text=icon)
        vol_var.trace_add("write", update_volume)
        popup.bind("<FocusOut>", lambda e: popup.destroy())
        self._volume_popup = popup

    @gui_operation_decorator
    def save_tts_as_mp3(self) -> None:
        text, _ = self._get_text_for_tts()
        if not text:
            self.update_status("❌ Kein Text zum Speichern.")
            return
        cleaned = self._clean_tts_text(text)
        if not cleaned:
            self.update_status("❌ Nach Entfernen der Zeitstempel kein Text übrig.")
            return
        base_name = self._get_safe_filename()
        suggested = f"{base_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.mp3"
        filename = filedialog.asksaveasfilename(
            defaultextension=".mp3",
            initialfile=suggested,
            filetypes=[("MP3 Audio", "*.mp3"), ("WAV Audio", "*.wav")],
        )
        if not filename:
            return
        if not self.tts_manager.is_available():
            self.update_status("❌ TTS-Engine nicht verfügbar.")
            return
        self.update_status("🎤 Erstelle Audio-Datei...")
        self.tts_manager.speak_to_file(
            cleaned,
            filename,
            callback=lambda s, m: self.update_status(
                f"✅ {m}" if s else f"❌ Fehler: {m}"
            ),
        )

    def _update_tts_button_state(self) -> None:
        if not hasattr(self, "tts_btn") or not self.tts_btn.winfo_exists():
            return
        if self._tts_active:
            self.tts_btn.config(text="🔊 STOP", bg=self.current_theme.SUCCESS)
            ToolTip(self.tts_btn, "Stop reading")
        else:
            self.tts_btn.config(text="🔊", bg=self.current_theme.BG_TERTIARY)
            ToolTip(self.tts_btn, "Read selected text aloud (TTS)")

    def toggle_vad_fallback(self) -> None:
        new_state = not self.vad_fallback_enabled.get()
        self.vad_fallback_enabled.set(new_state)
        self._update_vad_fallback_button()
        if hasattr(self, "audio_processor"):
            self.audio_processor.set_vad_fallback_enabled(new_state)
        self.update_status(
            f"VAD-Fallback {'aktiviert' if new_state else 'deaktiviert'}"
        )
        self._schedule_settings_save()

    def _schedule_settings_save(self) -> None:
        if self._save_settings_timer is not None:
            try:
                self.root.after_cancel(self._save_settings_timer)
            except (ValueError, tk.TclError):
                pass
        self._save_settings_timer = self._safe_after(500, self._save_settings_impl)

    def _sync_auto_tts_to_processor(self) -> None:
        """
        Übertragt die aktuellen Werte der Auto‑TTS‑Checkboxen
        (Transkription / Übersetzung) in den laufenden AudioProcessor,
        sodass die automatische Sprachausgabe sofort auf Benutzeränderungen
        reagiert.        """
        ap = getattr(self, 'audio_processor', None)
        if ap is None:
            if DEBUG_LEVEL >= 4:
                log_debug("tts_sync", "Kein AudioProcessor – Synchronisation übersprungen.")
            return
        transcript_val = self.auto_tts_transcript_var.get()
        translation_val = self.auto_tts_translation_var.get()
        try:
            lock = getattr(ap, '_engine_lock', None)
            if lock is not None:
                with lock:
                    ap.settings.auto_tts_transcript = transcript_val
                    ap.settings.auto_tts_translation = translation_val
            else:
                ap.settings.auto_tts_transcript = transcript_val
                ap.settings.auto_tts_translation = translation_val
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_sync",
                    "Auto‑TTS synced: transcript=%s, translation=%s",
                    transcript_val,
                    translation_val,
                )
        except AttributeError as e:
            logger.warning(
                "_sync_auto_tts_to_processor: Fehler beim Zugriff auf AudioProcessor‑Einstellungen: %s",
                e,
            )
        except Exception as e:
            logger.error(
                "_sync_auto_tts_to_processor: Unerwarteter Fehler: %s",
                e,
                exc_info=DEBUG_LEVEL >= 3,
            )

    def _on_auto_tts_toggle(self, source: str) -> None:
        """
        Callback für die Auto‑TTS‑Checkboxen.

        Wird vom `WhisperLayoutManager` aufgerufen, wenn der Benutzer
        die automatische Sprachausgabe für Transkription oder Übersetzung
        umschaltet.  Die Methode übernimmt folgende Aufgaben:

        1. Aktualisieren des entsprechenden Flags in ``advanced_settings``.
        2. Persistieren der geänderten Einstellungen (debounced).
        3. Synchronisieren mit dem AudioProcessor, falls verfügbar.
        """
        if source == "transcript":
            self.advanced_settings.auto_tts_transcript = (
                self.auto_tts_transcript_var.get()
            )
        elif source == "translation":
            self.advanced_settings.auto_tts_translation = (
                self.auto_tts_translation_var.get()
            )
        else:
            logger.warning(
                f"_on_auto_tts_toggle: unknown source '{source}' – ignored."
            )
            return

        # Einstellungen debounced speichern (schreibt auch die Änderung
        # sofort in die Datei, sofern der Timer nicht neu gestartet wird).
        self._schedule_settings_save()

        # Den AudioProcessor (falls aktiv) über die neue Einstellung informieren.
        sync_func = getattr(self, "_sync_auto_tts_to_processor", None)
        if sync_func is not None and callable(sync_func):
            try:
                sync_func()
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui",
                        f"Fehler in _sync_auto_tts_to_processor: {e}",
                    )
        else:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "gui",
                    "_sync_auto_tts_to_processor nicht verfügbar.",
                )

    def _save_settings_impl(self) -> None:
        try:
            self.advanced_settings.auto_tts_transcript = (
                self.auto_tts_transcript_var.get()
            )
            self.advanced_settings.auto_tts_translation = (
                self.auto_tts_translation_var.get()
            )
            self.advanced_settings.target_language = self.current_language
            self.advanced_settings.save_to_file()
            self.settings.save_to_file()
        except Exception as e:
            logger.error(f"Fehler beim Speichern der Einstellungen: {e}")
        finally:
            self._save_settings_timer = None

    def _update_vad_fallback_button(self) -> None:
        if hasattr(self, "vad_fallback_btn") and self.vad_fallback_btn.winfo_exists():
            text = "🔁VAD 1" if self.vad_fallback_enabled.get() else "🔁VAD 0"
            self._safe_gui_update(lambda: self.vad_fallback_btn.config(text=text))

    @gui_operation_decorator
    def toggle_live_mode(self) -> None:
        """        Schaltet die Chunk-Dauer zwischen zwei vordefinierten Werten um        """
        if (
            hasattr(self, "_live_mode_toggle_time")
            and time.time() - self._live_mode_toggle_time < 0.5
        ):
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "toggle_live_mode: Debounce – Aufruf ignoriert")
            return
        self._live_mode_toggle_time = time.time()
        if self.is_processing:
            DarkMessageBox.showwarning(
                "Achtung",
                "Der Live‑Modus kann während einer laufenden Transkription nicht geändert werden.\n\n"
                "Bitte stoppen Sie die Verarbeitung zuerst.",
                parent=self.root,
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui", "toggle_live_mode: Abbruch wegen laufender Verarbeitung"
                )
            return
        try:
            current_duration = self.advanced_settings.chunk_duration
        except AttributeError:
            logger.error(
                "advanced_settings nicht verfügbar – Live‑Modus kann nicht umgeschaltet werden"
            )
            return
        DURATION_LOW = 10.0
        DURATION_HIGH = 20.0
        if abs(current_duration - DURATION_LOW) < 0.1:
            new_duration = DURATION_HIGH
        else:
            new_duration = DURATION_LOW
        if DEBUG_LEVEL >= 3:
            log_debug(
                "gui",
                f"toggle_live_mode: Wechsle Chunk-Dauer von {current_duration:.1f}s → {new_duration:.1f}s",
            )
        self.advanced_settings.chunk_duration = new_duration
        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            try:
                self.audio_processor.settings.config.CHUNK_DURATION = new_duration
                if hasattr(self.audio_processor, "_update_chunk_size"):
                    self.audio_processor._update_chunk_size()
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui",
                        f"AudioProcessor synchronisiert: CHUNK_DURATION={new_duration:.1f}s",
                    )
            except AttributeError as e:
                logger.warning(f"Konnte AudioProcessor nicht synchronisieren: {e}")
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui", f"AudioProcessor Synchronisation fehlgeschlagen: {e}"
                    )
        self._update_live_mode_button()
        self.update_status(f"⏱️ Chunk-Dauer auf {new_duration:.0f}s umgestellt")
        self._schedule_settings_save()
        if hasattr(self, "event_bus") and self.event_bus is not None:
            try:
                self.event_bus.emit(
                    "chunk_duration_changed",
                    {
                        "old": current_duration,
                        "new": new_duration,
                    },
                )
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"Event-Bus Fehler: {e}")
        if DEBUG_LEVEL >= 2:
            log_debug("gui", f"toggle_live_mode erfolgreich: {new_duration:.1f}s")

    @gui_operation_decorator
    def _update_live_mode_button(self) -> None:
        """        Aktualisiert die Beschriftung des Live‑Mode‑Buttons mit der aktuellen
        Chunk‑Dauer. Thread‑sicher durch Bindung des Werts an das Lambda.        """
        if not hasattr(self, "live_mode_btn") or self.live_mode_btn is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui", "_update_live_mode_button: live_mode_btn nicht vorhanden"
                )
            return
        try:
            if not self.live_mode_btn.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui",
                        "_update_live_mode_button: live_mode_btn existiert nicht mehr",
                    )
                return
        except tk.TclError:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", "_update_live_mode_button: TclError bei winfo_exists")
            return
        try:
            duration = self.advanced_settings.chunk_duration
        except AttributeError:
            duration = 20.0
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "gui",
                    "_update_live_mode_button: advanced_settings nicht verfügbar, verwende 20.0s",
                )
        min_dur = getattr(self.advanced_settings.config, "MIN_CHUNK_DURATION", 2.0)
        max_dur = getattr(self.advanced_settings.config, "MAX_CHUNK_DURATION", 30.0)
        if not (min_dur <= duration <= max_dur):
            old = duration
            duration = max(min_dur, min(duration, max_dur))
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    f"_update_live_mode_button: chunk_duration {old:.1f}s außerhalb "
                    f"[{min_dur}, {max_dur}], geklemmt auf {duration:.1f}s",
                )
        if DEBUG_LEVEL >= 3:
            if not hasattr(self, "_last_displayed_chunk_duration"):
                self._last_displayed_chunk_duration = None
            if self._last_displayed_chunk_duration != duration:
                log_debug(
                    "gui",
                    f"_update_live_mode_button: Anzeige aktualisiert "
                    f"{self._last_displayed_chunk_duration} → {duration:.1f}s",
                )
                self._last_displayed_chunk_duration = duration
        self._safe_gui_update(
            lambda d=duration: self.live_mode_btn.config(text=f"⏱️ {d:.0f}s")
        )

    def _set_start_button_loading_state(self, loading: bool) -> None:
        """
        Deaktiviert den Start‑Button, solange ein KI‑Modell asynchron geladen
        wird, und stellt den normalen Zustand wieder her, sobald der Ladevorgang
        beendet ist (unabhängig vom Erfolg).

        Der Button wird bewusst nicht direkt vom Controller gesteuert, sondern
        über den Event‑Bus synchronisiert, damit auch abgebrochene oder
        fehlgeschlagene Ladevorgänge garantiert den Button wieder freigeben.

        Args:
            loading: True, wenn der Button deaktiviert werden soll
                     (Ladevorgang aktiv), False, um ihn wieder zu aktivieren.
        """
        btn = getattr(self, "start_button", None)
        if btn is None or not btn.winfo_exists():
            return

        if loading:
            btn.config(state="disabled", text="⏳ Lade Modell …")
            ToolTip(btn, "Das KI‑Modell wird gerade geladen – bitte warten.")
        else:
            btn.config(state="normal", text="🚀 START")
            ToolTip(btn, "Transkription und Übersetzung starten")

    def _schedule_tts(
        self,
        text: str,
        source: str,
        audio_processor: Optional[Any] = None,
    ) -> None:
        """
        Plant eine automatische TTS‑Ausgabe für einen transkribierten oder
        übersetzten Satz.
        """
        # ── 1. Dispose‑ und Shutdown‑Prüfung ───────────────────────
        if getattr(self, "_disposed", False) or self.is_shutting_down():
            return

        # ── 2. TTS‑Manager verfügbar? ──────────────────────────────
        tts = getattr(self, "tts_manager", None)
        if tts is None:
            return

        # ── 3. Quelle validieren ───────────────────────────────────
        if source not in ("transcript", "translation"):
            return

        # ── 4. Einstellungen ermitteln (AudioProcessor bevorzugt) ──
        ap = audio_processor
        if ap is None:
            ap = getattr(self, "audio_processor", None)
        if ap is not None and hasattr(ap, "settings") and ap.settings is not None:
            adv = ap.settings
        else:
            adv = getattr(self, "advanced_settings", None)
        if adv is None:
            return

        # ── 5. Auto‑TTS‑Flag prüfen ────────────────────────────────
        if source == "transcript" and not getattr(adv, "auto_tts_transcript", False):
            return
        if source == "translation" and not getattr(adv, "auto_tts_translation", False):
            return

        # ── 6. Text validieren und ggf. kürzen ─────────────────────
        if not text or not isinstance(text, str) or not text.strip():
            return
        MAX_TTS_LENGTH = 2000
        if len(text) > MAX_TTS_LENGTH:
            text = text[:MAX_TTS_LENGTH] + " […]"
        corrected_text = text.strip()
        if not corrected_text:
            return

        # ── 7. Duplikaterkennung (gleicher oder sehr ähnlicher Text) ──
        with self._tts_lock:
            if not hasattr(self, "_last_tts_texts"):
                self._last_tts_texts: Deque[str] = deque(maxlen=5)
            # Prüfe ob exakt gleich oder nur Leerzeichen anders
            normalized = " ".join(corrected_text.split()).lower()
            if normalized in self._last_tts_texts:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "tts_auto",
                        "Text bereits in TTS‑Historie, überspringe: '%s'",
                        corrected_text[:50],
                    )
                return
            # Bei sehr kurzen Texten (< 5 Wörtern) nur exakte Duplikate
            if len(corrected_text.split()) < 5:
                pass  # exakte Prüfung reicht
            else:
                # Ähnlichkeitsprüfung mit Levenshtein / rapidfuzz
                if not hasattr(self, "_fuzz"):
                    try:
                        from rapidfuzz import fuzz as _fuzz
                        self._fuzz = _fuzz
                    except ImportError:
                        self._fuzz = None
                if self._fuzz is not None:
                    for existing in self._last_tts_texts:
                        if self._fuzz.ratio(normalized, existing) > 90:
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "tts_auto",
                                    "Text zu ähnlich zu '%s', überspringe: '%s'",
                                    existing[:50],
                                    corrected_text[:50],
                                )
                            return

        # ── 8. Engine‑Fallback, falls gewünschte Engine nicht startbereit ist
        engine_name = getattr(adv, "tts_engine", "piper")
        if not tts.is_available(engine_name):
            fallback_engine = None
            for candidate in ("piper", "pyttsx3", "espeak"):
                if tts.is_available(candidate):
                    fallback_engine = candidate
                    break
            if fallback_engine is None:
                return
            tts.set_engine(fallback_engine)

        # ── 9. Pause‑ / Resume‑Funktionen vom AudioProcessor holen ──
        pause_func = getattr(ap, "_pause_transcription_for_tts", None) if ap else None
        resume_func = getattr(ap, "_resume_transcription_after_tts", None) if ap else None

        # ── 10. Watchdog‑Timer (verhindert Dauer‑Drosselung) ────────
        WATCHDOG_SECONDS = 60.0
        watchdog_timer: Optional[threading.Timer] = None

        def _execute_resume() -> None:
            """Garantiert, dass die Drosselung **einmal** aufgehoben wird."""
            if watchdog_timer is not None:
                watchdog_timer.cancel()
            if callable(resume_func):
                try:
                    resume_func()
                except Exception as exc:
                    logger.error(
                        "Fehler beim Wiederaufnehmen der Transkription "
                        "(Watchdog/Completion): %s",
                        exc,
                    )

        # ── 11. Completion‑Callback definieren ────────────────────
        # Dieser wird erst nach der vollständigen Synthese ausgeführt.
        def _on_tts_completion(success: bool, message: str) -> None:
            """Wird nach der Sprachausgabe aufgerufen (Erfolg oder Fehler)."""
            _execute_resume()
            # Text in die Historie aufnehmen
            with self._tts_lock:
                if hasattr(self, "_last_tts_texts"):
                    self._last_tts_texts.append(normalized)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_auto",
                    "TTS completion: success=%s, msg=%s, source=%s",
                    success,
                    message[:80] if message else "",
                    source,
                )

        # ── 12. Transkription drosseln (nur wenn Funktion vorhanden) ─
        if callable(pause_func):
            try:
                pause_func()
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "tts_drossel",
                        "Transkription vor TTS pausiert (source=%s).",
                        source,
                    )
            except Exception as exc:
                logger.error("Fehler beim Pausieren der Transkription: %s", exc)
                # Wenn Pause fehlschlägt, ist es sicherer, keinen Resume
                # später zu versuchen → Watchdog gar nicht erst starten.
                return

        # ── 13. Watchdog starten (als Fallback für hängende Synthese) ─
        watchdog_timer = threading.Timer(WATCHDOG_SECONDS, _execute_resume)
        watchdog_timer.daemon = True
        watchdog_timer.start()

        # ── 14. An die TTS‑Engine übergeben ─────────────────────────
        try:
            tts.speak_queued(
                corrected_text,
                callback=None,                    # wird für Auto‑TTS nicht benötigt
                completion_callback=_on_tts_completion,
                block_timeout=0.5,
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_auto",
                    "Text in TTS‑Queue eingereiht (source=%s, len=%d).",
                    source,
                    len(corrected_text),
                )
        except Exception as exc:
            logger.exception(
                "_schedule_tts: Fehler beim Einreihen in die TTS‑Queue: %s",
                exc,
            )
            # Im Fehlerfall die Drosselung SOFORT aufheben.
            _execute_resume()

    def _execute_tts(self, source: str) -> None:
        """
        Verarbeitet eine anstehende TTS‑Anforderung aus dem internen
        Puffer und leitet sie an die moderne ``_schedule_tts``‑Logik
        weiter.
        """
        with self._tts_lock:
            self._tts_timer = None

        if source == "transcript":
            with self._tts_lock:
                text = self._pending_tts_transcript
                self._pending_tts_transcript = ""
        else:  # "translation"
            with self._tts_lock:
                text = self._pending_tts_translation
                self._pending_tts_translation = ""

        if not text:
            return

        schedule_func = getattr(self, "_schedule_tts", None)
        if schedule_func is not None and callable(schedule_func):
            schedule_func(text, source)
        else:
            tts = getattr(self, "tts_manager", None)
            if tts is not None and tts.is_available():
                try:
                    tts.speak_queued(text, callback=lambda s, m: None)
                except Exception as exc:
                    logger.error(
                        "_execute_tts (Fallback): speak_queued fehlgeschlagen: %s",
                        exc,
                    )

    @gui_operation_decorator
    def correct_transcript_with_ollama(self) -> None:
        """        Exzellente, kontextbewusste Transkript‑Korrektur per Ollama.        """
        if not hasattr(self, "transcript_text") or not self.transcript_text.winfo_exists():
            return
        text = self.transcript_text.get("1.0", "end-1c").strip()
        if not text:
            DarkMessageBox.showinfo("Hinweis", "Kein Text zum Korrigieren vorhanden.", self.root)
            return
        if not OLLAMA_AVAILABLE:
            DarkMessageBox.showerror("Fehler", "Ollama nicht verfügbar (requests fehlt).", self.root)
            return
        test_summarizer = OllamaSummarizer(
            self,
            model=self.advanced_settings.ollama_model,
            host=self.advanced_settings.ollama_host,
            timeout=10,
        )
        if not test_summarizer.is_server_reachable():
            DarkMessageBox.showerror(
                "Fehler",
                "Ollama-Server läuft nicht oder ist nicht erreichbar.\n"
                "Bitte starte 'ollama serve' und versuche es erneut.",
                self.root,
            )
            test_summarizer.dispose()
            return
        test_summarizer.dispose()
        stream_title = ""
        uploader = ""
        if self.current_stream_info:
            stream_title = self.current_stream_info.title or ""
            uploader = self.current_stream_info.uploader or ""
        elif hasattr(self, "last_completed_stream_info") and self.last_completed_stream_info:
            stream_title = self.last_completed_stream_info.title or ""
            uploader = self.last_completed_stream_info.uploader or ""
        MAX_CHARS_PER_CHUNK = 3000
        paragraphs = text.split("\n")
        chunks: List[str] = []
        current = ""
        for para in paragraphs:
            para = para.strip()
            if not para:
                continue
            if current and len(current) + len(para) + 2 > MAX_CHARS_PER_CHUNK:
                chunks.append(current)
                current = para
            else:
                if current:
                    current += "\n\n" + para
                else:
                    current = para
            while len(current) > MAX_CHARS_PER_CHUNK:
                cut = current.rfind(". ", 0, MAX_CHARS_PER_CHUNK)
                if cut == -1:
                    cut = current.rfind(" ", 0, MAX_CHARS_PER_CHUNK)
                if cut == -1:
                    cut = MAX_CHARS_PER_CHUNK
                chunks.append(current[: cut + 1].strip())
                current = current[cut + 1 :].strip()
        if current:
            chunks.append(current)
        if not chunks:
            return
        total_chunks = len(chunks)
        log_debug("ollama", "Transkript in %d Chunk(s) aufgeteilt (max %d Zeichen)", total_chunks, MAX_CHARS_PER_CHUNK)
        context_lines = []
        if stream_title:
            context_lines.append(f"Videotitel: '{stream_title}'")
        if uploader:
            context_lines.append(f"Kanal/Uploader: '{uploader}'")
        context_block = "\n".join(context_lines) if context_lines else ""
        system_prompt = (
            "Du bist ein professioneller Transkript‑Editor für Deutsch. "
            "Deine Aufgabe ist es, ein automatisch erstelltes Transkript zu bereinigen.\n"
            "Korrigiere:\n"
            "- Eigennamen (Personen, Orte, Produkte), besonders wenn der Kontext darauf hinweist.\n"
            "- Satzzeichen, Groß‑/Kleinschreibung.\n"
            "- Typische Fehler der Spracherkennung (fehlende Wörter, falsche Wortgrenzen).\n"
            "Verändere NICHT den Sinn oder die Fakten. "
            "Gib NUR das korrigierte Transkript zurück, ohne Erklärungen."
        )

        def make_prompt(chunk_text: str) -> str:
            parts = [system_prompt]
            if context_block:
                parts.append(f"\n\n{context_block}")
            parts.append(f"\n\nOriginaltext:\n{chunk_text}")
            return "\n".join(parts)
        progress_ctrl = DarkMessageBox.show_progress(
            "Transkript korrigieren",
            f"Verarbeite {total_chunks} Abschnitt(e) mit Ollama...",
            parent=self.root,
            indeterminate=False,
        )
        if progress_ctrl is None or not hasattr(progress_ctrl, "progress"):
            DarkMessageBox.showerror("Fehler", "Konnte Fortschrittsdialog nicht öffnen.", self.root)
            return
        corrected_chunks: List[str] = []
        errors_count = 0

        def worker() -> None:
            nonlocal errors_count
            try:
                for idx, chunk in enumerate(chunks):
                    if progress_ctrl.is_closed():
                        break
                    prompt = make_prompt(chunk)
                    summarizer = OllamaSummarizer(
                        self,
                        model=self.advanced_settings.ollama_model,
                        host=self.advanced_settings.ollama_host,
                        timeout=120,
                    )
                    result = summarizer.summarize_sync(
                        text=chunk,
                        prompt=prompt,
                        temperature=0.1,
                        # timeout=120,  ← ENTFERNT (Parameter existiert nicht)
                    )
                    summarizer.dispose()
                    if result and result.strip():
                        corrected_chunks.append(result.strip())
                    else:
                        corrected_chunks.append(chunk)
                        errors_count += 1
                        log_debug(
                            "ollama",
                            "Chunk %d/%d: Keine Korrektur erhalten – verwende Original.",
                            idx + 1,
                            total_chunks,
                        )
                    progress = int((idx + 1) / total_chunks * 100)
                    self.root.after(0, lambda p=progress: progress_ctrl.progress.config(value=p))
                    self.root.after(
                        0,
                        lambda i=idx + 1, t=total_chunks: progress_ctrl.update_message(
                            f"Abschnitt {i}/{t} korrigiert"
                        ),
                    )
                if corrected_chunks:
                    final_text = "\n\n".join(corrected_chunks)
                    self.root.after(0, lambda t=final_text: self._insert_corrected_text(t))
                    status = (
                        f"✅ Transkript korrigiert ({total_chunks} Abschnitt"
                        f"{'e' if total_chunks != 1 else ''})"
                    )
                    if errors_count > 0:
                        status += f" – {errors_count} Fallback(s) auf Original"
                    self.root.after(0, lambda s=status: self.update_status(s))

            except Exception as exc:
                error_msg = f"{type(exc).__name__}: {exc}"[:200]
                logger.exception("Fehler in der Ollama‑Korrektur: %s", error_msg)
                self.root.after(
                    0,
                    lambda msg=error_msg: self.update_status(
                        f"❌ Korrektur fehlgeschlagen: {msg}"
                    ),
                )
            finally:
                ctrl = progress_ctrl
                if ctrl is not None and not ctrl.is_closed():
                    self.root.after(0, ctrl.close)
        threading.Thread(target=worker, daemon=True, name="OllamaCorrector").start()

    def _insert_corrected_text(self, new_text: str) -> None:
        """Ersetzt den Inhalt des Transkript-Widgets mit dem korrigierten Text."""
        try:
            widget = getattr(self, "transcript_text", None)
            if widget and widget.winfo_exists():
                widget.delete("1.0", "end")
                widget.insert("1.0", new_text)
                log_debug("ollama", "Korrigiertes Transkript in GUI eingefügt")
        except Exception as exc:
            logger.error("Fehler beim Einfügen des korrigierten Textes: %s", exc)

    @gui_operation_decorator
    def _update_transcript_with_correction(self, corrected_text: str) -> None:
        if self.transcript_text and self.transcript_text.winfo_exists():
            self.transcript_text.delete("1.0", "end")
            self.transcript_text.insert("1.0", corrected_text)
            self.update_status("✅ Transkription korrigiert")

    def _show_cookie_notice_dialog(self) -> None:
        result = DarkMessageBox.askyesno(
            "Datenschutzhinweis",
            "Dragon Whisperer kann auf gespeicherte Browser-Cookies zugreifen.\n\nMöchten Sie die Nutzung von Browser-Cookies erlauben?",
            parent=self.root,
        )
        self.settings.use_browser_cookies = result
        self.settings.cookies_notice_shown = True
        self.settings.save_to_file()
        if hasattr(self, "stream_manager"):
            self.stream_manager.use_browser_cookies = result
        if hasattr(self, "stream_info_extractor"):
            self.stream_info_extractor.use_browser_cookies = result

    def show_advanced_settings(self) -> None:
        AdvancedSettingsDialog(self.root, self)

    def show_translation_dialog(self) -> None:
        engine = self._create_temporary_translation_engine(
            self.advanced_settings.translation_engine, self.current_language
        )
        if engine is None:
            DarkMessageBox.showerror(
                "Fehler", "Übersetzungs-Engine nicht verfügbar.", self.root
            )
