def get_advanced_settings() -> "AdvancedSettings":
    """    Gibt die aktuellen erweiterten Einstellungen zurück.    """
    try:
        return AdvancedSettings.load_from_file()
    except Exception as e:
        logger.critical(f"❌ Konnte AdvancedSettings nicht laden: {e}", exc_info=True)
        try:
            return AdvancedSettings()
        except Exception:
            raise RuntimeError(
                "AdvancedSettings sind nicht verfügbar – Programm kann nicht fortgesetzt werden."
            ) from e

_original_console_mode: Optional[int] = None
_original_codepage: Optional[int] = None


def _save_console_state() -> None:
    global _original_console_mode, _original_codepage
    if not IS_WINDOWS:
        return
    try:
        import ctypes

        kernel32 = ctypes.windll.kernel32
        handle = kernel32.GetStdHandle(-11)
        mode = ctypes.c_ulong()
        if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
            _original_console_mode = mode.value
        _original_codepage = kernel32.GetConsoleOutputCP()
    except Exception:
        pass


def _restore_console_state() -> None:
    """Stellt die ursprünglichen Konsolen-/Terminal-Einstellungen wieder her."""
    if IS_WINDOWS:
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            if _original_console_mode is not None:
                handle = kernel32.GetStdHandle(-11)
                kernel32.SetConsoleMode(handle, _original_console_mode)
            if _original_codepage is not None:
                kernel32.SetConsoleOutputCP(_original_codepage)
                kernel32.SetConsoleCP(_original_codepage)
        except Exception as e:
            logger.debug(f"Fehler beim Wiederherstellen der Windows-Konsole: {e}")
    else:
        try:
            subprocess.run(["stty", "sane"], check=False, timeout=1)
        except Exception as e:
            logger.debug(f"Fehler beim Wiederherstellen des Terminals: {e}")

_save_console_state()
atexit.register(_restore_console_state)

def _setup_windows_console() -> bool:
    """
    Konfiguriert die Windows‑Konsole für UTF‑8‑Ausgabe und aktiviert die
    Verarbeitung virtueller Terminalsequenzen (ANSI‑Escape‑Codes).

    Diese Funktion war ursprünglich vor der Einführung der umfassenderen
    ``PlatformUtils.setup_platform_environment()`` die zentrale Stelle für
    die Konsoleninitialisierung.  Derzeit wird sie **nicht mehr aufgerufen**
    und stellt reinen Dead‑Code dar.  Sie verbleibt als dokumentierte
    Alternative und als Fallback für künftige Konsolen‑Erweiterungen.

    Verbesserungen gegenüber der ursprünglichen Version:
        * Schutz vor mehrfachem Aufruf (idempotent).
        * Verwendung von ``ctypes`` nur innerhalb eines ``try``‑Blocks,
          um ImportError zu vermeiden.
        * UTF‑8‑Codepage wird nur gesetzt, wenn sie nicht bereits aktiv ist.
        * Virtuelle Terminalverarbeitung wird nur aktiviert, wenn der Handle
          erfolgreich abgerufen werden kann.
        * Alle Exceptions werden protokolliert, aber nicht propagiert.
        * Die Konsolenausgabe (stdout) wird **nicht** mehr durch einen
          ``codecs.getwriter`` ersetzt – diese Technik ist fehleranfällig
          und mittlerweile durch die gesetzten Codepages obsolet.

    Returns:
        ``True`` wenn die Konsole erfolgreich konfiguriert wurde,
        ``False`` wenn ein Fehler auftrat oder die Plattform nicht
        Windows ist.
    """
    if not IS_WINDOWS:
        if DEBUG_LEVEL >= 3:
            log_debug("console", "Kein Windows – überspringe Konsolen‑Setup.")
        return False

    # Idempotenz sicherstellen – Konfiguration nur einmal pro Prozess
    if getattr(_setup_windows_console, "_configured", False):
        if DEBUG_LEVEL >= 4:
            log_debug("console", "Konsolen‑Setup bereits durchgeführt – überspringe.")
        return True

    success = True
    try:
        # ------------------------------------------------------------------
        # 1. UTF‑8 als Standard‑Codepage für Ein‑ und Ausgabe erzwingen
        # ------------------------------------------------------------------
        import ctypes
        kernel32 = ctypes.windll.kernel32

        current_output_cp = kernel32.GetConsoleOutputCP()
        current_input_cp = kernel32.GetConsoleCP()

        if current_output_cp != 65001:
            kernel32.SetConsoleOutputCP(65001)
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "console",
                    "SetConsoleOutputCP: %d → 65001 (UTF‑8)",
                    current_output_cp,
                )
        else:
            if DEBUG_LEVEL >= 4:
                log_debug("console", "ConsoleOutputCP bereits 65001.")

        if current_input_cp != 65001:
            kernel32.SetConsoleCP(65001)
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "console",
                    "SetConsoleCP: %d → 65001 (UTF‑8)",
                    current_input_cp,
                )
        else:
            if DEBUG_LEVEL >= 4:
                log_debug("console", "ConsoleCP bereits 65001.")

        # ------------------------------------------------------------------
        # 2. Virtuelle Terminal‑Verarbeitung aktivieren (ANSI‑Escapes)
        # ------------------------------------------------------------------
        STD_OUTPUT_HANDLE = -11
        handle = kernel32.GetStdHandle(STD_OUTPUT_HANDLE)
        if handle is None or handle == ctypes.c_void_p(-1).value:
            logger.warning(
                "Konsolen‑Handle (stdout) konnte nicht abgerufen werden – "
                "virtuelle Terminal‑Verarbeitung wird nicht aktiviert."
            )
        else:
            mode = ctypes.c_ulong()
            if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
                if not (mode.value & ENABLE_VIRTUAL_TERMINAL_PROCESSING):
                    new_mode = mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING
                    kernel32.SetConsoleMode(handle, new_mode)
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "console",
                            "Virtuelle Terminal‑Verarbeitung aktiviert "
                            "(mode: 0x%x → 0x%x).",
                            mode.value,
                            new_mode,
                        )
                else:
                    if DEBUG_LEVEL >= 4:
                        log_debug("console", "Virtuelle Terminal‑Verarbeitung bereits aktiv.")
            else:
                logger.warning("GetConsoleMode fehlgeschlagen – Terminal‑Modus unverändert.")

    except AttributeError as e:
        logger.debug("ctypes‑Attribute nicht gefunden – wahrscheinlich kein Windows: %s", e)
        success = False
    except Exception as e:
        logger.warning("Konsolen‑Setup teilweise fehlgeschlagen: %s", e)
        if DEBUG_LEVEL >= 3:
            log_exception("console", "_setup_windows_console", e, level="debug")
        success = False

    # Idempotenz‑Flag setzen, unabhängig vom Erfolg
    _setup_windows_console._configured = True
    return success


def check_platform_compatibility() -> List[str]:
    issues: List[str] = []
    if sys.version_info < (3, 8):
        issues.append(
            f"Python 3.8+ required (you have {sys.version_info.major}.{sys.version_info.minor})"
        )
    if IS_WINDOWS:
        try:
            import platform

            win_ver = platform.version()
            major_ver = int(win_ver.split(".")[0]) if "." in win_ver else 0
            if major_ver < 10:
                issues.append("Windows 10+ recommended for best experience")
        except Exception:
            pass
    return issues

