def _run_system_check() -> int:
    issues = check_platform_compatibility()
    print("🔍 Dragon Whisperer - System Compatibility Check")
    print("=" * 50)
    if issues:
        print("⚠️  Issues found:")
        for issue in issues:
            print(f"  • {issue}")
    else:
        print("✅ No compatibility issues")

    print("\n📦 Dependency Check:")
    print(f"  FFmpeg:        {'✅' if shutil.which('ffmpeg') else '❌'}")
    print(f"  yt-dlp:        {'✅' if shutil.which('yt-dlp') else '❌'}")
    print(f"  Tkinter:       {'✅' if GUI_AVAILABLE else '❌'}")
    print(f"  faster-whisper:{'✅' if WHISPER_AVAILABLE else '❌'}")
    print(f"  NumPy:         {'✅' if NUMPY_AVAILABLE else '❌'}")
    print(f"  PyTorch:       {'✅' if TORCH_AVAILABLE else '❌'}")
    print(f"  deep-translator:{'✅' if TRANSLATOR_AVAILABLE else '❌'}")
    print(f"  SciPy:         {'✅' if SCIPY_AVAILABLE else '❌'}")
    print(f"  psutil:        {'✅' if 'psutil' in sys.modules else '❌'}")
    print("\n💻 System Info:")
    print(f"  Platform: {SYSTEM}")
    print(f"  Architecture: {'ARM' if IS_ARM else 'x86'}")
    print(f"  Python: {sys.version.split()[0]}")
    if IS_WINDOWS:
        try:
            import platform

            print(f"  Windows: {platform.version()}")
        except Exception:
            pass
    return 0 if not issues else 1


def _show_user_error(message: str) -> None:
    if IS_WINDOWS and not sys.stdin.isatty():
        try:
            import ctypes

            ctypes.windll.user32.MessageBoxW(
                0,
                f"Dragon Whisperer - Setup Required\n\n{message}\n\n"
                "Please install missing components and try again.",
                "Setup Error",
                0x10,
            )
        except Exception:
            pass
    else:
        if "Tkinter" in message:
            print("\n💡 INSTALLATION HELP:")
            print("  pip install tk")
        elif "FFmpeg" in message:
            print("\n💡 INSTALLATION HELP:")
            if IS_WINDOWS:
                print("  Download from: https://ffmpeg.org/download.html")
            elif IS_MACOS:
                print("  brew install ffmpeg")
            else:
                print("  sudo apt install ffmpeg")
        else:
            print(f"\n❌ {message}")

def _fatal_error(message: str, title: str = "Fehler") -> None:
    """Gibt eine fatale Fehlermeldung aus.    """
    logger.critical("%s: %s", title, message)
    if len(message) > 2000:
        message = message[:1997] + "..."
    if GUI_AVAILABLE:
        try:
            import tkinter.messagebox as mb
            root = None
            if tk._default_root is not None and tk._default_root.winfo_exists():
                root = tk._default_root
            if root is None:
                tmp_root = tk.Tk()
                tmp_root.withdraw()
                mb.showerror(title, message, parent=tmp_root)
                tmp_root.destroy()
            else:
                mb.showerror(title, message, parent=root)
            return
        except Exception as e:
            logger.debug("Tkinter‑MessageBox fehlgeschlagen: %s", e)
    if IS_WINDOWS:
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(
                0,
                message,
                title,
                0x10,
            )
            return
        except Exception as e:
            logger.debug("Windows‑MessageBox fehlgeschlagen: %s", e)
    print(
        f"\n{'=' * 60}\n{title}\n{'=' * 60}\n{message}\n{'=' * 60}",
        file=sys.stderr,
    )

def print_system_info_debug3() -> None:
    """
    Gibt detaillierte Systeminformationen aus – ausschliesslich über die
    sichere Druckfunktion `_safe_print`, sodass die Ausgabe auch auf
    Windows‑Konsolen ohne vollständige Unicode‑Unterstützung stabil
    funktioniert.
    """
    import platform

    _safe_print("\n" + "=" * 60)
    _safe_print("*** DEBUG LEVEL 3 - SYSTEM INFORMATION ***")
    _safe_print("=" * 60)
    _safe_print(f"Platform: {platform.platform()}")
    _safe_print(f"Python: {sys.version}")
    _safe_print(f"CPU count: {os.cpu_count()}")

    try:
        import resource
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        _safe_print(f"RLIMIT_NOFILE: soft={soft}, hard={hard}")
    except Exception:
        pass

    _safe_print("\n📦 Environment variables set by script:")
    for key in os.environ:
        if key.startswith(("FFMPEG_", "TORCH_", "PYTORCH_", "AV_", "OPENCV_")):
            _safe_print(f"  {key}={os.environ[key]}")

    _safe_print("\n📚 Library versions:")
    libs = [
        ("torch", TORCH_AVAILABLE),
        ("faster_whisper", FASTER_WHISPER_AVAILABLE),
        ("whisper", OPENAI_WHISPER_AVAILABLE),
        ("numpy", NUMPY_AVAILABLE),
        ("scipy", SCIPY_AVAILABLE),
        ("psutil", importlib.util.find_spec("psutil") is not None),
        ("requests", OLLAMA_AVAILABLE),
        ("deep_translator", TRANSLATOR_AVAILABLE),
        ("pynvml", importlib.util.find_spec("pynvml") is not None),
    ]
    for name, avail in libs:
        if avail:
            try:
                mod = __import__(name)
                ver = getattr(mod, "__version__", "unknown")
                _safe_print(f"  {name}: {ver}")
            except Exception:
                _safe_print(f"  {name}: available (version unknown)")
        else:
            _safe_print(f"  {name}: not available")

    _safe_print("\n🎮 GPU info:")
    if TORCH_AVAILABLE:
        torch = FastLazyLoader.load("torch")
        if torch.cuda.is_available():
            _safe_print(f"  CUDA available: {torch.version.cuda}")
            _safe_print(f"  Device: {torch.cuda.get_device_name(0)}")
            _safe_print(
                f"  Total VRAM: "
                f"{torch.cuda.get_device_properties(0).total_memory / 1024**3:.2f} GB"
            )
        else:
            _safe_print("  CUDA not available")
    else:
        _safe_print("  PyTorch not installed")
    _safe_print("=" * 60 + "\n")

def global_exception_handler(exc_type, exc_value, exc_traceback):
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
        return
    logger.critical(
        "Unhandled exception in main thread",
        exc_info=(exc_type, exc_value, exc_traceback),
    )
    try:
        import tkinter.messagebox as mb
        mb.showerror(
            "Dragon Whisperer - Unerwarteter Fehler",
            f"Ein unerwarteter Fehler ist aufgetreten:\n\n{exc_value}\n\n"
            "Details in der Konsole.",
        )
    except Exception:
        pass
    sys.__excepthook__(exc_type, exc_value, exc_traceback)

def thread_exception_handler(args):
    logger.critical(
        f"Unhandled exception in thread {args.thread.name}: {args.exc_value}",
        exc_info=(args.exc_type, args.exc_value, args.exc_traceback),
    )

sys.excepthook = global_exception_handler
threading.excepthook = thread_exception_handler


def configure_logging(
    debug_level: int, debug_components: List[str], quiet: bool
) -> None:
    """    Konfiguriert das Logging basierend auf Debug-Level und Quiet-Modus.    """
    if quiet:
        log_level = logging.ERROR
    elif debug_level >= 1:
        log_level = logging.DEBUG
    else:
        log_level = logging.WARNING
    logging.basicConfig(
        level=log_level,
        format="[%(asctime)s.%(msecs)03d] [%(levelname)s] %(message)s",
        datefmt="%H:%M:%S",
    )
    dragon_logger = logging.getLogger("dragon")
    dragon_logger.setLevel(log_level)
    level_ext = logging.DEBUG if debug_level >= 3 else logging.WARNING
    for lib in ["huggingface_hub", "faster_whisper", "httpx", "urllib3", "httpcore"]:
        logging.getLogger(lib).setLevel(level_ext)

    class DebugFilter(logging.Filter):
        def filter(self, record):
            if debug_level >= 3:
                return True
            component = getattr(record, "component", None)
            if component and component in debug_components:
                return True
            return record.levelno >= logging.WARNING
    debug_filter = DebugFilter()
    dragon_logger.addFilter(debug_filter)
    logging.getLogger().addFilter(debug_filter)


