    class TestPlatformUtils(unittest.TestCase):
        def test_validate_url_http(self):
            valid, msg = PlatformUtils.validate_url(
                "https://www.youtube.com/watch?v=abc"
            )
            self.assertTrue(valid)
            self.assertEqual(msg, "ok")

        def test_validate_url_invalid_chars(self):
            valid, msg = PlatformUtils.validate_url("https://example.com/<>")
            self.assertFalse(valid)
            self.assertIn("nicht erlaubte Zeichen", msg)

        def test_validate_file_path(self):
            with tempfile.NamedTemporaryFile(delete=False) as tmp:
                tmp.write(b"dummy")
                tmp.flush()
                url = f"file://{tmp.name}"
                valid, path = PlatformUtils.validate_file_path(url)
                self.assertTrue(valid)
                self.assertEqual(path, os.path.realpath(tmp.name))
                os.unlink(tmp.name)

