def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="🐉 Dragon Whisperer - Livestream Transcription & Translation",
        epilog="For more information, visit: https://github.com/your-repo/dragon-whisperer",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "-q", "--quiet", action="store_true", help="Suppress all output except errors"
    )
    parser.add_argument(
        "--debug",
        action="store",
        nargs="?",
        const="1",
        default="0",
        help="Enable debug output. Optional level (1-3) or component name(s)",
    )
    parser.add_argument(
        "--check", action="store_true", help="Run system compatibility check and exit"
    )
    parser.add_argument(
        "--test", action="store_true", help="Run internal unit tests and exit"
    )
    parser.add_argument(
        "--version", "-v", action="store_true", help="Show version information and exit"
    )
    parser.add_argument(
        "--headless",
        action="store_true",
        help="Run in headless mode (no GUI, console output only)",
    )
    parser.add_argument(
        "--profile", metavar="NAME", help="Load a custom settings profile"
    )
    parser.add_argument(
        "--url",
        metavar="URL",
        help="Start processing the given URL immediately (implies --headless)",
    )
    parser.add_argument(
        "--model", help="Whisper model to use (e.g. 'large-v3', 'medium')"
    )
    parser.add_argument(
        "--language", help="Target language for translation (e.g. 'de', 'en')"
    )
    parser.add_argument(
        "--sysinfo",
        action="store_true",
        help="Print detailed system information and exit (useful for bug reports)",
    )
    return parser.parse_args()

def _safe_print(*args: Any, **kwargs: Any) -> None:
    """
    Gibt Text auf der Konsole aus und fängt UnicodeEncodeError ab, die
    unter Windows mit Codepage 1252 auftreten können, wenn das Terminal
    keine Emojis oder andere SMP‑Zeichen unterstützt.

    Die Funktion verwendet einen mehrstufigen Fallback:
    1) Normales ``print()``.
    2) Kodierung aller String‑Argumente mit ``errors='replace'``.
    3) Reduktion auf reines ASCII.
    4) Notfall: Ausgabe der ``repr()``-Darstellung jedes Arguments.

    So wird garantiert, dass der Programmstart auch auf restriktiven
    Konsolen niemals wegen eines UnicodeEncodeError abbricht.
    """
    # --- 1. Dateiobjekt und dessen Encoding ermitteln ---------------
    file = kwargs.get("file", sys.stdout)
    encoding = getattr(file, "encoding", None) or "utf-8"

    # --- 2. Erster Versuch – normales print ------------------------
    try:
        print(*args, **kwargs)
        return
    except UnicodeEncodeError:
        pass  # Fallback wird eingeleitet

    # --- 3. Zweiter Versuch – mit errors='replace' kodieren --------
    safe_args: List[Any] = []
    for arg in args:
        if isinstance(arg, str):
            try:
                safe_args.append(
                    arg.encode(encoding, errors="replace").decode(encoding)
                )
            except Exception:
                # Falls selbst das fehlschlägt, rohen String versuchen
                safe_args.append(str(arg))
        else:
            safe_args.append(arg)

    try:
        print(*safe_args, **kwargs)
        return
    except UnicodeEncodeError:
        pass

    # --- 4. Dritter Versuch – ASCII only ----------------------------
    ascii_args: List[Any] = []
    for arg in args:
        if isinstance(arg, str):
            try:
                ascii_args.append(
                    arg.encode("ascii", errors="replace").decode("ascii")
                )
            except Exception:
                ascii_args.append(repr(arg))
        else:
            ascii_args.append(arg)

    try:
        print(*ascii_args, **kwargs)
    except Exception:
        # --- 5. Absoluter Notfall – repr() -----
        print(*(repr(a) for a in args), **kwargs)

def _print_welcome(debug_level: int, quiet: bool) -> None:
    """Gibt eine Willkommensnachricht im Konsolen‑Modus aus.

    Unter Windows kann die Konsole (Codepage 1252) keine Emojis oder
    andere SMP‑Zeichen darstellen.  Diese Funktion erkennt, ob das
    aktuelle Ausgabegerät das Drachen‑Emoji 🐉 verarbeiten kann,
    und verwendet ansonsten einen reinen ASCII‑Titel, sodass ein
    Programmstart auch auf restriktiven Konsolen garantiert gelingt.
    """
    if quiet or debug_level == 0:
        return

    # ------------------------------------------------------------------
    # 1. Prüfen, ob stdout das Drachen‑Emoji tatsächlich ausgeben kann
    # ------------------------------------------------------------------
    use_dragon_emoji = False
    try:
        enc = (getattr(sys.stdout, "encoding", "") or "").lower()
        if enc in ("utf-8", "utf8"):
            # Probeweise ein einzelnes Zeichen ausgeben und wieder löschen
            sys.stdout.write("\U0001f409")
            sys.stdout.flush()
            sys.stdout.write("\b")      # \b = Backspace, entfernt das Zeichen
            sys.stdout.flush()
            use_dragon_emoji = True
    except (UnicodeEncodeError, UnicodeDecodeError):
        # Konsole unterstützt das Zeichen nicht – ASCII‑Fallback wird aktiv
        pass
    except Exception:
        # Jeder andere Fehler (z. B. kein stdout) wird ebenfalls toleriert
        pass

    # ------------------------------------------------------------------
    # 2. Titelzeile zusammenbauen und ausgeben
    # ------------------------------------------------------------------
    title = "🐉 DRAGON WHISPERER READY" if use_dragon_emoji else "*** DRAGON WHISPERER READY ***"

    _safe_print("\n" + "=" * 50)
    _safe_print(title)
    _safe_print("=" * 50)
    _safe_print(f"Platform: {SYSTEM} {'ARM' if IS_ARM else 'x86'}")
    _safe_print(f"Python: {sys.version.split()[0]}")
    _safe_print(f"Working Dir: {os.getcwd()}")
    _safe_print("Model: (wird beim Start geladen)")
    _safe_print("=" * 50 + "\n")

def _show_critical_error(message: str) -> None:
    """Zeigt eine kritische Fehlermeldung an (ggf. mit GUI)."""
    if IS_WINDOWS and not sys.stdin.isatty():
        try:
            import ctypes
            short_msg = message[:200] + "..." if len(message) > 200 else message
            ctypes.windll.user32.MessageBoxW(
                0,
                f"Dragon Whisperer - Critical Error\n\n{short_msg}",
                "Critical Error",
                0x10,
            )
        except Exception:
            pass
    else:
        print(f"\n💥 {message}")

def _handle_headless_mode(args: argparse.Namespace) -> int:
    """    Führt die Verarbeitung im Headless‑Modus aus (ohne GUI).
    Gibt 0 bei Erfolg zurück, sonst 1.    """
    logger = logging.getLogger("dragon")
    logger.info("🐉 Starting in headless mode...")
    if not args.url:
        logger.error("❌ --url required in headless mode")
        return 1
    try:
        PlatformUtils.check_platform_dependencies()
    except RuntimeError as e:
        _show_user_error(str(e))
        return 1
    app_settings = AppSettings.load_from_file()
    adv_settings = AdvancedSettings()
    if args.model and args.model in Config.WHISPER_MODELS:
        app_settings.default_model = args.model
        logger.info(f"Model override: {args.model}")
    elif args.model:
        logger.warning(f"⚠️ Unknown model '{args.model}', using default")
    if args.language and args.language in SUPPORTED_LANGUAGES:
        app_settings.default_language = args.language
        logger.info(f"Language override: {args.language}")
    elif args.language:
        logger.warning(f"⚠️ Unknown language '{args.language}', using default")
    ffmpeg_manager = FFmpegManager(adv_settings.config, settings=adv_settings)
    stream_manager = StreamManager(
        enable_debug=(DEBUG_LEVEL >= 1),
        use_browser_cookies=app_settings.use_browser_cookies,
        proxy=adv_settings.proxy_url,
        proxy_enabled=adv_settings.proxy_enabled,
    )
    if WHISPER_AVAILABLE:
        transcription_engine = TranscriptionEngine(adv_settings)
        logger.info(f"📁 Loading model {app_settings.default_model}...")
        if (
            transcription_engine.load_model(app_settings.default_model, set_active=True)
            is None
        ):
            logger.error("❌ Failed to load model")
            return 1
    else:
        transcription_engine = DummyTranscriptionEngine(adv_settings)
        logger.warning("⚠️ No Whisper backend, using dummy transcriptions")

    if adv_settings.translation_engine == "ollama" and OLLAMA_AVAILABLE:
        translation_engine = OllamaTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
            model=adv_settings.ollama_model,
            host=adv_settings.ollama_host,
        )
    elif adv_settings.translation_engine == "argos" and ARGOS_AVAILABLE:
        translation_engine = ArgosTranslateEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
    elif TRANSLATOR_AVAILABLE:
        translation_engine = GoogleTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
    else:
        translation_engine = DummyTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
        logger.warning("⚠️ No translation engine, using dummy")

    processor = AudioProcessor(
        None, ffmpeg_manager, adv_settings, stream_manager=stream_manager
    )
    processor.set_engines(
        transcription_engine=transcription_engine,
        translation_engine=translation_engine,
        fallback_translation_engine=None,
    )

    def info_cb(msg: str):
        logger.info(msg)

    def error_cb(msg: str):
        logger.error(msg)

    def trans_cb(res: TranscriptionResult):
        if res and res.text:
            print(f"[{datetime.now().strftime('%H:%M:%S')}] {res.text}")

    def transl_cb(res: TranslationResult):
        if res and res.translated:
            print(f"[{datetime.now().strftime('%H:%M:%S')}] → {res.translated}")

    def finished_cb():
        logger.info("Processing finished.")

    processor.start_processing(
        url=args.url,
        transcription_callback=trans_cb,
        translation_callback=transl_cb,
        info_callback=info_cb,
        error_callback=error_cb,
        finished_callback=finished_cb,
    )
    try:
        while processor._state == AudioProcessor.State.PROCESSING:
            time.sleep(0.5)
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
        processor.stop_processing(wait=True)
    finally:
        processor.dispose()
        transcription_engine.dispose()
        translation_engine.dispose()
        ffmpeg_manager.dispose()
        stream_manager.dispose()
    return 0

def main() -> int:
    """
    Hauptfunktion des Dragon Whisperer.

    Verarbeitet die Kommandozeilenargumente, initialisiert Logging und
    Plattformumgebung und startet entweder die GUI, den Headless‑Modus,
    Systemchecks, Tests oder zeigt Hilfe‑/Versionsinformationen an.

    Returns:
        0 bei erfolgreichem Programmende, sonst einen Fehlercode > 0.
    """
    args = parse_arguments()
    debug_level = 0
    debug_components: List[str] = []
    if args.debug != "0":
        if args.debug.isdigit():
            debug_level = int(args.debug)
        else:
            debug_components = args.debug.split(",")
            debug_level = 1
    configure_logging(debug_level, debug_components, args.quiet)
    setup_platform_environment()

    if args.version:
        print("🐉 Dragon Whisperer v4.1 (optimized)")
        print(f"Platform: {SYSTEM} {'ARM' if IS_ARM else 'x86'}")
        print(f"Python: {sys.version.split()[0]}")
        return 0
    if args.sysinfo:
        print_system_info_debug3()
        return 0
    if args.check:
        return _run_system_check()
    if args.test:
        return run_tests()
    if args.headless or args.url:
        if not args.url:
            print(
                "Error: --headless requires --url to specify a stream.",
                file=sys.stderr,
            )
            return 1
        try:
            PlatformUtils.check_platform_dependencies()
        except RuntimeError as e:
            _show_user_error(str(e))
            return 1
        return _handle_headless_mode(args)

    try:
        if not GUI_AVAILABLE:
            _fatal_error(
                "Tkinter ist nicht installiert.\n\n"
                "Dragon Whisperer benötigt Tkinter für die grafische Oberfläche.\n"
                "Installieren Sie es mit:\n"
                "  • Debian/Ubuntu: sudo apt install python3-tk\n"
                "  • Fedora:        sudo dnf install python3-tkinter\n"
                "  • pip install tk (falls verfügbar)\n\n"
                "Alternativ können Sie das Programm im Headless‑Modus "
                "mit --headless --url <URL> starten.",
                "Tkinter fehlt",
            )
            return 1

        logger.info("🐉 Dragon Whisperer starting...")
        logger.debug("🔍 Checking dependencies...")

        dependency_issue = False
        try:
            PlatformUtils.check_platform_dependencies()
        except RuntimeError as e:
            dependency_issue = True
            logger.warning(
                "Einige kritische Abhängigkeiten fehlen, aber die GUI kann "
                "trotzdem gestartet werden.  Nach der Installation der "
                "Komponenten steht der volle Funktionsumfang zur Verfügung.\n"
                "%s",
                e,
            )
        logger.debug(
            "✅ Dependencies OK (fehlende werden über GUI nachinstalliert)"
        )

        logger.debug("🖥️ Initializing GUI...")
        app = DragonWhispererGUI()

        if args.profile:
            try:
                profile_path = (
                    PlatformUtils.get_platform_config_dir()
                    / "profiles"
                    / f"{args.profile}.json"
                )
                if profile_path.exists():
                    with open(profile_path, "r", encoding="utf-8") as f:
                        profile_data = json.load(f)
                    for key, value in profile_data.items():
                        if hasattr(app.advanced_settings, key):
                            setattr(app.advanced_settings, key, value)
                    logger.info("✅ Profile '%s' loaded", args.profile)
                else:
                    logger.warning(
                        "⚠️ Profile '%s' not found, using defaults", args.profile
                    )
            except Exception as e:
                logger.warning("⚠️ Failed to load profile: %s", e)

        if args.url:
            def _set_url(url: str) -> None:
                if hasattr(app, "url_entry") and app.url_entry.winfo_exists():
                    app.url_entry.delete(0, "end")
                    app.url_entry.insert(0, url)
                    logger.info("📌 URL from command line: %s", url)
            app._safe_after(500, _set_url, args.url)

        if dependency_issue:
            def _open_installer() -> None:
                if (
                    hasattr(app, "show_install_dialog")
                    and not app.is_shutting_down()
                ):
                    app.show_install_dialog()
            app._safe_after(1500, _open_installer)

        if debug_level >= 1 and not args.quiet:
            _print_welcome(debug_level, args.quiet)

        if debug_level >= 3:
            print_system_info_debug3()

        logger.info("🚀 Starting main loop...")
        app.run()
        logger.info("✅ Application closed normally")

        if debug_level >= 1:
            active = threading.enumerate()
            logger.info(
                "Active threads after GUI close: %s",
                [t.name for t in active if t.is_alive()],
            )

        logger.info("Forcing immediate exit with sys.exit(0)")
        sys.exit(0)
        return 0

    except ModuleNotFoundError as e:
        missing = e.name if hasattr(e, "name") else str(e)
        _fatal_error(
            f"Das benötigte Python‑Modul '{missing}' ist nicht installiert.\n\n"
            f"Bitte installieren Sie es mit:\n"
            f"  pip install {missing}\n\n"
            f"Detaillierte Fehlermeldung:\n{e}",
            "Fehlendes Modul",
        )
        return 1

    except RuntimeError as e:
        _fatal_error(str(e), "Programmfehler")
        return 1

    except KeyboardInterrupt:
        logger.info("\n🛑 Interrupted by user")
        # sys.exit() löst den atexit‑Handler aus und sorgt für eine
        # vollständige Ressourcenfreigabe (Subprozesse, temporäre Dateien,
        # Executor‑Shutdown).  Dies ersetzt das frühere return 0, das
        # den Cleanup nicht garantierte.
        sys.exit(0)

    except Exception as e:
        logger.exception("💥 Unexpected error: %s", e)
        if debug_level >= 2:
            import traceback
            traceback.print_exc()
        _fatal_error(
            f"Ein unerwarteter Fehler ist aufgetreten:\n\n"
            f"{type(e).__name__}: {e}\n\n"
            f"Bitte überprüfen Sie die Konsole for Details.",
            "Unerwarteter Fehler",
        )
        return 2

    finally:
        logger.debug("🧹 Final minimal cleanup...")
        try:
            _EXECUTOR.shutdown(wait=True)
        except Exception as e:
            logger.exception("⚠️ Executor shutdown error: %s", e)
        gc.collect()
        logger.debug("✅ Shutdown complete")

if __name__ == "__main__":
    try:
        if "__file__" in globals():
            script_dir = os.path.dirname(os.path.abspath(__file__))
            if os.getcwd() != script_dir:
                os.chdir(script_dir)
                if DEBUG_LEVEL >= 1:
                    print(f"📁 Working directory set to: {script_dir}")
    except Exception:
        pass
    sys.exit(main())
